package com.squire;

import com.google.gson.Gson;
import com.google.gson.JsonObject;
import java.io.IOException;
import java.time.ZoneId;
import java.util.Map;
import java.util.function.Consumer;
import java.util.function.Supplier;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.HttpUrl;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;
import okhttp3.ResponseBody;

/**
 * Reads the account's summaries from the server: /api/overview (progression) and /api/activity (time played).
 */
class AccountApi
{
	/** Either the JSON or a message explaining why there isn't any. */
	static final class Result
	{
		final JsonObject json;
		final String error;

		private Result(JsonObject json, String error)
		{
			this.json = json;
			this.error = error;
		}
	}

	private final OkHttpClient http;
	private final Gson gson;
	private final Supplier<String> endpoint;
	private final Supplier<String> token;
	private final Supplier<String> accountName;

	AccountApi(OkHttpClient http, Gson gson, Supplier<String> endpoint, Supplier<String> token, Supplier<String> accountName)
	{
		this.http = http;
		this.gson = gson;
		this.endpoint = endpoint;
		this.token = token;
		this.accountName = accountName;
	}

	/** Progression summary. Calls back on an OkHttp thread. */
	void overview(Consumer<Result> callback)
	{
		get("api/overview", Map.of(), callback);
	}

	/** Time played for a day, week or month (offset 0 = the current one), in this computer's timezone. */
	void activity(String range, int offset, Consumer<Result> callback)
	{
		get("api/activity", Map.of("range", range, "offset", String.valueOf(offset), "tz", ZoneId.systemDefault().getId()), callback);
	}

	/** Gains over a period: everything gained, or one metric's values and per-day gains (metric null for the list). */
	void gained(String period, String metric, Consumer<Result> callback)
	{
		Map<String, String> q = new java.util.HashMap<>();
		q.put("period", period);
		if (metric != null)
		{
			q.put("metric", metric);
		}
		get("api/gained", q, callback);
	}

	/** A Progress detail page: skills, quests, combat-achievements, diaries, collection-log, kill-counts or stats. */
	void progress(String view, Consumer<Result> callback)
	{
		get("api/progress", Map.of("view", view), callback);
	}

	/** One boss over a period (day, week, month, year): count history, time, kills per hour, PBs and loot. */
	void boss(String name, String period, Consumer<Result> callback)
	{
		get("api/progress", Map.of("boss", name, "period", period), callback);
	}

	/** The profile editor's data for the logged-in character: settings, options (with what's unlocked), share link. */
	void profile(Consumer<Result> callback)
	{
		send("GET", "api/me/profile" + accountQuery("?"), null, callback);
	}

	/** Change the profile: {public?, background?, frame?, emblem?, highlights?: [ids], gear?: {slot: id|null}}. */
	void editProfile(JsonObject edit, Consumer<Result> callback)
	{
		send("PATCH", "api/me/profile" + accountQuery("?"), edit, callback);
	}

	/** The character's own items: worn in an equipment slot (slot >= 0), or anything for highlights (slot < 0). */
	void profileItems(int slot, String query, Consumer<Result> callback)
	{
		String q = java.net.URLEncoder.encode(query == null ? "" : query, java.nio.charset.StandardCharsets.UTF_8);
		send("GET", "api/me/profile/items?q=" + q + (slot >= 0 ? "&slot=" + slot : "") + accountQuery("&"), null, callback);
	}

	/** Upload the avatar render (PNG) for gear revision {rev}. */
	void uploadAvatar(byte[] png, int rev, Consumer<Result> callback)
	{
		JsonObject body = new JsonObject();
		body.addProperty("png", java.util.Base64.getEncoder().encodeToString(png));
		body.addProperty("rev", rev);
		send("PUT", "api/me/profile/avatar" + accountQuery("?"), body, callback);
	}

	/** A one-time link that opens the profile editor in the browser. */
	void profileLink(Consumer<Result> callback)
	{
		send("POST", "api/me/profile/link" + accountQuery("?"), null, callback);
	}

	/** The Set up page: {synced, history: waiting|importing|done|none, bank, collectionLog}. */
	void setup(Consumer<Result> callback)
	{
		get("api/setup", Map.of(), callback);
	}

	/** The player's plan, checked against their account ({ plan: null } when they have none). */
	void plan(Consumer<Result> callback)
	{
		get("api/plan", Map.of(), callback);
	}

	/** Tick a step or checkpoint, remove a checkpoint, or delete the plan: {op, checkpoint?, step?}. */
	void editPlan(JsonObject edit, Consumer<Result> callback)
	{
		String name = accountName.get();
		String query = name == null || name.isBlank() ? "" : "?account=" + java.net.URLEncoder.encode(name, java.nio.charset.StandardCharsets.UTF_8);
		send("PATCH", "api/plan" + query, edit, callback);
	}

	/** Re-evaluate a gear view after the player changes a slot (bonuses, DPS, swaps, export). */
	void gear(JsonObject request, Consumer<Result> callback)
	{
		String name = accountName.get();
		String query = name == null || name.isBlank() ? "" : "?account=" + java.net.URLEncoder.encode(name, java.nio.charset.StandardCharsets.UTF_8);
		send("POST", "api/gear" + query, request, callback);
	}

	/** Forget part of the player's data on the server: a kind (bank, worn, storage, location, loot, activity, clog) or one item. */
	void forget(String kind, String item, Consumer<Result> callback)
	{
		StringBuilder q = new StringBuilder("api/me/data?");
		String name = accountName.get();
		if (name != null && !name.isBlank())
		{
			q.append("account=").append(java.net.URLEncoder.encode(name, java.nio.charset.StandardCharsets.UTF_8)).append('&');
		}
		q.append(kind != null ? "kind=" + kind : "item=" + java.net.URLEncoder.encode(item, java.nio.charset.StandardCharsets.UTF_8));
		send("DELETE", q.toString(), null, callback);
	}

	/** Upload an observed session's summary for review. */
	void uploadSession(JsonObject summary, Consumer<Result> callback)
	{
		String name = accountName.get();
		String query = name == null || name.isBlank() ? "" : "?account=" + java.net.URLEncoder.encode(name, java.nio.charset.StandardCharsets.UTF_8);
		send("POST", "api/sessions" + query, summary, callback);
	}

	/** This install's daily allowance and linked accounts. */
	void me(Consumer<Result> callback)
	{
		send("GET", "api/me", null, callback);
	}

	/** Delete this install and everything it synced from the server. */
	void deleteMe(Consumer<Result> callback)
	{
		send("DELETE", "api/me", null, callback);
	}

	/** Use the player's own AI Gateway key (null removes it). */
	void setGatewayKey(String key, Consumer<Result> callback)
	{
		JsonObject body = new JsonObject();
		body.addProperty("key", key);
		send("PUT", "api/me/gateway-key", body, callback);
	}

	/** Join the private beta with an invite code. */
	void redeemInvite(String code, Consumer<Result> callback)
	{
		JsonObject body = new JsonObject();
		body.addProperty("code", code);
		send("POST", "api/me/invite", body, callback);
	}

	/** The player's own provider keys: {providers: [{id, label}], keys: [{provider, label, models}]} (never the keys). */
	void providerKeys(Consumer<Result> callback)
	{
		send("GET", "api/me/keys", null, callback);
	}

	/** Check and save a provider key (sent once, stored encrypted on the server). */
	void saveProviderKey(String provider, String key, Consumer<Result> callback)
	{
		JsonObject body = new JsonObject();
		body.addProperty("provider", provider);
		body.addProperty("key", key);
		send("PUT", "api/me/keys", body, callback);
	}

	void removeProviderKey(String provider, Consumer<Result> callback)
	{
		send("DELETE", "api/me/keys?provider=" + java.net.URLEncoder.encode(provider, java.nio.charset.StandardCharsets.UTF_8), null, callback);
	}

	/** A one-time code (10 minutes) for connecting another AI app, plus the MCP URL to add. */
	void pairingCode(Consumer<Result> callback)
	{
		send("POST", "api/me/pairing", null, callback);
	}

	/** What Squire remembers about the logged-in account: {notes: [{id, kind, text, done_at}], chats: [{summary, at}]}. */
	void notes(Consumer<Result> callback)
	{
		send("GET", "api/me/notes" + accountQuery("?"), null, callback);
	}

	/** Forget one note. */
	void forgetNote(int id, Consumer<Result> callback)
	{
		send("DELETE", "api/me/notes?id=" + id + accountQuery("&"), null, callback);
	}

	/** Mark a goal done (kept as a record). */
	void finishNote(int id, Consumer<Result> callback)
	{
		JsonObject body = new JsonObject();
		body.addProperty("done", true);
		send("PATCH", "api/me/notes?id=" + id + accountQuery("&"), body, callback);
	}

	private String accountQuery(String sep)
	{
		String name = accountName.get();
		return name == null || name.isBlank() ? "" : sep + "account=" + java.net.URLEncoder.encode(name, java.nio.charset.StandardCharsets.UTF_8);
	}

	/** AI apps connected to this install. */
	void connections(Consumer<Result> callback)
	{
		send("GET", "api/me/connections", null, callback);
	}

	/** Disconnect an AI app: its tokens stop working. */
	void disconnect(String appId, Consumer<Result> callback)
	{
		send("DELETE", "api/me/connections?app=" + java.net.URLEncoder.encode(appId, java.nio.charset.StandardCharsets.UTF_8), null, callback);
	}

	/** Sign this install up; the reply carries its token. No token needed. */
	void register(Consumer<Result> callback)
	{
		HttpUrl base = HttpUrl.parse(endpoint.get().trim());
		if (base == null)
		{
			callback.accept(new Result(null, "The server URL isn't valid."));
			return;
		}
		Request request = new Request.Builder()
			.url(base.newBuilder().addPathSegments("api/register").build())
			.post(okhttp3.RequestBody.create(okhttp3.MediaType.parse("application/json"), "{}"))
			.build();
		http.newCall(request).enqueue(handler(callback));
	}

	private void send(String method, String path, JsonObject body, Consumer<Result> callback)
	{
		HttpUrl base = HttpUrl.parse(endpoint.get().trim());
		if (base == null || token.get().isBlank())
		{
			callback.accept(new Result(null, "Squire isn't turned on yet."));
			return;
		}
		okhttp3.RequestBody payload = body == null ? null : okhttp3.RequestBody.create(okhttp3.MediaType.parse("application/json"), gson.toJson(body));
		Request request = new Request.Builder()
			.url(withPath(base, path))
			.header("Authorization", "Bearer " + token.get().trim())
			.method(method, payload == null && !method.equals("GET") && !method.equals("DELETE") ? okhttp3.RequestBody.create(null, new byte[0]) : payload)
			.build();
		http.newCall(request).enqueue(handler(callback));
	}

	/** base + "a/b?x=y" (the query is kept, not encoded into the path). */
	private static HttpUrl withPath(HttpUrl base, String path)
	{
		int q = path.indexOf('?');
		HttpUrl.Builder b = base.newBuilder().addPathSegments(q < 0 ? path : path.substring(0, q));
		if (q >= 0)
		{
			b.encodedQuery(path.substring(q + 1));
		}
		return b.build();
	}

	private Callback handler(Consumer<Result> callback)
	{
		return new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				callback.accept(new Result(null, "Couldn't reach the server."));
			}

			@Override
			public void onResponse(Call call, Response response)
			{
				try (response)
				{
					ResponseBody body = response.body();
					String text = body == null ? "" : body.string();
					JsonObject json = text.isEmpty() ? null : gson.fromJson(text, JsonObject.class);
					if (response.isSuccessful())
					{
						callback.accept(new Result(json, null));
					}
					else
					{
						String error = json != null && json.has("error") ? json.get("error").getAsString() : "Server returned " + response.code() + ".";
						callback.accept(new Result(null, error));
					}
				}
				catch (IOException | RuntimeException e)
				{
					callback.accept(new Result(null, "Couldn't read the server's reply."));
				}
			}
		};
	}

	private String notFoundReason(ResponseBody body)
	{
		try
		{
			JsonObject json = body == null ? null : gson.fromJson(body.string(), JsonObject.class);
			if (json != null && json.has("error") && json.get("error").isJsonPrimitive())
			{
				String error = json.get("error").getAsString();
				return error.startsWith("No synced account")
					? "Nothing synced for this character yet. Log in and it syncs automatically, or press **Update now** in settings."
					: error;
			}
		}
		catch (IOException | RuntimeException e)
		{
			// Not JSON: the server doesn't have this page
		}
		return "This page needs a newer Squire server. It should work after the next update.";
	}

	private void get(String path, Map<String, String> query, Consumer<Result> callback)
	{
		HttpUrl base = HttpUrl.parse(endpoint.get().trim());
		if (base == null || token.get().isBlank())
		{
			callback.accept(new Result(null, "Turn on Squire on the Home page to sync your account."));
			return;
		}
		HttpUrl.Builder url = base.newBuilder().addPathSegments(path);
		query.forEach(url::addQueryParameter);
		String name = accountName.get();
		if (name != null && !name.isBlank())
		{
			url.addQueryParameter("account", name);
		}
		Request request = new Request.Builder()
			.url(url.build())
			.header("Authorization", "Bearer " + token.get().trim())
			.build();
		http.newCall(request).enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				callback.accept(new Result(null, "Couldn't reach the server."));
			}

			@Override
			public void onResponse(Call call, Response response) throws IOException
			{
				try (response)
				{
					ResponseBody body = response.body();
					if (response.code() == 401)
					{
						callback.accept(new Result(null, "The server didn't recognise this install. Turn Squire off and on again in settings."));
					}
					else if (response.code() == 404)
					{
						// The server says why (e.g. no account synced yet); a 404 without a reason means the page is newer than the server
						callback.accept(new Result(null, notFoundReason(body)));
					}
					else if (!response.isSuccessful() || body == null)
					{
						callback.accept(new Result(null, "Server returned " + response.code() + "."));
					}
					else
					{
						callback.accept(new Result(gson.fromJson(body.string(), JsonObject.class), null));
					}
				}
				catch (RuntimeException e)
				{
					callback.accept(new Result(null, "Couldn't read the server's reply."));
				}
			}
		});
	}
}

package com.squire;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.util.List;
import java.util.Map;
import java.util.function.Consumer;
import javax.swing.JComponent;
import net.runelite.client.ui.FontManager;

/** The Activity page's visuals: a segmented range picker, a proportional bar and a stacked column chart. */
final class ActivityCharts
{
	/** One activity's share: minutes played or XP gained, depending on the metric shown. */
	static final class Part
	{
		final String name;
		final double value;
		final Color color;

		Part(String name, double value, Color color)
		{
			this.name = name;
			this.value = value;
			this.color = color;
		}
	}

	/** One column: a label under it, an optional second line (the date), and its stacked parts. */
	static final class Column
	{
		final String label;
		final String sub;
		final String tooltip;
		final boolean current;
		final boolean future;
		final List<Part> parts;

		Column(String label, String sub, String tooltip, boolean current, boolean future, List<Part> parts)
		{
			this.label = label;
			this.sub = sub;
			this.tooltip = tooltip;
			this.current = current;
			this.future = future;
			this.parts = parts;
		}

		double total()
		{
			return parts.stream().mapToDouble(p -> p.value).sum();
		}
	}

	/** Pill-shaped options in a sunken track, e.g. Day / Week / Month. */
	static final class Segmented extends JComponent
	{
		private final String[] options;
		private final Consumer<Integer> onPick;
		private int selected;
		private int hover = -1;

		private final Dimension size;

		Segmented(String[] options, int selected, Consumer<Integer> onPick)
		{
			this(options, selected, new Dimension(200, 32), onPick);
		}

		Segmented(String[] options, int selected, Dimension size, Consumer<Integer> onPick)
		{
			this.size = size;
			this.options = options;
			this.selected = selected;
			this.onPick = onPick;
			setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
			MouseAdapter m = new MouseAdapter()
			{
				@Override
				public void mouseReleased(MouseEvent e)
				{
					// On release rather than click: Swing drops a click if the pointer moves a pixel while pressed
					if (!javax.swing.SwingUtilities.isLeftMouseButton(e) || !e.getComponent().contains(e.getPoint()))
					{
						return;
					}
					int i = indexAt(e.getX());
					if (i != Segmented.this.selected)
					{
						Segmented.this.selected = i;
						repaint();
						onPick.accept(i);
					}
				}

				@Override
				public void mouseMoved(MouseEvent e)
				{
					int i = indexAt(e.getX());
					if (i != hover)
					{
						hover = i;
						repaint();
					}
				}

				@Override
				public void mouseExited(MouseEvent e)
				{
					hover = -1;
					repaint();
				}
			};
			addMouseListener(m);
			addMouseMotionListener(m);
		}

		void setSelected(int i)
		{
			selected = i;
			repaint();
		}

		private int indexAt(int x)
		{
			return Math.max(0, Math.min(options.length - 1, x * options.length / Math.max(1, getWidth())));
		}

		@Override
		public Dimension getPreferredSize()
		{
			return size;
		}

		@Override
		public Dimension getMaximumSize()
		{
			return size;
		}

		@Override
		protected void paintComponent(Graphics g)
		{
			Graphics2D g2 = (Graphics2D) g.create();
			g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
			int w = getWidth(), h = getHeight();
			g2.setColor(ChatComponents.BASE_BG);
			Pixel.fill(g2, 0, 0, w, h, 5);
			g2.setColor(ChatComponents.OUTLINE);
			Pixel.draw(g2, 0, 0, w, h, 5);

			Font font = h < 28 ? FontManager.getRunescapeSmallFont() : FontManager.getRunescapeFont();
			FontMetrics fm = g2.getFontMetrics(font);
			g2.setFont(font);
			double seg = (w - 4) / (double) options.length;
			for (int i = 0; i < options.length; i++)
			{
				int x = (int) Math.round(2 + seg * i);
				int sw = (int) Math.round(2 + seg * (i + 1)) - x;
				if (i == selected)
				{
					g2.setColor(ChatComponents.OUTLINE);
					Pixel.fill(g2, x, 2, sw, h - 4, 4);
					g2.setColor(ChatComponents.PANEL_BG);
					Pixel.fill(g2, x + 1, 3, sw - 2, h - 6, 3);
					g2.setColor(ChatComponents.HAIRLINE);
					Pixel.draw(g2, x + 1, 3, sw - 2, h - 6, 3);
				}
				g2.setColor(i == selected || i == hover ? Color.WHITE : ChatComponents.MUTED);
				String s = options[i];
				g2.drawString(s, x + (sw - fm.stringWidth(s)) / 2, (h - fm.getHeight()) / 2 + fm.getAscent());
			}
			g2.dispose();
		}
	}

	/** Horizontal bar split into rounded pills, one per part, sized by share. */
	static final class ShareBar extends JComponent
	{
		private static final int HEIGHT = 8;
		private static final int GAP = 3;
		private final List<Part> parts;

		ShareBar(List<Part> parts)
		{
			this.parts = parts;
		}

		@Override
		public Dimension getPreferredSize()
		{
			return new Dimension(100, HEIGHT);
		}

		@Override
		public Dimension getMaximumSize()
		{
			return new Dimension(Integer.MAX_VALUE, HEIGHT);
		}

		@Override
		protected void paintComponent(Graphics g)
		{
			Graphics2D g2 = (Graphics2D) g.create();
			g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
			double total = parts.stream().mapToDouble(p -> p.value).sum();
			int w = getWidth();
			if (total <= 0)
			{
				g2.setColor(ChatComponents.BASE_BG);
				Pixel.fill(g2, 0, 0, w, HEIGHT, HEIGHT / 2.0);
				g2.dispose();
				return;
			}
			double usable = w - GAP * (parts.size() - 1);
			double x = 0;
			for (Part p : parts)
			{
				double pw = Math.max(HEIGHT, usable * p.value / total);
				g2.setColor(p.color);
				g2.fill(Pixel.shape(x, 0, Math.min(pw, w - x), HEIGHT, HEIGHT / 2.0));
				x += pw + GAP;
				if (x >= w)
				{
					break;
				}
			}
			g2.dispose();
		}
	}

	/**
	 * Stacked columns with horizontal gridlines and an axis on the right. The current column (today / this hour)
	 * gets a highlight behind it and its date in an accent circle.
	 */
	static final class ColumnChart extends JComponent
	{
		private static final int PLOT_HEIGHT = 110;
		private static final int AXIS = 26;
		private final List<Column> columns;
		private final double max;
		private final boolean xp;
		private final boolean count;

		/** xp: the columns hold XP rather than minutes (changes the axis scale and labels). */
		ColumnChart(List<Column> columns, boolean xp)
		{
			this(columns, xp, false);
		}

		/** count: the columns hold plain counts (kills, completions), with a whole-number axis. */
		ColumnChart(List<Column> columns, boolean xp, boolean count)
		{
			this.columns = columns;
			this.xp = xp;
			this.count = count;
			double biggest = columns.stream().mapToDouble(Column::total).max().orElse(0);
			this.max = count ? niceCount(biggest) : xp ? niceXp(biggest) : niceMax(biggest);
			setToolTipText("");
		}

		/** An even number at least 2 (so the middle gridline is whole), rounded to 1, 2 or 5 times a power of ten above 10. */
		private static double niceCount(double value)
		{
			double v = Math.max(2, Math.ceil(value));
			if (v <= 10)
			{
				return v % 2 == 0 ? v : v + 1;
			}
			double pow = Math.pow(10, Math.floor(Math.log10(v)));
			for (double m : new double[]{1, 2, 5, 10})
			{
				if (v <= m * pow)
				{
					return m * pow;
				}
			}
			return 10 * pow;
		}

		/** Round up to 1, 2 or 5 times a power of ten (at least 10K). */
		private static double niceXp(double value)
		{
			double v = Math.max(10_000, value);
			double pow = Math.pow(10, Math.floor(Math.log10(v)));
			for (double m : new double[]{1, 1.5, 2, 2.5, 3, 4, 5, 6, 8})
			{
				if (v <= m * pow)
				{
					return m * pow;
				}
			}
			return 10 * pow;
		}

		/** Round the axis up to a whole number of hours (or 30 minutes for short periods). */
		private static double niceMax(double minutes)
		{
			if (minutes <= 30)
			{
				return 30;
			}
			if (minutes <= 60)
			{
				return 60;
			}
			int hours = (int) Math.ceil(minutes / 60);
			int[] steps = {2, 4, 6, 8, 12, 16, 20, 24};
			for (int s : steps)
			{
				if (hours <= s)
				{
					return s * 60;
				}
			}
			return hours * 60;
		}

		private boolean hasSubs()
		{
			return columns.stream().anyMatch(c -> c.sub != null);
		}

		@Override
		public Dimension getPreferredSize()
		{
			int line = getFontMetrics(FontManager.getRunescapeSmallFont()).getHeight();
			return new Dimension(200, PLOT_HEIGHT + 8 + line + (hasSubs() ? line + 6 : 0));
		}

		@Override
		public Dimension getMaximumSize()
		{
			return new Dimension(Integer.MAX_VALUE, getPreferredSize().height);
		}

		private double slot()
		{
			return (getWidth() - AXIS) / (double) Math.max(1, columns.size());
		}

		@Override
		public String getToolTipText(MouseEvent e)
		{
			int i = (int) (e.getX() / slot());
			return i >= 0 && i < columns.size() ? columns.get(i).tooltip : null;
		}

		@Override
		protected void paintComponent(Graphics g)
		{
			Graphics2D g2 = (Graphics2D) g.create();
			g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
			Font small = FontManager.getRunescapeSmallFont();
			FontMetrics fm = g2.getFontMetrics(small);
			g2.setFont(small);
			int plotW = getWidth() - AXIS;
			int top = 6;
			int bottom = top + PLOT_HEIGHT - 6;
			double slot = slot();
			boolean dense = columns.size() > 10;
			double barW = dense ? Math.max(2, slot - 2) : Math.min(26, slot * 0.62);
			double radius = Math.min(6, barW / 2);

			// Current column highlight
			for (int i = 0; i < columns.size(); i++)
			{
				if (columns.get(i).current && !dense)
				{
					g2.setColor(ChatComponents.HOVER_BG);
					double hw = Math.min(slot - 2, barW + 12);
					g2.fill(Pixel.shape(slot * i + (slot - hw) / 2, 0, hw, getHeight(), 4));
				}
			}

			// Gridlines: top, middle, bottom, labelled on the right
			g2.setStroke(new BasicStroke(1f));
			for (int k = 0; k <= 2; k++)
			{
				int y = bottom - (bottom - top) * k / 2;
				g2.setColor(k == 0 ? ChatComponents.BORDER : ChatComponents.OUTLINE);
				g2.drawLine(0, y, plotW, y);
				String label = k == 0 ? "0" : count ? Ui.shortNumber(max * k / 2) : xp ? Ui.shortNumber(max * k / 2) : axisLabel(max * k / 2);
				g2.setColor(ChatComponents.MUTED);
				g2.drawString(label, getWidth() - fm.stringWidth(label), y + fm.getAscent() / 2 - 1);
			}

			// Stacked columns, rounded at the top
			for (int i = 0; i < columns.size(); i++)
			{
				Column c = columns.get(i);
				double x = slot * i + (slot - barW) / 2;
				double total = c.total();
				if (total <= 0)
				{
					continue;
				}
				double h = Math.max(2, (bottom - top) * Math.min(1, total / max));
				java.awt.Shape clip = Pixel.shape(x, bottom - h, barW, h + radius, radius);
				Graphics2D bar = (Graphics2D) g2.create();
				bar.clip(new java.awt.Rectangle((int) Math.floor(x) - 1, 0, (int) Math.ceil(barW) + 2, bottom));
				bar.clip(clip);
				double y = bottom;
				for (Part p : c.parts)
				{
					double ph = h * p.value / total;
					bar.setColor(p.color);
					bar.fill(new java.awt.geom.Rectangle2D.Double(x, y - ph, barW, ph + 0.5));
					y -= ph;
				}
				bar.dispose();
			}

			// Labels
			int labelY = bottom + 8 + fm.getAscent();
			for (int i = 0; i < columns.size(); i++)
			{
				Column c = columns.get(i);
				double cx = slot * i + slot / 2;
				if (c.label != null && !c.label.isEmpty())
				{
					g2.setColor(c.current ? Color.WHITE : c.future ? ChatComponents.BORDER : ChatComponents.MUTED);
					int lx = (int) Math.round(cx - fm.stringWidth(c.label) / 2.0);
					g2.drawString(c.label, Math.max(0, Math.min(plotW - fm.stringWidth(c.label), lx)), labelY);
				}
				if (c.sub != null)
				{
					int subY = labelY + fm.getHeight() + 4;
					if (c.current)
					{
						int d = Math.max(fm.getHeight() + 2, fm.stringWidth(c.sub) + 8);
						g2.setColor(ChatComponents.ACCENT);
						Pixel.fill(g2, (int) Math.round(cx - d / 2.0), subY - fm.getAscent() - (d - fm.getHeight()) / 2 - 1, d, d, d / 2.0);
						g2.setColor(Color.WHITE);
					}
					else
					{
						g2.setColor(c.future ? ChatComponents.BORDER : ChatComponents.MUTED);
					}
					g2.drawString(c.sub, (int) Math.round(cx - fm.stringWidth(c.sub) / 2.0), subY);
				}
			}
			g2.dispose();
		}

		private static String axisLabel(double minutes)
		{
			return minutes >= 60 ? (minutes % 60 == 0 ? (int) (minutes / 60) + "h" : String.format("%.1fh", minutes / 60)) : (int) minutes + "m";
		}
	}

	/** Tooltip for a column: its total, then each part. */
	/**
	 * A labelled horizontal bar for ranked lists (XP by skill, kills by boss, loot by source): the name and value on one
	 * line, a pixel bar under it scaled to the biggest row, and an optional muted detail line.
	 */
	static final class HBar extends JComponent
	{
		private final String name;
		private final String value;
		private final String detail;
		private final double fraction;
		private final Color color;
		private final java.awt.image.BufferedImage icon;

		HBar(String name, String value, String detail, double fraction, Color color, java.awt.image.BufferedImage icon)
		{
			this.name = name;
			this.value = value;
			this.detail = detail;
			this.fraction = Math.max(0, Math.min(1, fraction));
			this.color = color;
			this.icon = icon;
		}

		private int line()
		{
			return getFontMetrics(FontManager.getRunescapeSmallFont()).getHeight();
		}

		@Override
		public Dimension getPreferredSize()
		{
			return new Dimension(200, line() + 8 + (detail != null ? line() : 0) + 2);
		}

		@Override
		public Dimension getMaximumSize()
		{
			return new Dimension(Integer.MAX_VALUE, getPreferredSize().height);
		}

		@Override
		protected void paintComponent(Graphics g)
		{
			Graphics2D g2 = (Graphics2D) g.create();
			g2.setFont(FontManager.getRunescapeSmallFont());
			FontMetrics fm = g2.getFontMetrics();
			int x = 0;
			if (icon != null)
			{
				int s = fm.getHeight() + 6;
				g2.drawImage(icon, 0, 0, s, s * icon.getHeight() / Math.max(1, icon.getWidth()), null);
				x = s + 6;
			}
			int w = getWidth() - x;
			g2.setColor(ChatComponents.MUTED.brighter());
			g2.drawString(name, x, fm.getAscent());
			g2.setColor(Color.WHITE);
			g2.drawString(value, getWidth() - fm.stringWidth(value), fm.getAscent());
			int by = fm.getHeight() + 2;
			g2.setColor(ChatComponents.BASE_BG);
			g2.fillRect(x, by, w, 4);
			g2.setColor(color);
			g2.fillRect(x, by, (int) Math.max(2, Math.round(w * fraction)), 4);
			g2.setColor(new Color(255, 255, 255, 50));
			g2.fillRect(x, by, (int) Math.max(2, Math.round(w * fraction)), 1);
			if (detail != null)
			{
				g2.setColor(ChatComponents.MUTED);
				g2.drawString(detail, x, by + 6 + fm.getAscent());
			}
			g2.dispose();
		}
	}

	/** A stat tile: small label, big value, and the change against the previous period (green up, red down). */
	static final class Tile extends JComponent
	{
		private final String label;
		private final String value;
		private final Integer changePct;

		Tile(String label, String value, Integer changePct)
		{
			this.label = label;
			this.value = value;
			this.changePct = changePct;
		}

		@Override
		public Dimension getPreferredSize()
		{
			int small = getFontMetrics(FontManager.getRunescapeSmallFont()).getHeight();
			int big = getFontMetrics(FontManager.getRunescapeBoldFont().deriveFont(18f)).getHeight();
			return new Dimension(100, 8 + small + big + small + 8);
		}

		@Override
		protected void paintComponent(Graphics g)
		{
			Graphics2D g2 = (Graphics2D) g.create();
			g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
			g2.setColor(ChatComponents.CARD_BG);
			Pixel.fill(g2, 0, 0, getWidth(), getHeight(), 6);
			Pixel.bevel(g2, 0, 0, getWidth(), getHeight(), 6, ChatComponents.CARD_LIGHT, ChatComponents.CARD_DARK);
			java.awt.Font small = FontManager.getRunescapeSmallFont();
			java.awt.Font big = FontManager.getRunescapeBoldFont().deriveFont(18f);
			FontMetrics fs = g2.getFontMetrics(small), fb = g2.getFontMetrics(big);
			int y = 8 + fs.getAscent();
			g2.setFont(small);
			g2.setColor(ChatComponents.MUTED);
			g2.drawString(label, 9, y);
			y += fs.getDescent() + fb.getAscent();
			g2.setFont(big);
			g2.setColor(Color.WHITE);
			g2.drawString(value, 9, y);
			if (changePct != null)
			{
				y += fb.getDescent() + fs.getAscent();
				g2.setFont(small);
				g2.setColor(changePct >= 0 ? new Color(0x5FBF6A) : new Color(0xE06A5A));
				g2.drawString((changePct >= 0 ? "+" : "") + changePct + "% vs before", 9, y);
			}
			g2.dispose();
		}
	}

	static String tooltip(String title, List<Part> parts, java.util.function.DoubleFunction<String> format)
	{
		double total = parts.stream().mapToDouble(p -> p.value).sum();
		StringBuilder sb = new StringBuilder("<html><b>").append(MarkdownLite.escape(title)).append("</b>: ").append(format.apply(total));
		for (Part p : parts)
		{
			sb.append("<br>").append(MarkdownLite.escape(p.name)).append(": ").append(format.apply(p.value));
		}
		return sb.append("</html>").toString();
	}

	static Map<String, Color> colorMap(List<String> rankedNames)
	{
		Map<String, Color> out = new java.util.LinkedHashMap<>();
		for (int i = 0; i < rankedNames.size(); i++)
		{
			out.put(rankedNames.get(i), Ui.activityColor(i, rankedNames.get(i)));
		}
		return out;
	}

	private ActivityCharts()
	{
	}
}

package com.squire;

import java.util.EnumMap;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.Set;
import net.runelite.api.Actor;
import net.runelite.api.Client;
import net.runelite.api.EquipmentInventorySlot;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.NPC;
import net.runelite.api.Player;
import net.runelite.api.Skill;
import net.runelite.api.gameval.InventoryID;

/**
 * Works out what the player spent each minute doing, for the Activity page.
 * A minute goes to the monster they were fighting, else the skill that gained the most XP, else "Other"
 * (questing, banking, running around). Idle minutes aren't counted. Client thread only.
 */
class ActivityTracker
{
	/** Minutes with any NPC fighting at least this many ticks (of 100) count as fighting it. */
	private static final int FIGHT_TICKS = 5;
	/** Minutes with input on at least this many ticks count as "Other" when nothing else happened. */
	private static final int ACTIVE_TICKS = 10;
	/** 5 minutes, in client ticks (20ms). */
	private static final int IDLE_CLIENT_TICKS = 15_000;
	private static final Set<Skill> MELEE_RANGED = Set.of(Skill.ATTACK, Skill.STRENGTH, Skill.DEFENCE, Skill.RANGED);

	private final Map<Skill, Integer> lastXp = new EnumMap<>(Skill.class);
	private long minute = -1;
	private final Map<String, Integer> npcTicks = new HashMap<>();
	// Ticks spent fighting with each weapon this minute, for the favourite weapon on the Progress page
	private final Map<String, Integer> weaponTicks = new HashMap<>();
	private final Map<Skill, Integer> xp = new EnumMap<>(Skill.class);
	private int activeTicks;

	/** Call on every game tick while logged in; returns the finished minute's record when a minute rolls over. */
	Map<String, Object> tick(Client client)
	{
		long now = System.currentTimeMillis() / 60_000;
		Map<String, Object> finished = null;
		if (now != minute)
		{
			finished = minute >= 0 ? classify(minute) : null;
			minute = now;
			npcTicks.clear();
			weaponTicks.clear();
			xp.clear();
			activeTicks = 0;
		}

		Player local = client.getLocalPlayer();
		Actor target = local == null ? null : local.getInteracting();
		if (target instanceof NPC && ((NPC) target).getCombatLevel() > 0 && target.getName() != null)
		{
			npcTicks.merge(target.getName(), 1, Integer::sum);
			String weapon = wieldedWeapon(client);
			if (weapon != null)
			{
				weaponTicks.merge(weapon, 1, Integer::sum);
			}
		}
		if (Math.min(client.getKeyboardIdleTicks(), client.getMouseIdleTicks()) < IDLE_CLIENT_TICKS)
		{
			activeTicks++;
		}
		return finished;
	}

	/** The weapon in the weapon slot, by name, or null when unarmed. */
	private static String wieldedWeapon(Client client)
	{
		ItemContainer worn = client.getItemContainer(InventoryID.WORN);
		Item weapon = worn == null ? null : worn.getItem(EquipmentInventorySlot.WEAPON.getSlotIdx());
		if (weapon == null || weapon.getId() <= 0)
		{
			return null;
		}
		String name = client.getItemDefinition(weapon.getId()).getName();
		return name == null || name.isEmpty() || "null".equals(name) ? null : name;
	}

	void onXp(Skill skill, int total)
	{
		Integer previous = lastXp.put(skill, total);
		if (previous != null && total > previous)
		{
			xp.merge(skill, total - previous, Integer::sum);
		}
	}

	/** Forget XP baselines and the partial minute (e.g. on logout or hopping accounts). */
	void reset()
	{
		lastXp.clear();
		minute = -1;
		npcTicks.clear();
		weaponTicks.clear();
		xp.clear();
		activeTicks = 0;
	}

	/** What this minute looks like so far ("Vorkath", "Woodcutting", "Other"), or null if idle. */
	String current()
	{
		Map<String, Object> m = minute >= 0 ? classify(minute) : null;
		return m == null ? null : (String) m.get("activity");
	}

	private Map<String, Object> classify(long minuteIndex)
	{
		int totalXp = xp.values().stream().mapToInt(Integer::intValue).sum();
		String activity;
		String category;

		Map.Entry<String, Integer> npc = npcTicks.entrySet().stream().max(Map.Entry.comparingByValue()).orElse(null);
		Map.Entry<Skill, Integer> skill = xp.entrySet().stream()
			.filter(e -> e.getKey() != Skill.HITPOINTS)
			.max(Map.Entry.comparingByValue())
			.orElse(null);
		if (npc != null && npc.getValue() >= FIGHT_TICKS)
		{
			activity = npc.getKey();
			category = "combat";
		}
		else if (skill != null && MELEE_RANGED.contains(skill.getKey()))
		{
			activity = "Combat";
			category = "combat";
		}
		else if (skill != null)
		{
			activity = skill.getKey().getName();
			category = "skilling";
		}
		else if (activeTicks >= ACTIVE_TICKS)
		{
			activity = "Other";
			category = "other";
		}
		else
		{
			return null; // idle
		}

		Map<String, Object> record = new LinkedHashMap<>();
		record.put("ts", minuteIndex * 60_000);
		record.put("activity", activity);
		record.put("category", category);
		record.put("xp", totalXp);
		if ("combat".equals(category))
		{
			weaponTicks.entrySet().stream().max(Map.Entry.comparingByValue()).ifPresent(w -> record.put("weapon", w.getKey()));
		}
		return record;
	}
}

package com.squire;

import static com.squire.Ui.*;

import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.squire.ActivityCharts.Column;
import com.squire.ActivityCharts.Part;
import com.squire.ChatComponents.Align;
import com.squire.ChatComponents.Bubble;
import com.squire.ChatComponents.MessageList;
import com.squire.ChatComponents.Surface;
import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Dimension;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import javax.swing.BorderFactory;
import javax.swing.Box;
import javax.swing.JButton;
import javax.swing.JComponent;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JScrollPane;
import javax.swing.ScrollPaneConstants;
import javax.swing.SwingConstants;
import javax.swing.SwingUtilities;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;

/**
 * The Activity page: what the account has been doing, by day, week or month.
 * A headline (total or daily average) with a stacked column chart, then the split by activity.
 */
class ActivityView extends JPanel
{
	private static final String[] RANGES = {"day", "week", "month"};
	private static final String[] RANGE_LABELS = {"Day", "Week", "Month"};

	private final AccountApi api;
	private final MessageList list = new MessageList(null, 0);
	private final ActivityCharts.Segmented picker;
	private final JLabel periodLabel = new JLabel("", SwingConstants.CENTER);
	private final JButton older = ChatComponents.iconButton("chevron-left", "Earlier");
	private final JButton newer = ChatComponents.iconButton("chevron-right", "Later");
	private final JPanel nav = new JPanel(new BorderLayout());
	private final ActivityCharts.Segmented metric;
	private int range = 1;
	private int offset;
	private int requestId;
	/** Show XP gained instead of time played. */
	private boolean xp;
	private JsonObject shown;
	/** Set by the sidebar: open the Gained page on a metric (a skill or boss tapped here). */
	static java.util.function.Consumer<String> openGained = m -> {};

	ActivityView(AccountApi api)
	{
		this.api = api;
		setLayout(new BorderLayout());
		setOpaque(false);

		picker = new ActivityCharts.Segmented(RANGE_LABELS, range, i ->
		{
			range = i;
			offset = 0;
			refresh();
		});
		metric = new ActivityCharts.Segmented(new String[]{"Time", "XP"}, 0, new Dimension(88, 24), i ->
		{
			xp = i == 1;
			if (shown != null)
			{
				render(shown, null);
			}
		});
		periodLabel.setFont(FontManager.getRunescapeBoldFont());
		periodLabel.setForeground(Color.WHITE);
		older.addActionListener(e ->
		{
			offset++;
			refresh();
		});
		newer.addActionListener(e ->
		{
			offset = Math.max(0, offset - 1);
			refresh();
		});
		nav.setOpaque(false);
		nav.add(older, BorderLayout.WEST);
		nav.add(periodLabel, BorderLayout.CENTER);
		nav.add(newer, BorderLayout.EAST);
		nav.setPreferredSize(new Dimension(200, 32));

		// Room at the bottom to scroll clear of the floating composer
		list.setBorder(BorderFactory.createEmptyBorder(8, 8, FloatingAsk.CLEARANCE, 8));
		JScrollPane scroll = new JScrollPane(list);
		scroll.setOpaque(false);
		scroll.getViewport().setOpaque(false);
		scroll.setBorder(BorderFactory.createEmptyBorder());
		scroll.setHorizontalScrollBarPolicy(ScrollPaneConstants.HORIZONTAL_SCROLLBAR_NEVER);
		Surface card = new Surface(ChatComponents.CARD_BG, 8, true).border(ChatComponents.PANEL_BG);
		card.setLayout(new BorderLayout());
		card.setBorder(BorderFactory.createEmptyBorder(1, 1, 1, 1));
		card.add(scroll, BorderLayout.CENTER);
		add(card, BorderLayout.CENTER);

		render(null, "Loading your activity...");
	}

	AccountApi api()
	{
		return api;
	}

	/** Reload the period on screen (e.g. when the page opens or after a sync). */
	void refresh()
	{
		int id = ++requestId;
		periodLabel.setText(periodLabel.getText().isEmpty() ? "..." : periodLabel.getText());
		api.activity(RANGES[range], offset, result -> SwingUtilities.invokeLater(() ->
		{
			if (id != requestId)
			{
				return; // a newer request is in flight
			}
			render(result.json, result.error);
		}));
	}

	/** Switch between time played and XP gained (previews; players use the toggle). */
	void showXp(boolean value)
	{
		xp = value;
		metric.setSelected(value ? 1 : 0);
		if (shown != null)
		{
			render(shown, null);
		}
	}

	void render(JsonObject a, String error)
	{
		shown = a;
		list.removeAll();
		list.add(ChatComponents.place(picker, Align.FILL, 0));
		list.add(ChatComponents.place(nav, Align.FILL, 8));
		if (a == null)
		{
			periodLabel.setText("");
			older.setEnabled(false);
			newer.setEnabled(false);
			list.add(ChatComponents.place(message(error), Align.FILL, 8));
			relayout();
			return;
		}
		int shownRange = java.util.Arrays.asList(RANGES).indexOf(str(a, "range"));
		if (shownRange >= 0)
		{
			range = shownRange;
			picker.setSelected(shownRange);
		}
		periodLabel.setText(str(a, "label"));
		older.setEnabled(a.get("hasOlder").getAsBoolean() || num(a, "totalMinutes") > 0);
		newer.setEnabled(a.get("hasNewer").getAsBoolean());

		// Colours follow the activities' rank for the whole period, so the chart and the list match
		List<String> names = new ArrayList<>();
		for (JsonElement e : a.getAsJsonArray("activities"))
		{
			names.add(str(e.getAsJsonObject(), "name"));
		}
		Map<String, Color> colors = ActivityCharts.colorMap(names);

		if (a.has("totals"))
		{
			list.add(ChatComponents.place(tiles(a), Align.FILL, 8));
		}
		list.add(ChatComponents.place(chartCard(a, colors, names), Align.FILL, 8));
		if (num(a, "totalMinutes") > 0)
		{
			list.add(ChatComponents.place(Ui.withAsk(breakdownCard(a, colors), "Review my playtime " + (range == 0 ? "today" : "this " + RANGES[range])), Align.FILL, 8));
		}
		else if (offset == 0)
		{
			list.add(ChatComponents.place(message("Nothing tracked " + (range == 0 ? "today" : "this " + RANGES[range])
				+ " yet. Squire notes what you're doing each minute you play: the monster you're fighting, the skill you're training, or **Other**. "
				+ "Idle minutes aren't counted."), Align.FILL, 8));
		}
		String when = range == 0 ? "today" : "this " + RANGES[range];
		addIf(skillsCard(a), "Which skills did I train most " + when + "?");
		addIf(killsCard(a), "How did my bossing go " + when + "?");
		addIf(lootCard(a), "What was my best loot " + when + "?");
		addIf(sessionsCard(a), "Summarise my play sessions " + when);
		addIf(milestonesCard(a), null);
		list.add(ChatComponents.place(HomeView.listRow(SvgIcon.load("progress", 16, null), "Gains over a month or year", null, () -> openGained.accept("overall")), Align.FILL, 8));
		relayout();
	}

	private JComponent chartCard(JsonObject a, Map<String, Color> colors, List<String> order)
	{
		Surface c = card();
		JsonObject headline = obj(a, "headline");
		String headlineLabel = str(headline, "label");
		if (xp)
		{
			headlineLabel = range == 0 ? "XP gained" : "Daily average XP";
		}
		c.add(row(small(headlineLabel), metric));
		c.add(Box.createVerticalStrut(2));
		JLabel value = bold(xp ? "+" + shortNumber(num(headline, "xp")) : duration(num(headline, "minutes")));
		value.setFont(FontManager.getRunescapeBoldFont().deriveFont(24f));
		JLabel change = null;
		String changeKey = xp ? "xpChangePct" : "changePct";
		if (headline.has(changeKey) && !headline.get(changeKey).isJsonNull())
		{
			int pct = (int) num(headline, changeKey);
			change = small((pct >= 0 ? "Up " : "Down ") + Math.abs(pct) + "% vs " + str(headline, "comparedTo"));
			change.setVerticalAlignment(SwingConstants.BOTTOM);
		}
		JPanel line = new JPanel(new BorderLayout(8, 0));
		line.setOpaque(false);
		line.add(value, BorderLayout.WEST);
		if (change != null)
		{
			JPanel wrap = new JPanel(new BorderLayout());
			wrap.setOpaque(false);
			wrap.setBorder(BorderFactory.createEmptyBorder(0, 0, 3, 0));
			wrap.add(change, BorderLayout.SOUTH);
			line.add(wrap, BorderLayout.CENTER);
		}
		line.setAlignmentX(LEFT_ALIGNMENT);
		line.setMaximumSize(new Dimension(Integer.MAX_VALUE, line.getPreferredSize().height));
		c.add(line);
		c.add(Box.createVerticalStrut(10));

		List<Column> columns = new ArrayList<>();
		for (JsonElement e : a.getAsJsonArray("buckets"))
		{
			JsonObject b = e.getAsJsonObject();
			List<Part> parts = new ArrayList<>();
			JsonArray segs = b.getAsJsonArray("segments");
			// Stack in rank order, biggest activity at the bottom
			for (String name : order)
			{
				for (JsonElement s : segs)
				{
					JsonObject seg = s.getAsJsonObject();
					if (str(seg, "name").equals(name))
					{
						double v = num(seg, xp ? "xp" : "minutes");
						if (v > 0)
						{
							parts.add(new Part(name, v, colors.getOrDefault(name, Ui.OTHER)));
						}
					}
				}
			}
			String title = columnTitle(a, b);
			columns.add(new Column(str(b, "label"), b.has("sub") && !b.get("sub").isJsonNull() ? str(b, "sub") : null,
				ActivityCharts.tooltip(title, parts, xp ? v -> fmt(v) + " XP" : Ui::duration), b.get("current").getAsBoolean(), b.get("future").getAsBoolean(), parts));
		}
		ActivityCharts.ColumnChart chart = new ActivityCharts.ColumnChart(columns, xp);
		chart.setAlignmentX(LEFT_ALIGNMENT);
		c.add(chart);
		return c;
	}

	private static String columnTitle(JsonObject a, JsonObject bucket)
	{
		String key = str(bucket, "key");
		if ("day".equals(str(a, "range")))
		{
			int h = Integer.parseInt(key);
			return (h % 12 == 0 ? 12 : h % 12) + (h < 12 ? "am" : "pm") + " - " + ((h + 1) % 12 == 0 ? 12 : (h + 1) % 12) + (h + 1 < 12 || h + 1 == 24 ? "am" : "pm");
		}
		try
		{
			java.time.LocalDate d = java.time.LocalDate.parse(key);
			return d.getDayOfWeek().getDisplayName(java.time.format.TextStyle.SHORT, java.util.Locale.US) + " "
				+ d.getMonth().getDisplayName(java.time.format.TextStyle.SHORT, java.util.Locale.US) + " " + d.getDayOfMonth();
		}
		catch (RuntimeException e)
		{
			return key;
		}
	}

	private JComponent breakdownCard(JsonObject a, Map<String, Color> colors)
	{
		Surface c = card();
		String valueKey = xp ? "xp" : "minutes";
		if (xp)
		{
			c.add(row(small(range == 0 ? "XP gained" : "XP gained, total"), clearOfAsk(bold("+" + fmt(num(a, "totalXp"))))));
		}
		else
		{
			c.add(row(small(range == 0 ? "Time played" : "Time played, total"), clearOfAsk(bold(duration(num(a, "totalMinutes"))))));
		}
		c.add(Box.createVerticalStrut(8));
		// XP view: only activities that gained XP, biggest first
		List<JsonObject> acts = new ArrayList<>();
		for (JsonElement e : a.getAsJsonArray("activities"))
		{
			JsonObject act = e.getAsJsonObject();
			if (!xp || num(act, "xp") > 0)
			{
				acts.add(act);
			}
		}
		if (xp)
		{
			acts.sort((x, y) -> Double.compare(num(y, "xp"), num(x, "xp")));
		}
		if (acts.isEmpty())
		{
			c.add(row(small("No XP gained in this period."), null));
			return c;
		}
		List<Part> parts = new ArrayList<>();
		for (JsonObject act : acts)
		{
			parts.add(new Part(str(act, "name"), num(act, valueKey), colors.getOrDefault(str(act, "name"), Ui.OTHER)));
		}
		ActivityCharts.ShareBar bar = new ActivityCharts.ShareBar(parts);
		bar.setAlignmentX(LEFT_ALIGNMENT);
		c.add(bar);
		c.add(Box.createVerticalStrut(10));
		for (int i = 0; i < acts.size(); i++)
		{
			JsonObject act = acts.get(i);
			if (i > 0)
			{
				c.add(Box.createVerticalStrut(6));
			}
			JLabel name = text(str(act, "name"), ColorScheme.LIGHT_GRAY_COLOR);
			name.setIcon(swatch(colors.getOrDefault(str(act, "name"), Ui.OTHER)));
			name.setIconTextGap(8);
			// The other metric, on hover
			name.setToolTipText(xp ? duration(num(act, "minutes")) + " played" : num(act, "xp") > 0 ? fmt(num(act, "xp")) + " XP" : null);
			JLabel amount = text(xp ? "+" + shortNumber(num(act, "xp")) : duration(num(act, "minutes")), Color.WHITE);
			JLabel pct = small((int) num(act, xp ? "xpPct" : "pct") + "%");
			pct.setHorizontalAlignment(SwingConstants.RIGHT);
			pct.setPreferredSize(new Dimension(34, pct.getPreferredSize().height));
			JPanel right = new JPanel(new BorderLayout(0, 0));
			right.setOpaque(false);
			right.add(amount, BorderLayout.CENTER);
			right.add(pct, BorderLayout.EAST);
			c.add(row(name, right));
		}
		return c;
	}

	private void addIf(JComponent card, String ask)
	{
		if (card != null)
		{
			list.add(ChatComponents.place(ask == null ? card : Ui.withAsk(card, ask), Align.FILL, 8));
		}
	}

	// ---- Tiles: time, XP, kills, loot, each against the period before

	private JComponent tiles(JsonObject a)
	{
		JsonObject h = obj(a, "headline");
		JsonObject t = obj(a, "totals");
		JPanel grid = new JPanel(new java.awt.GridLayout(2, 2, 6, 6));
		grid.setOpaque(false);
		grid.add(new ActivityCharts.Tile("Time played", duration(num(a, "totalMinutes")), pct(h, "changePct")));
		// XP from the skill snapshots when there are any (what the XP by skill card adds up), else from activity minutes
		double xpTotal = 0;
		JsonArray skills = a.getAsJsonArray("skills");
		if (skills != null)
		{
			for (JsonElement e : skills)
			{
				xpTotal += num(e.getAsJsonObject(), "xp");
			}
		}
		grid.add(new ActivityCharts.Tile("XP gained", "+" + shortNumber(xpTotal > 0 ? xpTotal : num(a, "totalXp")), pct(h, "xpChangePct")));
		grid.add(new ActivityCharts.Tile("Kills", fmt(num(t, "kills")), pct(t, "killsChangePct")));
		grid.add(new ActivityCharts.Tile("Loot", shortNumber(num(t, "loot")) + " gp", pct(t, "lootChangePct")));
		return grid;
	}

	private static Integer pct(JsonObject o, String key)
	{
		return o != null && o.has(key) && !o.get(key).isJsonNull() ? (int) num(o, key) : null;
	}

	private static JComponent header(Surface c, String title, String right)
	{
		c.add(row(small(title), right == null ? null : clearOfAsk(bold(right))));
		c.add(Box.createVerticalStrut(8));
		return c;
	}

	/** Keep a header value clear of the ask-Squire button in the card's top-right corner. */
	private static JComponent clearOfAsk(JLabel value)
	{
		value.setBorder(BorderFactory.createEmptyBorder(0, 0, 0, 26));
		return value;
	}

	/** A bar that opens the Gained page on its metric. */
	private static JComponent tappable(ActivityCharts.HBar bar, String metric)
	{
		bar.setCursor(java.awt.Cursor.getPredefinedCursor(java.awt.Cursor.HAND_CURSOR));
		bar.setToolTipText("See " + metric + " over time");
		bar.addMouseListener(new java.awt.event.MouseAdapter()
		{
			@Override
			public void mouseReleased(java.awt.event.MouseEvent e)
			{
				if (javax.swing.SwingUtilities.isLeftMouseButton(e) && e.getComponent().contains(e.getPoint()))
				{
					openGained.accept(metric);
				}
			}
		});
		bar.setAlignmentX(LEFT_ALIGNMENT);
		return bar;
	}

	// ---- XP by skill

	private JComponent skillsCard(JsonObject a)
	{
		JsonArray skills = a.getAsJsonArray("skills");
		if (skills == null || skills.size() == 0)
		{
			return null;
		}
		Surface c = card();
		double total = 0, top = num(skills.get(0).getAsJsonObject(), "xp");
		for (JsonElement e : skills)
		{
			total += num(e.getAsJsonObject(), "xp");
		}
		header(c, "XP by skill", "+" + shortNumber(total));
		for (int i = 0; i < Math.min(8, skills.size()); i++)
		{
			JsonObject sk = skills.get(i).getAsJsonObject();
			String name = str(sk, "skill");
			c.add(tappable(new ActivityCharts.HBar(name, "+" + shortNumber(num(sk, "xp")), "Level " + (int) num(sk, "level"),
				num(sk, "xp") / top, Ui.activityColor(i, name), null), name));
			c.add(Box.createVerticalStrut(6));
		}
		return c;
	}

	// ---- Kills by boss, with rates and kill times from the kill log

	private JComponent killsCard(JsonObject a)
	{
		JsonArray kills = a.getAsJsonArray("kills");
		if (kills == null || kills.size() == 0)
		{
			return null;
		}
		Surface c = card();
		double top = num(kills.get(0).getAsJsonObject(), "kills");
		header(c, "Kills", fmt(num(obj(a, "totals"), "kills")));
		for (JsonElement e : kills)
		{
			JsonObject k = e.getAsJsonObject();
			List<String> bits = new ArrayList<>();
			if (k.has("perHour") && !k.get("perHour").isJsonNull())
			{
				bits.add(num(k, "perHour") + "/hr");
			}
			if (k.has("avgSeconds") && !k.get("avgSeconds").isJsonNull())
			{
				bits.add("avg " + clock(num(k, "avgSeconds")));
			}
			if (k.has("bestSeconds") && !k.get("bestSeconds").isJsonNull())
			{
				bits.add("best " + clock(num(k, "bestSeconds")));
			}
			if (num(k, "minutes") > 0)
			{
				bits.add(duration(num(k, "minutes")));
			}
			c.add(tappable(new ActivityCharts.HBar(str(k, "boss"), fmt(num(k, "kills")), bits.isEmpty() ? null : String.join("  ·  ", bits),
				num(k, "kills") / top, ChatComponents.ACCENT, null), str(k, "boss")));
			c.add(Box.createVerticalStrut(6));
		}
		return c;
	}

	private static String clock(double seconds)
	{
		int s = (int) Math.round(seconds);
		return s >= 3600 ? String.format("%d:%02d:%02d", s / 3600, s / 60 % 60, s % 60) : String.format("%d:%02d", s / 60, s % 60);
	}

	// ---- Loot: by source, and the best drops

	private static final Color GOLD = new Color(0xC8A24A);

	private JComponent lootCard(JsonObject a)
	{
		JsonObject loot = obj(a, "loot");
		if (loot == null || num(loot, "value") <= 0)
		{
			return null;
		}
		Surface c = card();
		header(c, "Loot  ·  " + fmt(num(loot, "drops")) + " drops", shortNumber(num(loot, "value")) + " gp");
		JsonArray sources = loot.getAsJsonArray("sources");
		double top = sources.size() > 0 ? num(sources.get(0).getAsJsonObject(), "value") : 1;
		for (JsonElement e : sources)
		{
			JsonObject src = e.getAsJsonObject();
			ActivityCharts.HBar bar = new ActivityCharts.HBar(str(src, "source"), shortNumber(num(src, "value")) + " gp",
				fmt(num(src, "drops")) + " drops", num(src, "value") / Math.max(1, top), GOLD, null);
			bar.setAlignmentX(LEFT_ALIGNMENT);
			c.add(bar);
			c.add(Box.createVerticalStrut(6));
		}
		JsonArray items = loot.getAsJsonArray("items");
		if (items.size() > 0)
		{
			c.add(Box.createVerticalStrut(4));
			c.add(row(small("Best drops"), null));
			c.add(Box.createVerticalStrut(4));
			for (JsonElement e : items)
			{
				JsonObject it = e.getAsJsonObject();
				JLabel name = text((num(it, "quantity") > 1 ? fmt(num(it, "quantity")) + " x " : "") + str(it, "name"), ColorScheme.LIGHT_GRAY_COLOR);
				java.awt.image.BufferedImage img = Crest.itemImage((int) num(it, "id"), name);
				if (img != null)
				{
					name.setIcon(new javax.swing.ImageIcon(img.getScaledInstance(img.getWidth() * 2 / 3, img.getHeight() * 2 / 3, java.awt.Image.SCALE_FAST)));
					name.setIconTextGap(6);
				}
				c.add(row(name, text(shortNumber(num(it, "value")), Color.WHITE)));
			}
		}
		return c;
	}

	// ---- Play sessions (runs of active minutes, split by breaks of 15+ minutes)

	private JComponent sessionsCard(JsonObject a)
	{
		JsonArray sessions = a.getAsJsonArray("sessions");
		if (sessions == null || sessions.size() == 0)
		{
			return null;
		}
		Surface c = card();
		header(c, "Sessions", sessions.size() + (sessions.size() == 1 ? " session" : " sessions"));
		double longest = 1;
		for (JsonElement e : sessions)
		{
			longest = Math.max(longest, num(e.getAsJsonObject(), "minutes"));
		}
		java.time.format.DateTimeFormatter f = java.time.format.DateTimeFormatter.ofPattern(range == 0 ? "h:mma" : "EEE h:mma", java.util.Locale.US)
			.withZone(java.time.ZoneId.systemDefault());
		for (JsonElement e : sessions)
		{
			JsonObject ses = e.getAsJsonObject();
			String start;
			try
			{
				start = f.format(java.time.Instant.parse(str(ses, "start"))).toLowerCase(java.util.Locale.US).replace("am", "am").replace("pm", "pm");
				start = Character.toUpperCase(start.charAt(0)) + start.substring(1);
			}
			catch (RuntimeException ex)
			{
				start = "";
			}
			List<String> bits = new ArrayList<>();
			bits.add(str(ses, "main"));
			if (num(ses, "xp") > 0)
			{
				bits.add("+" + shortNumber(num(ses, "xp")) + " xp");
			}
			if (num(ses, "kills") > 0)
			{
				bits.add(fmt(num(ses, "kills")) + " kills");
			}
			if (num(ses, "loot") > 0)
			{
				bits.add(shortNumber(num(ses, "loot")) + " gp");
			}
			ActivityCharts.HBar bar = new ActivityCharts.HBar(start, duration(num(ses, "minutes")), String.join("  ·  ", bits),
				num(ses, "minutes") / longest, Ui.activityColor(0, str(ses, "main")), null);
			bar.setAlignmentX(LEFT_ALIGNMENT);
			c.add(bar);
			c.add(Box.createVerticalStrut(6));
		}
		return c;
	}

	// ---- Milestones: levels, collection log, pets, combat achievements, quests, deaths

	private JComponent milestonesCard(JsonObject a)
	{
		JsonArray ms = a.getAsJsonArray("milestones");
		if (ms == null || ms.size() == 0)
		{
			return null;
		}
		Surface c = card();
		header(c, "Milestones", String.valueOf(ms.size()));
		for (JsonElement e : ms)
		{
			JsonObject m = e.getAsJsonObject();
			JLabel label = text(str(m, "summary"), ColorScheme.LIGHT_GRAY_COLOR);
			label.setIcon(swatch(milestoneColor(str(m, "type"))));
			label.setIconTextGap(8);
			label.setToolTipText(str(m, "type").replace('_', ' '));
			c.add(row(label, null));
			c.add(Box.createVerticalStrut(4));
		}
		return c;
	}

	private static Color milestoneColor(String type)
	{
		switch (type)
		{
			case "level_up":
				return new Color(0x5FBF6A);
			case "collection_log":
				return new Color(0xB072E0);
			case "pet":
				return new Color(0xE07AB6);
			case "combat_achievement":
				return new Color(0xE0A34A);
			case "quest_complete":
				return ChatComponents.ACCENT;
			case "death":
				return new Color(0xE06A5A);
			case "personal_best":
				return new Color(0x4FC3D9);
			default:
				return ChatComponents.MUTED;
		}
	}

	private static Bubble message(String markdown)
	{
		Bubble b = new Bubble(ChatComponents.PANEL_BG, ColorScheme.LIGHT_GRAY_COLOR, false, true);
		b.setHtml(MarkdownLite.toHtml(markdown == null ? "" : markdown));
		return b;
	}

	private void relayout()
	{
		list.revalidate();
		list.repaint();
	}
}

package com.squire;

import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.util.Base64;
import java.util.LinkedHashMap;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import javax.imageio.IIOImage;
import javax.imageio.ImageIO;
import javax.imageio.ImageWriteParam;
import javax.imageio.ImageWriter;
import javax.imageio.stream.ImageOutputStream;

/**
 * Something attached to a chat message: a screenshot/image, or text (pasted or from a .txt/.md/... file).
 * Images go to the model as file parts; text goes as a quoted text part with its file name.
 */
final class Attachment
{
	enum Kind
	{
		IMAGE, TEXT
	}

	static final Set<String> IMAGE_TYPES = Set.of("png", "jpg", "jpeg", "gif", "bmp", "webp");
	static final Set<String> TEXT_TYPES = Set.of("txt", "md", "markdown", "json", "csv", "log", "yml", "yaml", "tsv");
	/** Pasted text longer than this becomes an attachment instead of going into the input. */
	static final int PASTE_AS_FILE_CHARS = 1000;
	static final int PASTE_AS_FILE_LINES = 12;
	private static final int MAX_TEXT_CHARS = 100_000;
	/** Long edge models see well; bigger images just cost more. */
	private static final int MAX_IMAGE_EDGE = 1568;
	/** Keeps a message with a few screenshots under the host's ~4.5MB request limit (base64 adds a third). */
	private static final int MAX_IMAGE_BYTES = 800_000;

	final Kind kind;
	final String name;
	final String mediaType;
	final byte[] bytes;
	final String text;
	final BufferedImage thumbnail;
	/** For context from a page (e.g. "Plan"): shown on the tile instead of a file type; null for files. */
	String label;

	private Attachment(Kind kind, String name, String mediaType, byte[] bytes, String text, BufferedImage thumbnail)
	{
		this.kind = kind;
		this.name = name;
		this.mediaType = mediaType;
		this.bytes = bytes;
		this.text = text;
		this.thumbnail = thumbnail;
	}

	static Attachment image(BufferedImage source, String name) throws IOException
	{
		BufferedImage img = fit(source, MAX_IMAGE_EDGE);
		byte[] png = encode(img, "png", 1f);
		String type = "image/png";
		String file = name == null ? "Screenshot.png" : name;
		if (png.length > MAX_IMAGE_BYTES)
		{
			// Photos and busy screenshots: JPEG, shrinking until it fits
			type = "image/jpeg";
			file = file.replaceAll("\\.[A-Za-z]+$", "") + ".jpg";
			int edge = MAX_IMAGE_EDGE;
			png = encode(toRgb(img), "jpg", 0.85f);
			while (png.length > MAX_IMAGE_BYTES && edge > 400)
			{
				edge = edge * 3 / 4;
				png = encode(toRgb(fit(source, edge)), "jpg", 0.8f);
			}
		}
		return new Attachment(Kind.IMAGE, file, type, png, null, fit(source, 144));
	}

	/**
	 * Context from the page the player asked from (their plan, their progress): sent to Squire like a text file,
	 * shown as a tile with a label and an icon instead of a file type.
	 */
	static Attachment context(String label, String name, String markdown, BufferedImage icon)
	{
		Attachment a = new Attachment(Kind.TEXT, name, "text/markdown", null, markdown, icon);
		a.label = label;
		return a;
	}

	static Attachment text(String text, String name)
	{
		String body = text.length() > MAX_TEXT_CHARS ? text.substring(0, MAX_TEXT_CHARS) + "\n[truncated]" : text;
		boolean markdown = name != null ? name.toLowerCase(Locale.ROOT).matches(".*\\.(md|markdown)$") : looksLikeMarkdown(body);
		String file = name != null ? name : markdown ? "Pasted text.md" : "Pasted text.txt";
		return new Attachment(Kind.TEXT, file, markdown ? "text/markdown" : "text/plain", null, body, null);
	}

	/** An attachment for a file the player chose or dropped, or null if it's not a kind we take. */
	static Attachment fromFile(net.runelite.client.util.Filepath file) throws IOException
	{
		String name = file.getFileName();
		String ext = extensionOf(name);
		if (IMAGE_TYPES.contains(ext))
		{
			try (java.io.InputStream in = file.openInputStream())
			{
				BufferedImage img = ImageIO.read(in);
				return img == null ? null : image(img, name);
			}
		}
		if (TEXT_TYPES.contains(ext))
		{
			try (java.io.InputStream in = file.openInputStream())
			{
				return text(new String(in.readAllBytes(), StandardCharsets.UTF_8), name);
			}
		}
		return null;
	}

	/** For the chat history: the kind, name and a small thumbnail (not the full image or text). */
	com.google.gson.JsonObject toHistory()
	{
		com.google.gson.JsonObject o = new com.google.gson.JsonObject();
		o.addProperty("kind", kind.name());
		o.addProperty("name", name);
		o.addProperty("mediaType", mediaType);
		o.addProperty("size", sizeLabel());
		if (label != null)
		{
			o.addProperty("label", label);
		}
		if (thumbnail != null)
		{
			try
			{
				o.addProperty("thumbnail", Base64.getEncoder().encodeToString(encode(fit(thumbnail, 96), "png", 1f)));
			}
			catch (IOException ignored)
			{
				// no thumbnail
			}
		}
		return o;
	}

	/** A tile for a sent message restored from the history. */
	static Attachment fromHistory(com.google.gson.JsonObject o)
	{
		Kind kind = "IMAGE".equals(o.has("kind") ? o.get("kind").getAsString() : "") ? Kind.IMAGE : Kind.TEXT;
		BufferedImage thumb = null;
		if (o.has("thumbnail"))
		{
			try
			{
				thumb = ImageIO.read(new java.io.ByteArrayInputStream(Base64.getDecoder().decode(o.get("thumbnail").getAsString())));
			}
			catch (IOException | IllegalArgumentException ignored)
			{
				// no thumbnail
			}
		}
		String name = o.has("name") ? o.get("name").getAsString() : "Attachment";
		String type = o.has("mediaType") ? o.get("mediaType").getAsString() : "";
		Attachment a = new Attachment(kind, name, type, new byte[0], kind == Kind.TEXT ? "" : null, thumb);
		a.label = o.has("label") ? o.get("label").getAsString() : null;
		return a;
	}

	/** True for pasted text that should become a file rather than go into the input. */
	static boolean isLongPaste(String s)
	{
		return s.length() > PASTE_AS_FILE_CHARS || s.split("\n", -1).length > PASTE_AS_FILE_LINES;
	}

	/** The label on a tile: MD, TXT, PNG, ... */
	String extension()
	{
		String ext = extensionOf(name);
		return ext.isEmpty() ? (kind == Kind.IMAGE ? "IMG" : "TXT") : ext.toUpperCase(Locale.ROOT);
	}

	String sizeLabel()
	{
		long n = kind == Kind.IMAGE ? bytes.length : text.getBytes(StandardCharsets.UTF_8).length;
		return n >= 1_000_000 ? String.format(Locale.US, "%.1f MB", n / 1e6) : n >= 1000 ? (n / 1000) + " KB" : n + " B";
	}

	/** This attachment as a message part for the agent (AI SDK UserContent). */
	Map<String, Object> toPart()
	{
		Map<String, Object> part = new LinkedHashMap<>();
		if (kind == Kind.IMAGE)
		{
			part.put("type", "file");
			part.put("data", "data:" + mediaType + ";base64," + Base64.getEncoder().encodeToString(bytes));
			part.put("mediaType", mediaType);
			part.put("filename", name);
		}
		else
		{
			part.put("type", "text");
			part.put("text", "Attached file: " + name + "\n\n" + text);
		}
		return part;
	}

	static boolean looksLikeMarkdown(String s)
	{
		return s.matches("(?s).*(^|\n)(#{1,6} |[-*] |\\d+\\. |> |```).*") || s.contains("**") || s.matches("(?s).*\\[[^\\]]+\\]\\([^)]+\\).*");
	}

	static String extensionOf(String name)
	{
		int dot = name == null ? -1 : name.lastIndexOf('.');
		return dot < 0 ? "" : name.substring(dot + 1).toLowerCase(Locale.ROOT);
	}

	private static BufferedImage fit(BufferedImage img, int maxEdge)
	{
		double scale = Math.min(1.0, maxEdge / (double) Math.max(img.getWidth(), img.getHeight()));
		int w = Math.max(1, (int) Math.round(img.getWidth() * scale)), h = Math.max(1, (int) Math.round(img.getHeight() * scale));
		BufferedImage out = new BufferedImage(w, h, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = out.createGraphics();
		g.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BICUBIC);
		g.setRenderingHint(RenderingHints.KEY_RENDERING, RenderingHints.VALUE_RENDER_QUALITY);
		g.drawImage(img, 0, 0, w, h, null);
		g.dispose();
		return out;
	}

	private static BufferedImage toRgb(BufferedImage img)
	{
		BufferedImage out = new BufferedImage(img.getWidth(), img.getHeight(), BufferedImage.TYPE_INT_RGB);
		Graphics2D g = out.createGraphics();
		g.setColor(java.awt.Color.BLACK);
		g.fillRect(0, 0, img.getWidth(), img.getHeight());
		g.drawImage(img, 0, 0, null);
		g.dispose();
		return out;
	}

	private static byte[] encode(BufferedImage img, String format, float quality) throws IOException
	{
		ByteArrayOutputStream out = new ByteArrayOutputStream();
		if (format.equals("jpg"))
		{
			ImageWriter writer = ImageIO.getImageWritersByFormatName("jpg").next();
			ImageWriteParam param = writer.getDefaultWriteParam();
			param.setCompressionMode(ImageWriteParam.MODE_EXPLICIT);
			param.setCompressionQuality(quality);
			try (ImageOutputStream ios = ImageIO.createImageOutputStream(out))
			{
				writer.setOutput(ios);
				writer.write(null, new IIOImage(img, null, null), param);
			}
			finally
			{
				writer.dispose();
			}
		}
		else
		{
			ImageIO.write(img, format, out);
		}
		return out.toByteArray();
	}
}

package com.squire;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.FlowLayout;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.Image;
import java.awt.Rectangle;
import java.awt.RenderingHints;
import java.awt.Shape;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.awt.image.BufferedImage;
import java.util.List;
import java.util.function.Consumer;
import javax.swing.JComponent;
import javax.swing.JPanel;
import net.runelite.client.ui.FontManager;

/** Attachment tiles: little squares above the composer (removable) and above sent messages. */
final class AttachmentViews
{
	static final int TILE = 48;
	private static final int RADIUS = 8;
	private static final int CLOSE = 16;

	/** A row of tiles. With onRemove, each shows an x on hover that calls it. */
	static JPanel strip(List<Attachment> attachments, boolean alignRight, Consumer<Attachment> onRemove)
	{
		JPanel row = new JPanel(new FlowLayout(alignRight ? FlowLayout.RIGHT : FlowLayout.LEFT, 6, 0))
		{
			@Override
			public Dimension getMaximumSize()
			{
				return new Dimension(Integer.MAX_VALUE, getPreferredSize().height);
			}
		};
		// FlowLayout pads the ends by its gap; cancel it so tiles line up with the text
		row.setBorder(javax.swing.BorderFactory.createEmptyBorder(0, -6, 0, -6));
		row.setOpaque(false);
		for (Attachment a : attachments)
		{
			row.add(new Tile(a, onRemove));
		}
		return row;
	}

	static final class Tile extends JComponent
	{
		private final Attachment attachment;
		private final Consumer<Attachment> onRemove;
		private boolean hover;
		private boolean overClose;

		Tile(Attachment attachment, Consumer<Attachment> onRemove)
		{
			this.attachment = attachment;
			this.onRemove = onRemove;
			setPreferredSize(new Dimension(TILE, TILE));
			setToolTipText("<html><b>" + MarkdownLite.escape(attachment.name) + "</b><br>" + attachment.sizeLabel() + "</html>");
			MouseAdapter mouse = new MouseAdapter()
			{
				@Override
				public void mouseEntered(MouseEvent e)
				{
					hover = true;
					repaint();
				}

				@Override
				public void mouseExited(MouseEvent e)
				{
					hover = false;
					overClose = false;
					setCursor(Cursor.getDefaultCursor());
					repaint();
				}

				@Override
				public void mouseMoved(MouseEvent e)
				{
					boolean over = onRemove != null && closeBounds().contains(e.getPoint());
					if (over != overClose)
					{
						overClose = over;
						setCursor(over ? Cursor.getPredefinedCursor(Cursor.HAND_CURSOR) : Cursor.getDefaultCursor());
						repaint();
					}
				}

				@Override
				public void mouseReleased(MouseEvent e)
				{
					// On release rather than click: Swing drops a click if the pointer moves a pixel while pressed
					if (!javax.swing.SwingUtilities.isLeftMouseButton(e) || !e.getComponent().contains(e.getPoint()))
					{
						return;
					}
					if (onRemove != null && closeBounds().contains(e.getPoint()))
					{
						onRemove.accept(attachment);
					}
				}
			};
			addMouseListener(mouse);
			addMouseMotionListener(mouse);
		}

		private Rectangle closeBounds()
		{
			return new Rectangle(getWidth() - CLOSE - 3, 3, CLOSE, CLOSE);
		}

		@Override
		protected void paintComponent(Graphics g)
		{
			Graphics2D g2 = (Graphics2D) g.create();
			g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
			int w = getWidth(), h = getHeight();
			Shape shape = Pixel.shape(0, 0, w, h, RADIUS);

			if (attachment.kind == Attachment.Kind.IMAGE && attachment.thumbnail != null)
			{
				g2.setColor(ChatComponents.BASE_BG);
				g2.fill(shape);
				g2.clip(shape);
				g2.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BICUBIC);
				drawCover(g2, attachment.thumbnail, w, h);
				g2.setClip(null);
			}
			else if (attachment.label != null)
			{
				paintContext(g2, w, h, shape);
			}
			else
			{
				paintFile(g2, w, h, shape);
			}

			g2.setColor(ChatComponents.BORDER);
			g2.setStroke(new BasicStroke(1f));
			Pixel.draw(g2, 0, 0, w, h, RADIUS);

			if (hover && onRemove != null)
			{
				Rectangle c = closeBounds();
				g2.setColor(overClose ? ChatComponents.HOVER_BG : ChatComponents.BASE_BG);
				Pixel.fill(g2, c.x, c.y, c.width, c.height, c.width / 2.0);
				g2.setColor(ChatComponents.BORDER);
				Pixel.draw(g2, c.x, c.y, c.width, c.height, c.width / 2.0);
				Image x = SvgIcon.load("close", 12, overClose ? Color.WHITE : ChatComponents.MUTED).getImage();
				g2.drawImage(x, c.x + 2, c.y + 2, 12, 12, null);
			}
			g2.dispose();
		}

		/** Context from a page: its icon (e.g. the plan's current item) and a label ("PLAN") underneath. */
		private void paintContext(Graphics2D g2, int w, int h, Shape shape)
		{
			g2.setColor(ChatComponents.PANEL_BG);
			g2.fill(shape);
			BufferedImage icon = attachment.thumbnail;
			if (icon != null)
			{
				int iw = Math.min(icon.getWidth(), w - 8), ih = Math.min(icon.getHeight(), h - 18);
				double scale = Math.min(iw / (double) icon.getWidth(), ih / (double) icon.getHeight());
				int dw = (int) (icon.getWidth() * scale), dh = (int) (icon.getHeight() * scale);
				g2.drawImage(icon, (w - dw) / 2, 4 + (h - 18 - dh) / 2, dw, dh, null);
			}
			Font font = FontManager.getRunescapeSmallFont();
			g2.setFont(font);
			FontMetrics fm = g2.getFontMetrics();
			g2.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_OFF);
			g2.setColor(ChatComponents.ACCENT.brighter());
			String label = attachment.label.toUpperCase(java.util.Locale.ROOT);
			g2.drawString(label, 8, h - 7 - fm.getDescent() + 2);
		}

		/** A document: faint lines of "text" and the file type underneath. */
		private void paintFile(Graphics2D g2, int w, int h, Shape shape)
		{
			g2.setColor(ChatComponents.PANEL_BG);
			g2.fill(shape);
			g2.setColor(ChatComponents.USER_BG);
			int x = 8, y = 9;
			int[] lengths = {w - 16, w - 22, w - 18};
			for (int len : lengths)
			{
				g2.fillRect(x, y, len, 2);
				y += 5;
			}

			String ext = attachment.extension();
			if (ext.length() > 4)
			{
				ext = ext.substring(0, 4);
			}
			Font font = FontManager.getRunescapeSmallFont();
			g2.setFont(font);
			FontMetrics fm = g2.getFontMetrics();
			g2.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_OFF);
			g2.setColor(ChatComponents.MUTED);
			g2.drawString(ext, x, h - 7 - fm.getDescent() + 2);
		}

		private static void drawCover(Graphics2D g2, BufferedImage img, int w, int h)
		{
			double scale = Math.max(w / (double) img.getWidth(), h / (double) img.getHeight());
			int dw = (int) Math.ceil(img.getWidth() * scale), dh = (int) Math.ceil(img.getHeight() * scale);
			g2.drawImage(img, (w - dw) / 2, (h - dh) / 2, dw, dh, null);
		}
	}

	private AttachmentViews()
	{
	}
}

package com.squire;

import com.google.gson.JsonObject;
import java.awt.AlphaComposite;
import java.awt.Color;
import java.awt.GradientPaint;
import java.awt.Graphics2D;
import java.awt.Image;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import java.util.HashMap;
import java.util.Map;
import java.util.function.IntFunction;
import javax.imageio.ImageIO;

/**
 * The avatar card: the character on a background, in a frame, with an emblem. Drawn on the same 80x80 pixel grid and
 * from the same data as the website's card (server/app/p/avatar-card.tsx), including the background's specks, which
 * come from the same seeded random sequence, so the plugin and the profile page look the same.
 */
final class AvatarCard
{
	private static final Color OUTLINE = new Color(0x0B0B0B);
	private static final Map<String, BufferedImage> EMBLEMS = new HashMap<>();

	private AvatarCard()
	{
	}

	/**
	 * Paint the card at (x, y), size px square. {@code background} and {@code frame} are the server's option objects;
	 * {@code character} is the avatar render (may be null); {@code icons} gives item icons (may be null).
	 */
	static void paint(Graphics2D g0, int x, int y, int size, JsonObject background, JsonObject frame, String emblem,
		BufferedImage character, IntFunction<BufferedImage> icons)
	{
		Graphics2D g = (Graphics2D) g0.create();
		g.translate(x, y);
		double u = size / 80.0;
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_OFF);

		Color band = color(frame, "band", 0x4454DA), light = color(frame, "light", 0x7A86FF), dark = color(frame, "dark", 0x252E78);
		stepped(g, u, 0, 0, 80, 80, 2, OUTLINE);
		stepped(g, u, 1, 1, 78, 78, 2, band);
		rect(g, u, 2, 1, 76, 1, light);
		rect(g, u, 1, 2, 1, 76, light);
		rect(g, u, 2, 78, 76, 1, dark);
		rect(g, u, 78, 2, 1, 76, dark);
		rect(g, u, 4, 4, 72, 72, OUTLINE);

		// Background: a vertical gradient with its specks
		int ix = px(u, 5), iy = px(u, 5), iw = px(u, 75) - ix, ih = px(u, 75) - iy;
		g.setPaint(new GradientPaint(ix, iy, color(background, "top", 0x10131C), ix, iy + ih, color(background, "bottom", 0x2A2522)));
		g.fillRect(ix, iy, iw, ih);
		Color ink = color(background, "ink", 0xFFFFFF);
		for (double[] s : pattern(Ui.str(background, "id"), Ui.str(background, "pattern")))
		{
			g.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, (float) s[3]));
			rect(g, u, (int) s[0], (int) s[1], (int) s[2], (int) s[2], ink);
		}
		g.setComposite(AlphaComposite.SrcOver);

		if (character != null)
		{
			// Bottom-aligned in the frame's opening, like the web card (x 6, y 7, 68 square)
			Graphics2D c = (Graphics2D) g.create();
			c.clipRect(ix, iy, iw, ih);
			c.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BILINEAR);
			int cs = px(u, 74) - px(u, 6);
			c.drawImage(character, px(u, 6), px(u, 75) - cs, cs, cs, null);
			c.dispose();
		}

		if (frame != null && frame.has("itemId") && !frame.get("itemId").isJsonNull())
		{
			stepped(g, u, 30, 0, 20, 15, 2, OUTLINE);
			rect(g, u, 31, 1, 18, 13, dark);
			BufferedImage icon = icons == null ? null : icons.apply(frame.get("itemId").getAsInt());
			if (icon != null)
			{
				fit(g, icon, px(u, 32), px(u, 1), px(u, 48) - px(u, 32), px(u, 14) - px(u, 1));
			}
		}
		if (emblem != null)
		{
			stepped(g, u, 64, 64, 15, 15, 2, OUTLINE);
			rect(g, u, 65, 65, 13, 13, new Color(0x1E1E1E));
			BufferedImage e = emblem(emblem);
			if (e != null)
			{
				fit(g, e, px(u, 66), px(u, 66), px(u, 77) - px(u, 66), px(u, 77) - px(u, 66));
			}
		}
		g.dispose();
	}

	/** The background's specks in grid units: x, y, size, opacity. Same sequence as the website's card. */
	static java.util.List<double[]> pattern(String id, String kind)
	{
		long seed = 7;
		for (char ch : id.toCharArray())
		{
			seed = (seed * 31 + ch) % 2147483646L;
		}
		seed += 1;
		int count, y0, y1, size;
		double alpha;
		switch (kind)
		{
			case "stars":
				count = 18; y0 = 5; y1 = 45; size = 1; alpha = 0.85;
				break;
			case "motes":
				count = 14; y0 = 5; y1 = 75; size = 2; alpha = 0.35;
				break;
			case "snow":
				count = 26; y0 = 5; y1 = 75; size = 1; alpha = 0.9;
				break;
			case "embers":
				count = 16; y0 = 40; y1 = 75; size = 1; alpha = 0.9;
				break;
			default:
				return java.util.List.of();
		}
		java.util.List<double[]> out = new java.util.ArrayList<>();
		for (int i = 0; i < count; i++)
		{
			seed = (seed * 48271) % 2147483647L;
			double rx = seed / 2147483647.0;
			seed = (seed * 48271) % 2147483647L;
			double ry = seed / 2147483647.0;
			out.add(new double[]{5 + Math.floor(rx * 70), y0 + Math.floor(ry * (y1 - y0)), size, alpha});
		}
		return out;
	}

	static BufferedImage emblem(String id)
	{
		synchronized (EMBLEMS)
		{
			return EMBLEMS.computeIfAbsent(id, k ->
			{
				if ("squire".equals(k))
				{
					return SquireIcon.create(26);
				}
				try (java.io.InputStream in = AvatarCard.class.getResourceAsStream("emblems/" + k + ".png"))
				{
					return in == null ? null : ImageIO.read(in);
				}
				catch (java.io.IOException e)
				{
					return null;
				}
			});
		}
	}

	/** Draw an image as large as fits the box, in whole-pixel steps when it's small pixel art. */
	private static void fit(Graphics2D g, Image img, int x, int y, int w, int h)
	{
		int iw = img.getWidth(null), ih = img.getHeight(null);
		if (iw <= 0 || ih <= 0)
		{
			return;
		}
		double s = Math.min((double) w / iw, (double) h / ih);
		if (s >= 1)
		{
			s = Math.floor(s);
		}
		int dw = (int) Math.round(iw * s), dh = (int) Math.round(ih * s);
		Graphics2D c = (Graphics2D) g.create();
		c.setRenderingHint(RenderingHints.KEY_INTERPOLATION, s >= 1 ? RenderingHints.VALUE_INTERPOLATION_NEAREST_NEIGHBOR : RenderingHints.VALUE_INTERPOLATION_BILINEAR);
		c.drawImage(img, x + (w - dw) / 2, y + (h - dh) / 2, dw, dh, null);
		c.dispose();
	}

	private static int px(double u, double v)
	{
		return (int) Math.round(v * u);
	}

	private static void rect(Graphics2D g, double u, int x, int y, int w, int h, Color c)
	{
		g.setColor(c);
		g.fillRect(px(u, x), px(u, y), px(u, x + w) - px(u, x), px(u, y + h) - px(u, y));
	}

	/** A rectangle with corners cut in whole grid pixels, like the web card's stepped path. */
	private static void stepped(Graphics2D g, double u, int x, int y, int w, int h, int cut, Color c)
	{
		rect(g, u, x + cut, y, w - 2 * cut, h, c);
		rect(g, u, x, y + cut, cut, h - 2 * cut, c);
		rect(g, u, x + w - cut, y + cut, cut, h - 2 * cut, c);
	}

	private static Color color(JsonObject o, String key, int fallback)
	{
		String hex = o == null ? "" : Ui.str(o, key);
		try
		{
			return hex.startsWith("#") ? new Color(Integer.parseInt(hex.substring(1), 16)) : new Color(fallback);
		}
		catch (NumberFormatException e)
		{
			return new Color(fallback);
		}
	}
}

package com.squire;

import java.awt.image.BufferedImage;
import java.io.BufferedReader;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.Arrays;
import java.util.HashMap;
import java.util.Map;
import java.util.function.Consumer;
import net.runelite.api.Client;
import net.runelite.api.Player;
import net.runelite.api.PlayerComposition;

/**
 * Renders the profile avatar: the player's own character, full body, optionally dressed in other gear they own. To
 * dress it, the local player's appearance is swapped for a moment (only on this client, like the Fashionscape
 * plugin), the model is captured once it has loaded, and the real appearance is put straight back. Nothing is sent to
 * the game. Client thread only: call {@link #onGameTick()} every tick.
 */
final class AvatarStudio
{
	// Body parts by the game's kit/equipment index
	private static final int SHIELD = 5, ARMS = 6, HAIR = 8, JAW = 11;
	/** Equipment slots that show on a character (ring and ammo don't). */
	static final int[] VISIBLE_SLOTS = {0, 1, 2, 3, 4, 5, 7, 9, 10};
	/** Body parts gear can hide, whose own look is put back when the new gear doesn't hide them. */
	private static final int[] HIDEABLE = {ARMS, HAIR, JAW, 9, 10};
	/** Full body, a little room above the head and below the feet. */
	private static final PlayerPortrait.Framing FULL_BODY = new PlayerPortrait.Framing(-228f, 6f, Math.toRadians(-22));
	static final int SIZE = 256;
	private static final int MAX_TICKS = 25;

	/** What each wearable item hides (bit = body part), from the game's item definitions (avatar-hides.txt). */
	private static final Map<Integer, Integer> HIDES = loadHides();

	private final Client client;
	/** The player's own look for parts gear can hide (hair, jaw, arms...), as last seen uncovered. */
	private final int[] ownKits = new int[12];
	private Job job;

	private static final class Job
	{
		final Map<Integer, Integer> gear;
		final Consumer<BufferedImage> done;
		int[] original;
		int[] applied;
		int ticks;
		long lastSignature;
		int stable;

		Job(Map<Integer, Integer> gear, Consumer<BufferedImage> done)
		{
			this.gear = gear;
			this.done = done;
		}
	}

	AvatarStudio(Client client)
	{
		this.client = client;
	}

	/** Render the character in this gear (equipment slot to item id; other slots as worn). Replaces a pending render. */
	void render(Map<Integer, Integer> gear, Consumer<BufferedImage> done)
	{
		cancel();
		job = new Job(new HashMap<>(gear), done);
	}

	boolean busy()
	{
		return job != null;
	}

	/** Put the real appearance back if a render was in progress (logout, shutdown). */
	void cancel()
	{
		Job j = job;
		job = null;
		Player p = client.getLocalPlayer();
		if (j != null && j.applied != null && p != null)
		{
			restore(p.getPlayerComposition(), j);
		}
	}

	void onGameTick()
	{
		Player p = client.getLocalPlayer();
		PlayerComposition c = p == null ? null : p.getPlayerComposition();
		if (c == null)
		{
			return;
		}
		Job j = job;
		if (j == null || j.applied == null)
		{
			remember(c.getEquipmentIds());
		}
		if (j == null)
		{
			return;
		}
		j.ticks++;
		if (j.original == null)
		{
			// Start only while standing still, so the capture isn't mid-stride
			if (!PlayerPortrait.isIdle(p))
			{
				if (j.ticks > MAX_TICKS * 4)
				{
					job = null;
				}
				return;
			}
			j.original = c.getEquipmentIds().clone();
			if (!j.gear.isEmpty())
			{
				apply(c, j);
			}
			j.ticks = 0;
			return;
		}
		// Item models load over a tick or two: capture once the model stops changing
		PlayerPortrait.Mesh mesh = PlayerPortrait.isIdle(p) ? PlayerPortrait.capture(client) : null;
		long signature = mesh == null ? 0 : PlayerPortrait.signature(mesh);
		j.stable = mesh != null && signature == j.lastSignature ? j.stable + 1 : 0;
		j.lastSignature = signature;
		boolean ready = mesh != null && j.stable >= 1 && j.ticks >= 2;
		if (!ready && j.ticks < MAX_TICKS)
		{
			return;
		}
		job = null;
		if (j.applied != null)
		{
			restore(c, j);
		}
		if (mesh != null)
		{
			j.done.accept(PlayerPortrait.draw(mesh, SIZE, FULL_BODY));
		}
	}

	/** Note the player's own hair, jaw, arms and so on whenever they're uncovered (a kit, not an item or hidden). */
	private void remember(int[] ids)
	{
		for (int k : HIDEABLE)
		{
			int v = ids[k];
			if (v >= PlayerComposition.KIT_OFFSET && v < PlayerComposition.ITEM_OFFSET)
			{
				ownKits[k] = v;
			}
		}
	}

	/** Dress the character: the chosen items, then hide or show body parts to match what the new gear covers. */
	static int[] dress(int[] original, Map<Integer, Integer> gear, int[] ownKits)
	{
		int[] ids = original.clone();
		gear.forEach((slot, item) -> ids[slot] = item + PlayerComposition.ITEM_OFFSET);
		int hidden = 0;
		for (int s : VISIBLE_SLOTS)
		{
			if (ids[s] >= PlayerComposition.ITEM_OFFSET)
			{
				hidden |= HIDES.getOrDefault(ids[s] - PlayerComposition.ITEM_OFFSET, 0);
			}
		}
		// A two-handed weapon hides the shield slot
		if ((hidden & (1 << SHIELD)) != 0 && !gear.containsKey(SHIELD))
		{
			ids[SHIELD] = 0;
		}
		for (int k : HIDEABLE)
		{
			if (ids[k] >= PlayerComposition.ITEM_OFFSET)
			{
				continue;
			}
			if ((hidden & (1 << k)) != 0)
			{
				ids[k] = 0;
			}
			else if (ids[k] == 0 && ownKits[k] != 0)
			{
				ids[k] = ownKits[k];
			}
		}
		return ids;
	}

	private void apply(PlayerComposition c, Job j)
	{
		int[] ids = c.getEquipmentIds();
		int[] dressed = dress(j.original, j.gear, ownKits);
		System.arraycopy(dressed, 0, ids, 0, Math.min(ids.length, dressed.length));
		j.applied = ids.clone();
		c.setHash();
	}

	/** Put the real appearance back, unless the game has already replaced it (they changed gear meanwhile). */
	private static void restore(PlayerComposition c, Job j)
	{
		if (c == null)
		{
			return;
		}
		int[] ids = c.getEquipmentIds();
		if (Arrays.equals(ids, j.applied))
		{
			System.arraycopy(j.original, 0, ids, 0, Math.min(ids.length, j.original.length));
			c.setHash();
		}
	}

	private static Map<Integer, Integer> loadHides()
	{
		Map<Integer, Integer> out = new HashMap<>();
		try (InputStream in = AvatarStudio.class.getResourceAsStream("avatar-hides.txt"))
		{
			if (in == null)
			{
				return out;
			}
			BufferedReader r = new BufferedReader(new InputStreamReader(in, StandardCharsets.UTF_8));
			for (String line = r.readLine(); line != null; line = r.readLine())
			{
				int colon = line.indexOf(':');
				if (colon > 0 && !line.startsWith("#"))
				{
					out.put(Integer.parseInt(line.substring(0, colon)), Integer.parseInt(line.substring(colon + 1).trim()));
				}
			}
		}
		catch (java.io.IOException | NumberFormatException e)
		{
			// Without the table, gear still shows; hair or arms may poke through
		}
		return out;
	}
}

package com.squire;

import static com.squire.Ui.*;

import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.squire.ChatComponents.Align;
import com.squire.ChatComponents.MessageList;
import com.squire.ChatComponents.Surface;
import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.image.BufferedImage;
import java.util.List;
import javax.swing.BorderFactory;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.ImageIcon;
import javax.swing.JComponent;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JScrollPane;
import javax.swing.ScrollPaneConstants;
import javax.swing.SwingUtilities;
import net.runelite.client.ui.FontManager;

/**
 * One boss (or raid, minigame, clue tier) over time, opened from the kill counts: its picture and count, the count over a
 * period with kills per day, time spent and kills per hour (the Gained page's card), personal bests and the setups they
 * were set in, and loot. Data from /api/progress?boss=.
 */
class BossView extends JPanel
{
	private static final String[] PERIODS = {"week", "month", "year", "all"};
	private static final String[] PERIOD_LABELS = {"Week", "Month", "Year", "All"};

	private final AccountApi api;
	private final WikiImages images;
	private final MessageList list = new MessageList(null, 0);
	private final ActivityCharts.Segmented picker;
	private int period = 1;
	private String boss;
	private JsonObject shown;
	private int requestId;

	BossView(AccountApi api, WikiImages images)
	{
		this.api = api;
		this.images = images;
		setLayout(new BorderLayout());
		setOpaque(false);
		picker = new ActivityCharts.Segmented(PERIOD_LABELS, period, new Dimension(220, 32), i ->
		{
			period = i;
			refresh();
		});
		list.setBorder(BorderFactory.createEmptyBorder(8, 8, FloatingAsk.CLEARANCE, 8));
		JScrollPane scroll = new JScrollPane(list);
		scroll.setOpaque(false);
		scroll.getViewport().setOpaque(false);
		scroll.setBorder(BorderFactory.createEmptyBorder());
		scroll.setHorizontalScrollBarPolicy(ScrollPaneConstants.HORIZONTAL_SCROLLBAR_NEVER);
		scroll.getVerticalScrollBar().setUnitIncrement(16);
		add(scroll, BorderLayout.CENTER);
	}

	String pageTitle()
	{
		return boss == null ? "Boss" : boss;
	}

	void show(String name)
	{
		boss = name;
		shown = null;
		message("Loading " + name + "...");
		refresh();
	}

	/** For previews: show a boss from data instead of loading it. */
	void showData(JsonObject data)
	{
		boss = str(data, "boss");
		shown = data;
		render(data);
	}

	void refresh()
	{
		if (boss == null)
		{
			return;
		}
		int id = ++requestId;
		api.boss(boss, PERIODS[period], r -> SwingUtilities.invokeLater(() ->
		{
			if (id != requestId)
			{
				return;
			}
			if (r.json == null || r.json.has("error"))
			{
				message(r.json != null ? str(r.json, "error") : r.error);
				return;
			}
			shown = r.json;
			render(r.json);
		}));
	}

	/** This boss's numbers, as context for a question asked from this page. */
	Attachment contextAttachment()
	{
		if (shown == null)
		{
			return null;
		}
		StringBuilder md = new StringBuilder("# ").append(str(shown, "boss")).append("\n\n");
		md.append("Kill count: ").append(fmt(num(shown, "count"))).append("\n");
		for (JsonElement e : shown.getAsJsonArray("personalBests"))
		{
			JsonObject p = e.getAsJsonObject();
			if (p.has("personal_best") && !p.get("personal_best").isJsonNull())
			{
				md.append("PB (").append(str(p, "activity")).append("): ").append(ProgressDetailView.clock(num(p, "personal_best"))).append("\n");
			}
		}
		JsonObject g = obj(shown, "gains");
		if (g != null && !g.has("error") && g.has("gained") && !g.get("gained").isJsonNull())
		{
			md.append(period == 3 ? "Kills, all time" : "Kills in the last " + PERIODS[period]).append(": ").append(fmt(num(g, "gained"))).append("\n");
		}
		return Attachment.context(str(shown, "boss"), str(shown, "boss"), md.toString(), SquireIcon.create(26));
	}

	private void message(String text)
	{
		list.removeAll();
		list.add(ChatComponents.place(small(text == null ? "" : text), Align.FILL, 12));
		relayout();
	}

	private void render(JsonObject o)
	{
		list.removeAll();
		String name = str(o, "boss");
		list.add(ChatComponents.place(Ui.withAsk(headerCard(o), "How can I get faster, more consistent kills at " + name + "?"), Align.FILL, 0));
		list.add(ChatComponents.place(picker, Align.FILL, 8));
		JsonObject gains = obj(o, "gains");
		if (gains != null && !gains.has("error"))
		{
			list.add(ChatComponents.place(GainedView.metricCard(gains), Align.FILL, 8));
		}
		JComponent pbs = personalBestsCard(o.getAsJsonArray("personalBests"));
		if (pbs != null)
		{
			list.add(ChatComponents.place(Ui.withAsk(pbs, "What's holding back my " + name + " times?"), Align.FILL, 8));
		}
		JComponent loot = lootCard(obj(o, "loot"));
		if (loot != null)
		{
			list.add(ChatComponents.place(Ui.withAsk(loot, "Am I dry at " + name + "?"), Align.FILL, 8));
		}
		relayout();
	}

	private JComponent headerCard(JsonObject o)
	{
		Surface c = HomeView.homeCard();
		JPanel top = new JPanel(new BorderLayout(12, 0));
		top.setOpaque(false);
		ProgressView.BossPicture pic = new ProgressView.BossPicture();
		if (images != null && o.has("image") && !o.get("image").isJsonNull())
		{
			images.load(str(o, "image"), pic::setImage);
		}
		top.add(pic, BorderLayout.WEST);
		JPanel side = new JPanel();
		side.setLayout(new BoxLayout(side, BoxLayout.Y_AXIS));
		side.setOpaque(false);
		JLabel count = bold(fmt(num(o, "count")));
		count.setFont(FontManager.getRunescapeBoldFont().deriveFont(22f));
		side.add(row(count, null));
		side.add(row(text("kills · " + ProgressDetailView.categoryLabel(str(o, "category")), ChatComponents.MUTED), null));
		if (o.has("lastKill") && !o.get("lastKill").isJsonNull())
		{
			side.add(row(small("Last kill " + ago(str(o, "lastKill"))), null));
		}
		top.add(side, BorderLayout.CENTER);
		top.setAlignmentX(LEFT_ALIGNMENT);
		top.setMaximumSize(new Dimension(Integer.MAX_VALUE, top.getPreferredSize().height));
		c.add(top);
		return c;
	}

	/** Each PB (per team size for raids): the time, recent average and gap, how it improved, and the fastest setups. */
	private JComponent personalBestsCard(JsonArray pbs)
	{
		if (pbs == null || pbs.size() == 0)
		{
			return null;
		}
		Surface c = HomeView.listCard();
		for (JsonElement e : pbs)
		{
			JsonObject p = e.getAsJsonObject();
			if (!p.has("personal_best") || p.get("personal_best").isJsonNull())
			{
				continue;
			}
			JPanel head = new JPanel();
			head.setLayout(new BoxLayout(head, BoxLayout.Y_AXIS));
			head.setOpaque(false);
			head.setBorder(BorderFactory.createEmptyBorder(10, 12, 10, 12));
			head.add(row(bold("Personal best" + (pbs.size() > 1 ? ": " + str(p, "activity") : "")), null));
			head.add(Box.createVerticalStrut(6));
			JLabel time = bold(ProgressDetailView.clock(num(p, "personal_best")));
			time.setFont(FontManager.getRunescapeBoldFont().deriveFont(18f));
			time.setForeground(ChatComponents.ACCENT);
			JLabel avg = null;
			if (p.has("recent_average_seconds") && !p.get("recent_average_seconds").isJsonNull())
			{
				avg = bold(ProgressDetailView.clock(num(p, "recent_average_seconds")));
				avg.setFont(FontManager.getRunescapeBoldFont().deriveFont(18f));
			}
			head.add(row(time, avg));
			String gap = p.has("recent_gap_to_pb_pct") && !p.get("recent_gap_to_pb_pct").isJsonNull() ? " (+" + (int) num(p, "recent_gap_to_pb_pct") + "%)" : "";
			head.add(row(text("personal best", ChatComponents.MUTED), avg == null ? null : text("recent average" + gap, ChatComponents.MUTED)));
			head.setAlignmentX(LEFT_ALIGNMENT);
			c.add(head);

			JsonArray history = p.getAsJsonArray("history");
			// Newest improvements first
			for (int i = history.size() - 1, shownRows = 0; i >= 0 && shownRows < 5; i--, shownRows++)
			{
				JsonObject h = history.get(i).getAsJsonObject();
				c.add(HomeView.divider());
				JComponent r = HomeView.listRow(HomeView.dotIcon(i == history.size() - 1 ? ChatComponents.ACCENT : ChatComponents.BORDER),
					str(h, "time"), small(ago(str(h, "ts"))), null);
				JsonElement gear = h.get("gear");
				if (gear != null && gear.isJsonArray())
				{
					List<String> names = new java.util.ArrayList<>();
					gear.getAsJsonArray().forEach(g -> names.add(g.getAsString()));
					r.setToolTipText("Wearing " + String.join(", ", names));
				}
				c.add(r);
			}
			JsonArray setups = p.getAsJsonArray("by_setup");
			if (setups != null && setups.size() > 1)
			{
				c.add(HomeView.divider());
				c.add(HomeView.listRow(null, "Fastest by setup", null, null));
				for (JsonElement s : setups)
				{
					JsonObject x = s.getAsJsonObject();
					c.add(HomeView.divider());
					String gearNames = str(x, "gear");
					String label = gearNames.length() > 36 ? gearNames.substring(0, 35) + "…" : gearNames;
					JComponent r = HomeView.listRow(null, label, text(ProgressDetailView.clock(num(x, "best_seconds")) + " · " + fmt(num(x, "kills")) + " kills", Color.WHITE), null);
					r.setToolTipText(gearNames);
					c.add(r);
				}
			}
		}
		return c.getComponentCount() == 0 ? null : c;
	}

	private JComponent lootCard(JsonObject loot)
	{
		if (loot == null || num(loot, "drops") == 0)
		{
			return null;
		}
		Surface c = HomeView.listCard();
		JPanel head = new JPanel();
		head.setLayout(new BoxLayout(head, BoxLayout.Y_AXIS));
		head.setOpaque(false);
		head.setBorder(BorderFactory.createEmptyBorder(10, 12, 10, 12));
		head.add(row(bold("Loot"), null));
		head.add(Box.createVerticalStrut(6));
		JLabel value = bold(shortNumber(num(loot, "value")) + " gp");
		value.setFont(FontManager.getRunescapeBoldFont().deriveFont(18f));
		head.add(row(value, null));
		head.add(row(text("from " + fmt(num(loot, "drops")) + " drops", ChatComponents.MUTED), null));
		head.setAlignmentX(LEFT_ALIGNMENT);
		c.add(head);
		for (JsonElement e : loot.getAsJsonArray("items"))
		{
			JsonObject item = e.getAsJsonObject();
			BufferedImage img = Crest.itemImage((int) num(item, "id"), this);
			c.add(HomeView.divider());
			c.add(HomeView.listRow(img == null ? null : new ImageIcon(img), str(item, "name") + " x" + fmt(num(item, "quantity")),
				text(shortNumber(num(item, "value")), Color.WHITE), null));
		}
		return c;
	}

	private void relayout()
	{
		list.revalidate();
		list.repaint();
	}
}

package com.squire;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.io.BufferedReader;
import java.io.IOException;
import java.io.InterruptedIOException;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.concurrent.Executors;
import java.util.concurrent.RejectedExecutionException;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;
import java.util.function.Supplier;
import lombok.extern.slf4j.Slf4j;
import okhttp3.Call;
import okhttp3.HttpUrl;
import okhttp3.MediaType;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.RequestBody;
import okhttp3.Response;
import okhttp3.ResponseBody;

/**
 * Talks to the Squire agent (eve) over its session HTTP API: create a session, post messages,
 * and follow the NDJSON event stream for each turn.
 */
@Slf4j
class ChatClient
{
	interface Listener
	{
		/** Assistant text as it streams in. */
		void onDelta(String text);

		/** One assistant text block finished (a turn can have several around tool calls). */
		void onBlockCompleted();

		/** The agent started calling tools. */
		void onToolUse(String description);

		/** A piece of the model's (summarized) thinking. */
		default void onReasoning(String delta)
		{
		}

		/** One block of thinking finished. */
		default void onReasoningDone()
		{
		}

		/** The raw tool calls the agent made (callId, kind, toolName, input), for the Steps panel. */
		default void onActions(JsonArray actions)
		{
		}

		/** A tool call finished; output is the tool's result (MCP content or plain JSON). */
		default void onActionResult(String callId, JsonElement output, boolean ok)
		{
		}

		void onError(String message);

		/** The turn is over and the session is ready for another message. */
		void onDone();
	}

	private static final MediaType JSON = MediaType.parse("application/json; charset=utf-8");
	private static final int MAX_STREAM_RECONNECTS = 5;
	private static final long NOT_READY_RETRY_MS = 20_000;

	private final OkHttpClient http;
	private final Gson gson;
	private final Supplier<String> endpoint;
	private final Supplier<String> token;
	private final Supplier<String> model;
	/** The logged-in account's hash, so the agent's memory is kept per account (null when logged out). */
	private Supplier<String> account = () -> null;
	// The connection's thread; turns run one at a time, in order (see enqueue)
	private final ScheduledExecutorService worker = Executors.newSingleThreadScheduledExecutor(r ->
	{
		Thread t = new Thread(r, "squire-chat");
		t.setDaemon(true);
		return t;
	});
	// Turns waiting their go; each is handed a callback to run when it's finished (retries included)
	private final java.util.ArrayDeque<java.util.function.Consumer<Runnable>> turns = new java.util.ArrayDeque<>();
	private boolean turnRunning;

	private volatile String sessionId;
	// Absolute count of stream events already consumed, so each turn reads only its own events
	private volatile int streamIndex;
	private volatile Call activeStream;

	ChatClient(OkHttpClient http, Gson gson, Supplier<String> endpoint, Supplier<String> token, Supplier<String> model)
	{
		this.model = model;
		// Streams stay open while the model thinks and tools run
		this.http = http.newBuilder().readTimeout(90, TimeUnit.SECONDS).build();
		this.gson = gson;
		this.endpoint = endpoint;
		this.token = token;
	}

	void setAccount(Supplier<String> account)
	{
		this.account = account;
	}

	void send(String message, Map<String, Object> clientContext, Listener listener)
	{
		send(message, java.util.List.of(), clientContext, listener, null);
	}

	/** The server session this conversation continues (saved with the chat history). */
	String sessionId()
	{
		return sessionId;
	}

	/** The index of the next stream event; a resumed session reads on from here, not from the start. */
	int streamIndex()
	{
		return streamIndex;
	}

	void resume(String sessionId, int streamIndex)
	{
		this.sessionId = sessionId;
		this.streamIndex = streamIndex;
	}

	/**
	 * Sends a message; with attachments it goes as content parts (text, then files/images). {@code recap} is the
	 * conversation so far, sent only if the server has to start a new session for it (e.g. a chat reopened
	 * from the history after its session expired), so the agent still has the earlier messages.
	 */
	void send(String message, java.util.List<Attachment> attachments, Map<String, Object> clientContext, Listener listener, String recap)
	{
		pendingRecap = recap;
		Object content = message;
		if (!attachments.isEmpty())
		{
			java.util.List<Object> parts = new java.util.ArrayList<>();
			Map<String, Object> text = new LinkedHashMap<>();
			text.put("type", "text");
			text.put("text", message.isEmpty() ? "(see attached)" : message);
			parts.add(text);
			attachments.forEach(a -> parts.add(a.toPart()));
			content = parts;
		}
		Object body = content;
		enqueue(done -> attempt(body, clientContext, listener, System.currentTimeMillis() + NOT_READY_RETRY_MS, 250, done));
	}

	/** Run turns one after another: the next starts only when the one before calls its finished callback. */
	private void enqueue(java.util.function.Consumer<Runnable> turn)
	{
		synchronized (turns)
		{
			turns.add(turn);
			if (turnRunning)
			{
				return;
			}
			turnRunning = true;
		}
		worker.execute(this::nextTurn);
	}

	private void nextTurn()
	{
		java.util.function.Consumer<Runnable> turn;
		synchronized (turns)
		{
			turn = turns.poll();
			if (turn == null)
			{
				turnRunning = false;
				return;
			}
		}
		turn.accept(() ->
		{
			try
			{
				worker.execute(this::nextTurn);
			}
			catch (RejectedExecutionException shutDown)
			{
				// The chat closed
			}
		});
	}

	/** Send the message and follow the reply. While the session is still starting, try again shortly (without blocking). */
	private void attempt(Object body, Map<String, Object> clientContext, Listener listener, long deadline, long backoff, Runnable done)
	{
		try
		{
			if (!postMessage(body, clientContext, deadline))
			{
				worker.schedule(() -> attempt(body, clientContext, listener, deadline, Math.min(backoff * 2, 2000), done),
					backoff, TimeUnit.MILLISECONDS);
				return;
			}
			followTurn(listener);
		}
		catch (Exception e)
		{
			log.warn("Squire chat failed", e);
			listener.onError(e.getMessage() != null ? e.getMessage() : e.toString());
		}
		done.run();
	}

	/** Stops the in-flight turn; the stream then reports turn.cancelled and the session waits again. */
	void cancel()
	{
		String id = sessionId;
		if (id == null)
		{
			return;
		}
		Request request = authed(url("eve/v1/session/" + id + "/cancel"))
			.post(RequestBody.create(JSON, "{}"))
			.build();
		http.newCall(request).enqueue(new okhttp3.Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				log.debug("Cancel failed", e);
			}

			@Override
			public void onResponse(Call call, Response response)
			{
				response.close();
			}
		});
	}

	/** Forget the conversation; the next message starts a fresh session. */
	void reset()
	{
		Call stream = activeStream;
		if (stream != null)
		{
			stream.cancel();
		}
		sessionId = null;
		streamIndex = 0;
	}

	void shutdown()
	{
		reset();
		worker.shutdownNow();
	}

	private volatile String pendingRecap;

	/** Post the message; false when the session isn't ready for it yet (and there's still time to wait). */
	private boolean postMessage(Object message, Map<String, Object> clientContext, long deadline) throws IOException
	{
		Map<String, Object> body = new LinkedHashMap<>();
		String recap = pendingRecap;
		if (sessionId == null && recap != null && !recap.isEmpty())
		{
			// A fresh session for an existing conversation: lead with what was said before
			java.util.List<Object> parts = new java.util.ArrayList<>();
			Map<String, Object> earlier = new LinkedHashMap<>();
			earlier.put("type", "text");
			earlier.put("text", "Earlier in this conversation (restored from the chat history):\n\n" + recap + "\n\n---\nThe player's new message:");
			parts.add(earlier);
			if (message instanceof java.util.List)
			{
				parts.addAll((java.util.List<?>) message);
			}
			else
			{
				Map<String, Object> text = new LinkedHashMap<>();
				text.put("type", "text");
				text.put("text", message);
				parts.add(text);
			}
			body.put("message", parts);
		}
		else
		{
			body.put("message", message);
		}
		if (clientContext != null && !clientContext.isEmpty())
		{
			body.put("clientContext", clientContext);
		}

		if (sessionId == null)
		{
			JsonObject created = postJson("eve/v1/session", body);
			sessionId = created.get("sessionId").getAsString();
			streamIndex = 0;
			return true;
		}

		try
		{
			postJson("eve/v1/session/" + sessionId, body);
			return true;
		}
		catch (HttpError e)
		{
			if (e.status == 409 && System.currentTimeMillis() < deadline && (e.getMessage() == null || !e.getMessage().contains("session_not_active")))
			{
				// session_not_ready: the durable inbox is still starting
				return false;
			}
			if (e.status == 404 || e.status == 410 || (e.status == 409 && e.getMessage() != null && e.getMessage().contains("session_not_active")))
			{
				// Session expired, ended or was reset: start a new one with this message (and the recap)
				sessionId = null;
				return postMessage(message, clientContext, deadline);
			}
			throw e;
		}
	}

	private void followTurn(Listener listener) throws IOException
	{
		boolean turnStarted = false;
		// One failure is reported as both turn.failed and session.failed: show it once, and don't reconnect after it
		boolean failed = false;
		for (int attempt = 0; attempt <= MAX_STREAM_RECONNECTS; attempt++)
		{
			HttpUrl url = url("eve/v1/session/" + sessionId + "/stream").newBuilder()
				.addQueryParameter("startIndex", Integer.toString(streamIndex))
				.build();
			Call call = http.newCall(authed(url).get().build());
			activeStream = call;
			try (Response response = call.execute())
			{
				if (!response.isSuccessful())
				{
					throw new HttpError(response.code(), bodyText(response));
				}
				ResponseBody body = response.body();
				if (body == null)
				{
					throw new IOException("Empty stream response");
				}
				BufferedReader reader = new BufferedReader(body.charStream());
				String line;
				while ((line = reader.readLine()) != null)
				{
					if (line.isBlank())
					{
						continue;
					}
					streamIndex++;
					JsonObject event = gson.fromJson(line, JsonObject.class);
					String type = event.get("type").getAsString();
					JsonObject data = event.has("data") && event.get("data").isJsonObject() ? event.getAsJsonObject("data") : new JsonObject();

					switch (type)
					{
						case "turn.started":
							turnStarted = true;
							break;
						case "message.appended":
							listener.onDelta(string(data, "messageDelta"));
							break;
						case "message.completed":
							listener.onBlockCompleted();
							break;
						case "actions.requested":
							listener.onToolUse(describeActions(data));
							if (data.has("actions") && data.get("actions").isJsonArray())
							{
								listener.onActions(data.getAsJsonArray("actions"));
							}
							break;
						case "reasoning.appended":
							listener.onReasoning(string(data, "reasoningDelta"));
							break;
						case "reasoning.completed":
							listener.onReasoningDone();
							break;
						case "action.result":
						{
							JsonObject result = data.has("result") && data.get("result").isJsonObject() ? data.getAsJsonObject("result") : new JsonObject();
							listener.onActionResult(string(result, "callId"), result.get("output"), "completed".equals(string(data, "status")) || !data.has("status"));
							break;
						}
						case "turn.failed":
						case "session.failed":
							if (!failed)
							{
								failed = true;
								listener.onError(string(data, "message"));
							}
							if ("session.failed".equals(type))
							{
								// The session can't take more turns; the next message starts a new one
								sessionId = null;
								return;
							}
							break;
						case "session.waiting":
						case "session.completed":
							// A waiting event before our turn began belongs to an earlier turn
							if (turnStarted || "session.completed".equals(type))
							{
								if ("session.completed".equals(type))
								{
									sessionId = null;
								}
								listener.onDone();
								return;
							}
							break;
						default:
							break;
					}
				}
			}
			catch (InterruptedIOException e)
			{
				// Read timeout or stream lease ended; reconnect from our cursor
				if (call.isCanceled())
				{
					return;
				}
				log.debug("Chat stream interrupted, reconnecting from {}", streamIndex);
				continue;
			}
			catch (IOException e)
			{
				if (call.isCanceled())
				{
					return;
				}
				if (attempt == MAX_STREAM_RECONNECTS)
				{
					throw e;
				}
				continue;
			}
			finally
			{
				activeStream = null;
			}
			if (failed)
			{
				// The turn already ended in an error the player has seen
				return;
			}
			// Server closed the stream cleanly mid-turn (lease renewal): reconnect
		}
		throw new IOException("Lost connection to the chat stream");
	}

	private static String describeActions(JsonObject data)
	{
		JsonElement actions = data.get("actions");
		if (actions != null && actions.isJsonArray())
		{
			StringBuilder names = new StringBuilder();
			for (JsonElement a : (JsonArray) actions)
			{
				if (!a.isJsonObject())
				{
					continue;
				}
				String name = firstString(a.getAsJsonObject(), "toolName", "name");
				if (name != null)
				{
					// connection tools arrive as "osrs__get_gear"
					if (name.equals("connection_search"))
					{
						name = "finding account tools";
					}
					name = name.replaceFirst("^osrs__", "").replace('_', ' ');
					if (names.length() > 0)
					{
						names.append(", ");
					}
					names.append(name);
				}
			}
			if (names.length() > 0)
			{
				return names.toString();
			}
		}
		return "looking something up";
	}

	private static String firstString(JsonObject o, String... keys)
	{
		for (String k : keys)
		{
			if (o.has(k) && o.get(k).isJsonPrimitive())
			{
				return o.get(k).getAsString();
			}
		}
		return null;
	}

	private static String string(JsonObject o, String key)
	{
		JsonElement e = o.get(key);
		return e != null && e.isJsonPrimitive() ? e.getAsString() : "";
	}

	private JsonObject postJson(String path, Object body) throws IOException
	{
		Request request = authed(url(path)).post(RequestBody.create(JSON, gson.toJson(body))).build();
		try (Response response = http.newCall(request).execute())
		{
			String text = bodyText(response);
			if (!response.isSuccessful())
			{
				throw new HttpError(response.code(), text);
			}
			return gson.fromJson(text, JsonObject.class);
		}
	}

	private Request.Builder authed(HttpUrl url)
	{
		Request.Builder b = new Request.Builder().url(url)
			.header("Authorization", "Bearer " + token.get().trim())
			.header("X-Squire-Model", model.get());
		String hash = account.get();
		if (hash != null)
		{
			b.header("X-Squire-Account", hash);
		}
		return b;
	}

	private HttpUrl url(String path)
	{
		HttpUrl base = HttpUrl.parse(endpoint.get().trim());
		if (base == null)
		{
			throw new IllegalStateException("Set the server URL in the Squire settings");
		}
		return base.newBuilder().addPathSegments(path).build();
	}

	private static String bodyText(Response response) throws IOException
	{
		ResponseBody body = response.body();
		return body == null ? "" : body.string();
	}

	static class HttpError extends IOException
	{
		final int status;

		HttpError(int status, String body)
		{
			super(status == 401 ? "Not authorized; turn Squire on again from its Home page" : "Server returned " + status + ": " + body);
			this.status = status;
		}
	}
}

package com.squire;

import java.awt.BorderLayout;
