	}

	/** A grooved divider (dark line over a lighter line), as around the typing row. */
	static void groove(Graphics g, int y, int width)
	{
		g.setColor(OUTLINE);
		g.fillRect(0, y, width, 1);
		g.setColor(PANEL_BG);
		g.fillRect(0, y + 1, width, 1);
	}

