/**
 * The Chats page: every conversation, newest first. Ones still answering show the Leap spinner; ones that
 * finished while you were elsewhere show a dot. Click to open; hover for the delete button (click it twice).
 */
class ChatHistoryView extends JPanel
{
	private final ChatSessions sessions;
	private final Consumer<String> open;
	private final Runnable newChat;
	private final MessageList list = new MessageList(null, 0);
	private String renderedKey = "";

	ChatHistoryView(ChatSessions sessions, Consumer<String> open, Runnable newChat)
	{
		super(new BorderLayout());
		this.sessions = sessions;
		this.open = open;
		this.newChat = newChat;
		setOpaque(false);
		list.setBorder(BorderFactory.createEmptyBorder(1, 1, 8, 1));
		JScrollPane scroll = new JScrollPane(list);
		scroll.setOpaque(false);
		scroll.getViewport().setOpaque(false);
		scroll.setBorder(BorderFactory.createEmptyBorder());
		scroll.setHorizontalScrollBarPolicy(ScrollPaneConstants.HORIZONTAL_SCROLLBAR_NEVER);
		scroll.getVerticalScrollBar().setUnitIncrement(16);
		add(scroll);
		sessions.addListener(() ->
		{
			if (isShowing())
			{
				render();
			}
		});
		render();
	}

	/** Rebuild if anything the list shows changed (cheap to call on every show). */
	void onShown()
	{
		render();
	}

	private void render()
	{
		List<ChatSessions.Chat> chats = sessions.chats();
		StringBuilder key = new StringBuilder();
		long now = System.currentTimeMillis();
		for (ChatSessions.Chat c : chats)
		{
			key.append(c.id).append(c.title).append(c.updatedAt).append(c.running()).append(c.unread).append(ago(c.updatedAt, now)).append('|');
		}
		if (key.toString().equals(renderedKey))
		{
			return;
		}
		renderedKey = key.toString();

		list.removeAll();
		Surface top = HomeView.listCard();
		top.add(HomeView.listRow(SvgIcon.load("new-chat", 16, null), "New chat", null, newChat));
		list.add(ChatComponents.place(top, Align.FILL, 0));

		if (chats.isEmpty())
		{
			JLabel none = Ui.small("Your conversations will be listed here.");
			none.setBorder(BorderFactory.createEmptyBorder(12, 12, 0, 0));
			list.add(ChatComponents.place(none, Align.LEFT, 4));
		}
		else
		{
			Surface card = HomeView.listCard();
			for (int i = 0; i < chats.size(); i++)
			{
				if (i > 0)
				{
					card.add(HomeView.divider());
				}
				card.add(row(chats.get(i), now));
			}
			list.add(ChatComponents.place(Ui.sectionLabel("Chats"), Align.LEFT, 12));
			list.add(ChatComponents.place(card, Align.FILL, 4));
		}
		list.revalidate();
		list.repaint();
	}

	private JComponent row(ChatSessions.Chat chat, long now)
	{
		Surface r = new Surface(null, 0, false);
		r.setLayout(new BorderLayout(8, 0));
		r.setBorder(BorderFactory.createEmptyBorder(6, 12, 6, 12));

		JPanel words = new JPanel();
		words.setOpaque(false);
		words.setLayout(new BoxLayout(words, BoxLayout.Y_AXIS));
		JLabel title = new JLabel(chat.title);
		title.setFont(chat.unread ? FontManager.getRunescapeBoldFont() : FontManager.getRunescapeFont());
		title.setForeground(chat.unread ? Color.WHITE : ColorScheme.LIGHT_GRAY_COLOR);
		JLabel preview = Ui.small(chat.running() ? "Working..." : chat.preview);
		title.setAlignmentX(Component.LEFT_ALIGNMENT);
		preview.setAlignmentX(Component.LEFT_ALIGNMENT);
		words.add(title);
		words.add(preview);
		r.add(words, BorderLayout.CENTER);

		// Right: spinner while working, a dot when there's an unseen answer, else how long ago; delete on hover
		JPanel right = new JPanel(new BorderLayout());
		right.setOpaque(false);
		JComponent status = chat.running() ? ChatTraceViews.spinner(ChatComponents.ACCENT)
			: chat.unread ? unreadDot() : Ui.small(ago(chat.updatedAt, now));
		JLabel delete = Ui.small("x");
		delete.setToolTipText("Delete this chat");
		delete.setBorder(BorderFactory.createEmptyBorder(0, 6, 0, 2));
		delete.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		delete.setVisible(false);
		JPanel stack = new JPanel(new java.awt.GridBagLayout());
		stack.setOpaque(false);
		stack.add(status);
		stack.add(delete);
		right.add(stack, BorderLayout.CENTER);
		r.add(right, BorderLayout.EAST);
		r.setAlignmentX(LEFT_ALIGNMENT);
		r.setMaximumSize(new Dimension(Integer.MAX_VALUE, r.getPreferredSize().height));
		r.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));

		MouseAdapter hover = new MouseAdapter()
		{
			@Override
			public void mouseReleased(MouseEvent e)
			{
				// On release rather than click: Swing drops a click if the pointer moves a pixel while pressed
				if (!javax.swing.SwingUtilities.isLeftMouseButton(e) || !e.getComponent().contains(e.getPoint()))
				{
					return;
				}
				open.accept(chat.id);
			}

			@Override
			public void mouseEntered(MouseEvent e)
			{
				r.setFill(ChatComponents.HOVER_BG);
				delete.setVisible(!chat.running());
			}

			@Override
			public void mouseExited(MouseEvent e)
			{
				if (!r.contains(SwingUtilities.convertPoint(e.getComponent(), e.getPoint(), r)))
				{
					r.setFill(null);
					delete.setVisible(false);
					delete.setText("x");
				}
			}
		};
		for (Component c : new Component[]{r, words, title, preview, right, stack, status})
		{
			c.addMouseListener(hover);
		}
		delete.addMouseListener(new MouseAdapter()
		{
			@Override
			public void mouseReleased(MouseEvent e)
			{
				// On release rather than click: Swing drops a click if the pointer moves a pixel while pressed
				if (!javax.swing.SwingUtilities.isLeftMouseButton(e) || !e.getComponent().contains(e.getPoint()))
				{
					return;
				}
				// Two clicks: "x" becomes "Delete?", then it goes
				if ("x".equals(delete.getText()))
				{
					delete.setText("Delete?");
					delete.setForeground(Tokens.COLOR_TEXT_ERROR);
				}
				else
				{
					sessions.delete(chat.id);
				}
			}

			@Override
			public void mouseExited(MouseEvent e)
			{
				hover.mouseExited(e);
			}
		});
		return r;
	}

	private static JComponent unreadDot()
	{
		JComponent d = new JComponent()
		{
			@Override
			protected void paintComponent(Graphics g)
			{
				Graphics2D g2 = (Graphics2D) g.create();
				g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
				g2.setColor(ChatComponents.ACCENT);
				Pixel.fill(g2, (getWidth() - 8) / 2, (getHeight() - 8) / 2, 8, 8, 2);
				g2.dispose();
			}
		};
		d.setPreferredSize(new Dimension(16, 16));
		d.setToolTipText("New reply");
		return d;
	}

	/** "now", "5m", "3h", "2d", "4w". */
	static String ago(long at, long now)
	{
		long s = Math.max(0, (now - at) / 1000);
		if (s < 60)
		{
			return "now";
		}
		if (s < 3600)
		{
			return (s / 60) + "m";
		}
		if (s < 86400)
		{
			return (s / 3600) + "h";
		}
		if (s < 86400 * 14)
		{
			return (s / 86400) + "d";
		}
		return (s / (86400 * 7)) + "w";
	}
}

package com.squire;

import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.concurrent.CopyOnWriteArrayList;
import java.util.function.Consumer;
import java.util.function.Supplier;
import javax.swing.SwingUtilities;

/**
 * All of the player's conversations: the one on screen, others still answering in the background, and the saved
 * history. Each conversation has its own view and its own connection to the agent, so several can run at once.
 * Saved chats are only rebuilt into a view when opened. Swing thread only.
 */
class ChatSessions
{
	static final class Chat
	{
		final String id;
		String title;
		long updatedAt;
		/** The last thing said, for the history list. */
		String preview = "";
		/** Built when the chat is first opened; until then only the saved record exists. */
		ChatView view;
		private JsonObject saved;
		/** Finished answering while the player was looking at something else. */
		boolean unread;
		/** When it was last on screen, to unload the least recently used. */
		long shownAt;
		/** The conversation held through the game's chatbox. */
		boolean inGame;

		private Chat(String id)
		{
			this.id = id;
		}

		boolean running()
		{
			return view != null && view.isBusy();
		}

		boolean hasMessages()
		{
			return view != null ? view.hasConversation() : saved != null;
		}
	}

	private final Supplier<ChatView> factory;
	private final ChatStore store;
	private final List<Chat> chats = new ArrayList<>();
	private final List<Runnable> listeners = new CopyOnWriteArrayList<>();
	private Consumer<ChatView> onCurrent = v -> {};
	private Consumer<ChatView> onUnloaded = v -> {};
	/** Chats kept built besides the one on screen and any still answering; older ones go back to their record. */
	private static final int KEEP_LOADED = 3;
	private Chat current;

	/** {@code store} may be null (previews): nothing is loaded or saved. */
	ChatSessions(Supplier<ChatView> factory, ChatStore store)
	{
		this.factory = factory;
		this.store = store;
		current = create();
	}

	/** Read the saved history (in the background) and list it. */
	void load()
	{
		if (store == null)
		{
			return;
		}
		store.loadAll(records -> SwingUtilities.invokeLater(() ->
		{
			records.forEach(this::addSaved);
			changed();
		}));
	}

	/** List a saved conversation (from disk); its view is built when it's opened. */
	Chat addSaved(JsonObject r)
	{
		String id = r.get("id").getAsString();
		Chat existing = find(id);
		if (existing != null)
		{
			return existing;
		}
		Chat c = new Chat(id);
		c.saved = r;
		c.title = r.has("title") ? r.get("title").getAsString() : "Chat";
		c.updatedAt = r.has("updatedAt") ? r.get("updatedAt").getAsLong() : 0;
		c.preview = previewOf(r.has("turns") ? r.getAsJsonArray("turns") : new JsonArray());
		c.inGame = r.has("inGame") && r.get("inGame").getAsBoolean();
		chats.add(c);
		return c;
	}

	void addListener(Runnable listener)
	{
		listeners.add(listener);
	}

	/** Told whenever a different conversation comes on screen. */
	void setOnCurrent(Consumer<ChatView> onCurrent)
	{
		this.onCurrent = onCurrent;
	}

	/** Told when a conversation's view is dropped (unloaded or deleted), so the panel can let go of it. */
	void setOnUnloaded(Consumer<ChatView> onUnloaded)
	{
		this.onUnloaded = onUnloaded;
	}

	ChatView current()
	{
		return current.view;
	}

	Chat currentChat()
	{
		return current;
	}

	/** Conversations with messages, most recent first. */
	List<Chat> chats()
	{
		List<Chat> out = new ArrayList<>();
		for (Chat c : chats)
		{
			if (c.hasMessages())
			{
				out.add(c);
			}
		}
		out.sort(Comparator.comparingLong((Chat c) -> c.updatedAt).reversed());
		return out;
	}

	/** Show an empty conversation, reusing the current one if nothing has been said in it yet. */
	ChatView newChat()
	{
		if (!current.hasMessages() && !current.running())
		{
			current.view.focusInput();
			return current.view;
		}
		Chat c = create();
		show(c);
		return c.view;
	}

	/** Start a new conversation with this message (Home's prompts and composer). */
	void startWith(String message, java.util.List<Attachment> context)
	{
		newChat().startWith(message, context);
	}

	void startWith(String message)
	{
		newChat().startWith(message);
	}

	void open(String id)
	{
		Chat c = find(id);
		if (c == null)
		{
			return;
		}
		if (c.view == null)
		{
			c.view = factory.get();
			c.view.restore(c.saved);
			c.saved = null;
			wire(c);
		}
		show(c);
	}

	/**
	 * The conversation for questions asked in the game's chatbox: the latest in-game chat if it was active in the
	 * last couple of hours, else a new one. Built if needed but not brought on screen.
	 */
	ChatView inGame(Consumer<ChatView> setUp)
	{
		Chat found = null;
		for (Chat c : chats)
		{
			if (c.inGame && System.currentTimeMillis() - c.updatedAt < IN_GAME_CONTINUES_MS && (found == null || c.updatedAt > found.updatedAt))
			{
				found = c;
			}
		}
		if (found == null)
		{
			found = create();
			found.inGame = true;
		}
		else if (found.view == null)
		{
			found.view = factory.get();
			found.view.restore(found.saved);
			found.saved = null;
			wire(found);
		}
		found.shownAt = System.nanoTime();
		setUp.accept(found.view);
		return found.view;
	}

	private static final long IN_GAME_CONTINUES_MS = 2 * 3_600_000L;

	/** Forget a conversation (the player deleted it from the list). */
	void delete(String id)
	{
		Chat c = find(id);
		if (c == null)
		{
			return;
		}
		chats.remove(c);
		if (c.view != null)
		{
			onUnloaded.accept(c.view);
			c.view.close();
		}
		if (store != null)
		{
			store.delete(id);
		}
		if (c == current)
		{
			current = create();
			onCurrent.accept(current.view);
		}
		changed();
	}

	/** Every conversation that has a view (open now or earlier this session). */
	void forEachView(Consumer<ChatView> action)
	{
		for (Chat c : chats)
		{
			if (c.view != null)
			{
				action.accept(c.view);
			}
		}
	}

	/** Forget every conversation (the player deleted their data); a fresh empty chat comes on screen. */
	void clearAll()
	{
		for (Chat c : new java.util.ArrayList<>(chats))
		{
			if (c.view != null)
			{
				onUnloaded.accept(c.view);
				c.view.close();
			}
		}
		chats.clear();
		current = create();
		onCurrent.accept(current.view);
		changed();
	}

	void shutdown()
	{
		for (Chat c : chats)
		{
			if (c.view != null)
			{
				c.view.close();
			}
		}
		if (store != null)
		{
			store.shutdown();
		}
	}

	private Chat create()
	{
		ChatView view = factory.get();
		Chat c = new Chat(view.id());
		c.view = view;
		c.shownAt = System.nanoTime();
		c.title = view.title();
		c.updatedAt = System.currentTimeMillis();
		wire(c);
		chats.add(c);
		return c;
	}

	private void show(Chat c)
	{
		current = c;
		c.unread = false;
		c.shownAt = System.nanoTime();
		// Leave at most one empty conversation lying around
		chats.removeIf(o -> o != current && !o.hasMessages() && !o.running() && closeQuietly(o));
		onCurrent.accept(c.view);
		unloadOld();
		changed();
	}

	private boolean closeQuietly(Chat c)
	{
		if (c.view != null)
		{
			onUnloaded.accept(c.view);
			c.view.close();
		}
		return true;
	}

	/** Keep memory bounded: idle chats beyond the most recent few go back to their saved record. */
	private void unloadOld()
	{
		List<Chat> idle = new ArrayList<>();
		for (Chat c : chats)
		{
			if (c.view != null && c != current && !c.running() && c.hasMessages())
			{
				idle.add(c);
			}
		}
		idle.sort(Comparator.comparingLong((Chat c) -> c.shownAt).reversed());
		for (Chat c : idle.subList(Math.min(KEEP_LOADED, idle.size()), idle.size()))
		{
			c.saved = c.view.toRecord();
			onUnloaded.accept(c.view);
			c.view.close();
			c.view = null;
		}
	}

	private void wire(Chat c)
	{
		c.view.setOnChanged(() ->
		{
			c.title = c.view.title();
			c.updatedAt = c.view.updatedAt();
			JsonObject record = c.view.toRecord();
			c.preview = previewOf(record.getAsJsonArray("turns"));
			if (!c.view.isBusy() && c != current && c.view.hasConversation())
			{
				c.unread = true;
			}
			if (store != null && c.view.hasConversation())
			{
				store.save(record);
			}
			changed();
		});
	}

	private Chat find(String id)
	{
		for (Chat c : chats)
		{
			if (c.id.equals(id))
			{
				return c;
			}
		}
		return null;
	}

	private void changed()
	{
		listeners.forEach(Runnable::run);
	}

	private static String previewOf(JsonArray turns)
	{
		for (int i = turns.size() - 1; i >= 0; i--)
		{
			JsonElement t = turns.get(i);
			if (t.isJsonObject() && t.getAsJsonObject().has("text"))
			{
				String text = MarkdownLite.normalize(t.getAsJsonObject().get("text").getAsString())
					.replaceAll("\\[\\[([^\\]|]*\\|)?([^\\]]*)\\]\\]", "$2")
					.replaceAll("[*_`#>]", "")
					.replaceAll("\\s+", " ")
					.trim();
				if (!text.isEmpty())
				{
					return text.length() > 90 ? text.substring(0, 89).trim() + "..." : text;
				}
			}
		}
		return "";
	}
}

package com.squire;

import com.google.gson.Gson;
import com.google.gson.JsonObject;
import java.io.IOException;
import java.io.InputStream;
import java.nio.charset.StandardCharsets;
import java.nio.file.StandardCopyOption;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.function.Consumer;
import java.util.stream.Collectors;
import java.util.stream.Stream;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.util.Filepath;

/**
 * The chat history on disk: one JSON file per conversation in Squire's plugin data folder, under chats. Reads and
 * writes run on their own thread so the panel never waits on the disk; writes replace the file atomically. With no
 * folder (RuneLite couldn't make one), history lasts only as long as the session.
 */
@Slf4j
class ChatStore
{
	private final Filepath dir;
	private final Gson gson;
	private final ExecutorService io = Executors.newSingleThreadExecutor(r ->
	{
		Thread t = new Thread(r, "squire-chat-history");
		t.setDaemon(true);
		return t;
	});

	ChatStore(Filepath dir, Gson gson)
	{
		this.dir = dir;
		this.gson = gson;
	}

	/** Every saved conversation (called back on the history thread). */
	void loadAll(Consumer<List<JsonObject>> onLoaded)
	{
		io.execute(() ->
		{
			List<JsonObject> out = new ArrayList<>();
			for (Filepath f : files())
			{
				try (InputStream in = f.openInputStream())
				{
					JsonObject o = gson.fromJson(new String(in.readAllBytes(), StandardCharsets.UTF_8), JsonObject.class);
					if (o != null && o.has("id"))
					{
						out.add(o);
					}
				}
				catch (Exception e)
				{
					log.debug("Skipping unreadable chat {}", f, e);
				}
			}
			onLoaded.accept(out);
		});
	}

	private List<Filepath> files()
	{
		if (dir == null || !dir.isDirectory())
		{
			return List.of();
		}
		try (Stream<Filepath> walk = dir.walk(1))
		{
			return walk.filter(f -> f.getFileName().endsWith(".json") && f.isFile()).collect(Collectors.toList());
		}
		catch (IOException e)
		{
			log.warn("Couldn't list saved chats", e);
			return List.of();
		}
	}

	void save(JsonObject record)
	{
		String id = record.get("id").getAsString();
		String json = gson.toJson(record);
		if (dir == null)
		{
			return;
		}
		io.execute(() ->
		{
			try
			{
				dir.createDirectories();
				Filepath tmp = dir.joinSegment(fileName(id) + ".tmp");
				tmp.write(json.getBytes(StandardCharsets.UTF_8));
				tmp.moveTo(dir.joinSegment(fileName(id)), StandardCopyOption.REPLACE_EXISTING, StandardCopyOption.ATOMIC_MOVE);
			}
			catch (IOException | RuntimeException e)
			{
				log.warn("Couldn't save chat {}", id, e);
			}
		});
	}

	/** Remove a conversation the player deleted from the list. */
	void delete(String id)
	{
		if (dir == null)
		{
			return;
		}
		io.execute(() ->
		{
			try
			{
				dir.joinSegment(fileName(id)).deleteIfExists();
			}
			catch (IOException | RuntimeException e)
			{
				log.warn("Couldn't delete chat {}", id, e);
			}
		});
	}

	void shutdown()
	{
		io.shutdown();
	}

	private static String fileName(String id)
	{
		return id.replaceAll("[^A-Za-z0-9-]", "_") + ".json";
	}
}

package com.squire;

import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import java.net.URLDecoder;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;

/**
 * What the agent did for one reply: its thinking, the tools it called (in plain words), and the sources
 * those tools drew on. Sources get stable numbers so links in the reply can cite them as [1], [2], ...
 */
class ChatTrace
{
	/** A thought or a tool call, in the order they happened. */
	static final class Entry
	{
		final boolean thought;
		final StringBuilder text = new StringBuilder();
		String label;
		String detail;
		String url;
		boolean done;
		boolean failed;

		private Entry(boolean thought)
		{
			this.thought = thought;
		}
	}

	static final class Source
	{
		final String title;
		final String url;
		/** Who it's from: "OSRS Wiki", "Wiki prices", "Squire" (the player's synced data), ... */
		final String origin;

		Source(String title, String url, String origin)
		{
			this.title = title;
			this.url = url;
			this.origin = origin;
		}
	}


	final List<Entry> entries = new ArrayList<>();
	final List<Source> sources = new ArrayList<>();
	private final Map<String, Entry> byCall = new LinkedHashMap<>();
	private final Map<String, String> toolByCall = new LinkedHashMap<>();
	private Entry thinking;
	long startedAt = System.currentTimeMillis();
	long finishedAt;

	// ---- Saving with the chat history

	JsonObject toJson()
	{
		JsonObject o = new JsonObject();
		o.addProperty("startedAt", startedAt);
		o.addProperty("finishedAt", finishedAt);
		JsonArray es = new JsonArray();
		for (Entry e : entries)
		{
			JsonObject j = new JsonObject();
			j.addProperty("thought", e.thought);
			if (e.text.length() > 0)
			{
				j.addProperty("text", e.text.toString());
			}
			j.addProperty("label", e.label);
			j.addProperty("detail", e.detail);
			j.addProperty("url", e.url);
			j.addProperty("done", e.done);
			j.addProperty("failed", e.failed);
			es.add(j);
		}
		o.add("entries", es);
		JsonArray ss = new JsonArray();
		for (Source src : sources)
		{
			JsonObject j = new JsonObject();
			j.addProperty("title", src.title);
			j.addProperty("url", src.url);
			j.addProperty("origin", src.origin);
			ss.add(j);
		}
		o.add("sources", ss);
		JsonArray xs = new JsonArray();
		exports.forEach(x -> xs.add(x.toJson()));
		o.add("exports", xs);
		JsonArray gs = new JsonArray();
		gears.forEach(gs::add);
		o.add("gears", gs);
		o.addProperty("savedPlan", savedPlan);
		if (plan != null)
		{
			o.add("plan", plan);
		}
		return o;
	}

	static ChatTrace fromJson(JsonObject o)
	{
		ChatTrace t = new ChatTrace();
		t.startedAt = o.has("startedAt") ? o.get("startedAt").getAsLong() : 0;
		t.finishedAt = o.has("finishedAt") ? o.get("finishedAt").getAsLong() : t.startedAt;
		if (o.has("entries"))
		{
			for (JsonElement el : o.getAsJsonArray("entries"))
			{
				JsonObject j = el.getAsJsonObject();
				Entry e = new Entry(j.has("thought") && j.get("thought").getAsBoolean());
				e.text.append(str(j, "text"));
				e.label = j.has("label") && !j.get("label").isJsonNull() ? j.get("label").getAsString() : null;
				e.detail = j.has("detail") && !j.get("detail").isJsonNull() ? j.get("detail").getAsString() : null;
				e.url = j.has("url") && !j.get("url").isJsonNull() ? j.get("url").getAsString() : null;
				e.done = !j.has("done") || j.get("done").getAsBoolean();
				e.failed = j.has("failed") && j.get("failed").getAsBoolean();
				t.entries.add(e);
			}
		}
		if (o.has("sources"))
		{
			for (JsonElement el : o.getAsJsonArray("sources"))
			{
				JsonObject j = el.getAsJsonObject();
				t.sources.add(new Source(str(j, "title"), str(j, "url"), str(j, "origin")));
			}
		}
		t.savedPlan = o.has("savedPlan") && o.get("savedPlan").getAsBoolean();
		if (o.has("plan") && o.get("plan").isJsonObject())
		{
			t.plan = o.getAsJsonObject("plan");
		}
		if (o.has("gears"))
		{
			for (JsonElement el : o.getAsJsonArray("gears"))
			{
				t.gears.add(el.getAsJsonObject());
			}
		}
		if (o.has("exports"))
		{
			for (JsonElement el : o.getAsJsonArray("exports"))
			{
				ExportCards.Export x = ExportCards.Export.from(el.getAsJsonObject());
				if (x != null)
				{
					t.exports.add(x);
				}
			}
		}
		return t;
	}

	// ---- Events

	void reasoning(String delta)
	{
		if (delta == null || delta.isEmpty())
		{
			return;
		}
		if (thinking == null)
		{
			thinking = new Entry(true);
			entries.add(thinking);
		}
		thinking.text.append(delta);
	}

	void reasoningDone()
	{
		thinking = null;
	}

	void actions(JsonArray actions)
	{
		thinking = null;
		for (JsonElement e : actions)
		{
			if (!e.isJsonObject())
			{
				continue;
			}
			JsonObject a = e.getAsJsonObject();
			String callId = str(a, "callId");
			String kind = str(a, "kind");
			String tool = str(a, "toolName").replaceFirst("^osrs__", "");
			JsonObject input = a.has("input") && a.get("input").isJsonObject() ? a.getAsJsonObject("input") : new JsonObject();
			toolByCall.put(callId, "load-skill".equals(kind) ? "load-skill" : tool);
			if ("connection_search".equals(tool))
			{
				continue; // the agent finding its own tools; not interesting to players
			}
			Entry entry = new Entry(false);
			if ("load-skill".equals(kind))
			{
				entry.label = "Followed the " + str(input, "skill").replace('-', ' ') + " playbook";
			}
			else
			{
				entry.label = label(tool);
				entry.detail = detail(tool, input);
			}
			entries.add(entry);
			byCall.put(callId, entry);
		}
	}

	/** Data the agent made for other plugins this turn (setups, tags, markers), shown as cards to copy. */
	final List<ExportCards.Export> exports = new ArrayList<>();
	private static String gearKey(JsonObject card)
	{
		JsonObject gear = card.getAsJsonObject("gear");
		return str(gear, "target") + "|" + str(gear, "style");
	}

	/** Gear views this turn ({gear, export}): the game's equipment screen, editable, with a copy button. */
	final List<JsonObject> gears = new ArrayList<>();
	/** Squire saved the player's plan this turn: the reply links to it, and Home and the Plan page reload it. */
	boolean savedPlan;
	/** The plan as saved (checked against the account), shown as a card under the reply. */
	JsonObject plan;
	/** Set by the plugin: reload the plan, and open the Plan page. */
	static Runnable planSaved = () -> {};
	static Runnable openPlan = () -> {};
	/** Set by the plugin: Squire's start_session_review tool starts observing with this label. */
	static java.util.function.Consumer<String> sessionStart = label -> {};

	void result(String callId, JsonElement output, boolean ok)
	{
		Entry entry = byCall.get(callId);
		String tool = toolByCall.getOrDefault(callId, "");
		if (entry != null)
		{
			entry.done = true;
			entry.failed = !ok || isError(output);
		}
		if (!ok || isError(output))
		{
			return;
		}
		JsonElement data = unwrap(output);
		if ((tool.equals("show_gear") || tool.equals("create_inventory_setup") || tool.equals("best_gear")) && data != null && data.isJsonObject()
			&& data.getAsJsonObject().has("gear") && data.getAsJsonObject().get("gear").isJsonObject())
		{
			JsonObject g = new JsonObject();
			g.add("gear", data.getAsJsonObject().get("gear"));
			g.add("export", data.getAsJsonObject().get("export"));
			// One card per target and style: a setup built after the calculator's pick replaces it
			String key = gearKey(g);
			gears.removeIf(prev -> gearKey(prev).equals(key));
			gears.add(g);
			return;
		}
		if (tool.equals("start_session_review") && data != null && data.isJsonObject())
		{
			String label = str(data.getAsJsonObject(), "label");
			javax.swing.SwingUtilities.invokeLater(() -> sessionStart.accept(label.isEmpty() ? "Session" : label));
			return;
		}
		if (tool.equals("save_plan"))
		{
			savedPlan = true;
			if (data != null && data.isJsonObject() && data.getAsJsonObject().get("plan") instanceof JsonObject)
			{
				plan = data.getAsJsonObject().getAsJsonObject("plan");
			}
			javax.swing.SwingUtilities.invokeLater(planSaved);
			return;
		}
		if (tool.startsWith("create_") && data != null && data.isJsonObject() && data.getAsJsonObject().has("export"))
		{
			ExportCards.Export export = ExportCards.Export.from(data.getAsJsonObject());
			if (export != null)
			{
				exports.add(export);
			}
			return;
		}
		// Squire's own tools (the player's synced data, the calculators) aren't listed as sources:
		// the Steps line already shows they were used. Sources are what came from outside.
		if (tool.equals("wiki_read") && data != null && data.isJsonObject())
		{
			JsonObject o = data.getAsJsonObject();
			String url = str(o, "url");
			String title = str(o, "title") + (str(o, "section").isEmpty() ? "" : ": " + str(o, "section"));
			if (!url.isEmpty())
			{
				addSource(new Source(title.isEmpty() ? titleFromUrl(url) : title, url, "OSRS Wiki"));
				if (entry != null)
				{
					entry.url = url;
				}
			}
		}
		else if (Set.of("drop_table", "drop_luck", "ge_price", "ge_history").contains(tool) && data != null && data.isJsonObject())
		{
			String url = str(data.getAsJsonObject(), "source");
			if (url.startsWith("http"))
			{
				boolean prices = url.contains("prices.runescape.wiki");
				String title = prices ? "GE prices" + (entry != null && entry.detail != null ? ": " + entry.detail : "") : titleFromUrl(url);
				addSource(new Source(title, url, prices ? "Wiki prices" : "OSRS Wiki"));
				if (entry != null)
				{
					entry.url = url;
				}
			}
		}
		else if ((tool.equals("read_webpage") || tool.equals("web_fetch")) && data != null && data.isJsonObject())
		{
			JsonObject o = data.getAsJsonObject();
			String url = str(o, "url");
			if (url.startsWith("http"))
			{
				String title = str(o, "title");
				addSource(new Source(title.isEmpty() ? hostOf(url) : title, url, originOf(url)));
				if (entry != null)
				{
					entry.url = url;
				}
			}
		}
		else if (tool.equals("hiscores_lookup") && entry != null && entry.detail != null)
		{
			addSource(new Source("Hiscores: " + entry.detail, null, "Jagex"));
		}
	}

	void finish()
	{
		finishedAt = System.currentTimeMillis();
		thinking = null;
	}

	// ---- Citations

	/** The 1-based number of this URL among the sources, adding it if a reply links somewhere new. */
	int cite(String url, String linkText)
	{
		String key = pageKey(url);
		for (int i = 0; i < sources.size(); i++)
		{
			Source s = sources.get(i);
			if (s.url != null && pageKey(s.url).equals(key))
			{
				return i + 1;
			}
		}
		addSource(new Source(linkText == null || linkText.isBlank() ? titleFromUrl(url) : linkText, url, originOf(url)));
		for (int i = 0; i < sources.size(); i++)
		{
			if (url.equals(sources.get(i).url))
			{
				return i + 1;
			}
		}
		return sources.size();
	}

	int toolCount()
	{
		return (int) entries.stream().filter(e -> !e.thought).count();
	}

	boolean hasThoughts()
	{
		return entries.stream().anyMatch(e -> e.thought);
	}

	private static final Map<String, String> PRESENT = Map.ofEntries(
		Map.entry("Read", "Reading"), Map.entry("Checked", "Checking"), Map.entry("Searched", "Searching"),
		Map.entry("Listed", "Listing"), Map.entry("Looked", "Looking"), Map.entry("Queried", "Querying"),
		Map.entry("Worked", "Working"), Map.entry("Ran", "Running"), Map.entry("Found", "Finding"),
		Map.entry("Ranked", "Ranking"), Map.entry("Followed", "Following"));

	/** The step in progress, in the present tense ("Reading the wiki"), for the live status line. */
	String liveStatus()
	{
		for (int i = entries.size() - 1; i >= 0; i--)
		{
			Entry e = entries.get(i);
			if (!e.thought)
			{
				String label = e.label;
				int space = label.indexOf(' ');
				if (space > 0 && PRESENT.containsKey(label.substring(0, space)))
				{
					label = PRESENT.get(label.substring(0, space)) + label.substring(space);
				}
				return e.done ? "Thinking" : label;
			}
		}
		return "Thinking";
	}

	private void addSource(Source source)
	{
		for (Source s : sources)
		{
			boolean sameUrl = s.url != null && source.url != null && pageKey(s.url).equals(pageKey(source.url)) && s.title.equals(source.title);
			boolean sameTitle = s.url == null && source.url == null && s.title.equals(source.title);
			if (sameUrl || sameTitle)
			{
				return;
			}
		}
		// Linked sources (the wiki) come first, then the player's own data
		int at = sources.size();
		if (source.url != null)
		{
			for (int i = 0; i < sources.size(); i++)
			{
				if (sources.get(i).url == null)
				{
					at = i;
					break;
				}
			}
		}
		sources.add(at, source);
	}

