package com.squire;

import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import net.runelite.api.Client;
import net.runelite.api.EnumComposition;
import net.runelite.api.StructComposition;
import net.runelite.api.gameval.VarPlayerID;

/**
 * Reads every combat achievement task and its completion state straight from the game cache and varps,
 * so no interface needs to be open.
 */
final class CombatAchievements
{
	// One enum of task structs per tier, easy through grandmaster
	private static final int[] TIER_ENUMS = {3981, 3982, 3983, 3984, 3985, 3986};
	private static final String[] TIER_NAMES = {"easy", "medium", "hard", "elite", "master", "grandmaster"};
	private static final int TYPE_NAME_ENUM = 3969;
	private static final int MONSTER_NAME_ENUM = 3971;

	private static final int PARAM_TASK_ID = 1306;
	private static final int PARAM_NAME = 1308;
	private static final int PARAM_DESCRIPTION = 1309;
	private static final int PARAM_TYPE = 1311;
	private static final int PARAM_MONSTER = 1312;

	// Task N is bit N%32 of COMPLETED_VARPS[N/32]
	private static final int[] COMPLETED_VARPS = {
		VarPlayerID.CA_TASK_COMPLETED_0, VarPlayerID.CA_TASK_COMPLETED_1, VarPlayerID.CA_TASK_COMPLETED_2,
		VarPlayerID.CA_TASK_COMPLETED_3, VarPlayerID.CA_TASK_COMPLETED_4, VarPlayerID.CA_TASK_COMPLETED_5,
		VarPlayerID.CA_TASK_COMPLETED_6, VarPlayerID.CA_TASK_COMPLETED_7, VarPlayerID.CA_TASK_COMPLETED_8,
		VarPlayerID.CA_TASK_COMPLETED_9, VarPlayerID.CA_TASK_COMPLETED_10, VarPlayerID.CA_TASK_COMPLETED_11,
		VarPlayerID.CA_TASK_COMPLETED_12, VarPlayerID.CA_TASK_COMPLETED_13, VarPlayerID.CA_TASK_COMPLETED_14,
		VarPlayerID.CA_TASK_COMPLETED_15, VarPlayerID.CA_TASK_COMPLETED_16, VarPlayerID.CA_TASK_COMPLETED_17,
		VarPlayerID.CA_TASK_COMPLETED_18, VarPlayerID.CA_TASK_COMPLETED_19, VarPlayerID.CA_TASK_COMPLETED_20,
	};

	static boolean isCompletionVarp(int varpId)
	{
		for (int varp : COMPLETED_VARPS)
		{
			if (varp == varpId)
			{
				return true;
			}
		}
		return false;
	}

	/**
	 * Must run on the client thread.
	 */
	static List<Map<String, Object>> read(Client client)
	{
		List<Map<String, Object>> tasks = new ArrayList<>();
		EnumComposition typeNames = client.getEnum(TYPE_NAME_ENUM);
		EnumComposition monsterNames = client.getEnum(MONSTER_NAME_ENUM);

		for (int tier = 0; tier < TIER_ENUMS.length; tier++)
		{
			for (int structId : client.getEnum(TIER_ENUMS[tier]).getIntVals())
			{
				StructComposition struct = client.getStructComposition(structId);
				int id = struct.getIntValue(PARAM_TASK_ID);
				int varpIndex = id / 32;
				boolean complete = varpIndex < COMPLETED_VARPS.length
					&& (client.getVarpValue(COMPLETED_VARPS[varpIndex]) & (1 << (id % 32))) != 0;

				Map<String, Object> task = new LinkedHashMap<>();
				task.put("id", id);
				task.put("name", struct.getStringValue(PARAM_NAME));
				task.put("description", struct.getStringValue(PARAM_DESCRIPTION));
				task.put("tier", TIER_NAMES[tier]);
				task.put("type", typeNames.getStringValue(struct.getIntValue(PARAM_TYPE)));
				task.put("monster", monsterNames.getStringValue(struct.getIntValue(PARAM_MONSTER)));
				task.put("complete", complete);
				tasks.add(task);
			}
		}
		return tasks;
	}

	private CombatAchievements()
	{
	}
}

package com.squire;

import java.awt.AlphaComposite;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.FontMetrics;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.RenderingHints;
import javax.swing.JComponent;
import javax.swing.JLayeredPane;
import javax.swing.JRootPane;
import javax.swing.SwingUtilities;
import javax.swing.Timer;
import net.runelite.client.ui.FontManager;

/**
 * The floating composer settling into the chat's composer after sending: a stand-in box glides and stretches from
 * where the floating one was to where the chat's sits, its colour and shadow easing to match while the sent text
 * fades out. Drawn above everything in the window's layered pane, then removed to reveal the real composer.
 */
final class ComposerTransition extends JComponent
{
	static final int DURATION_MS = 280;

	private final Rectangle from;
	private final Rectangle to;
	private final String text;
	private final long start = System.currentTimeMillis();
	private double t;

	private ComposerTransition(Rectangle from, Rectangle to, String text)
	{
		this.from = from;
		this.to = to;
		this.text = text;
		setOpaque(false);
	}

	/**
	 * Animate from {@code from} to {@code to} (both in {@code within}'s coordinates), then run {@code done}.
	 * Without a window to draw in (previews) it just runs {@code done}.
	 */
	static void play(JComponent within, Rectangle from, Rectangle to, String text, Runnable done)
	{
		JRootPane root = SwingUtilities.getRootPane(within);
		if (root == null || from == null || to == null || to.width <= 0)
		{
			done.run();
			return;
		}
		JLayeredPane layer = root.getLayeredPane();
		Rectangle a = SwingUtilities.convertRectangle(within, from, layer);
		Rectangle b = SwingUtilities.convertRectangle(within, to, layer);
		Rectangle area = a.union(b);
		area.grow(12, 12);
		ComposerTransition ghost = new ComposerTransition(
			new Rectangle(a.x - area.x, a.y - area.y, a.width, a.height),
			new Rectangle(b.x - area.x, b.y - area.y, b.width, b.height), text);
		ghost.setBounds(area);
		layer.add(ghost, JLayeredPane.DRAG_LAYER);
		Timer timer = new Timer(15, null);
		timer.addActionListener(e ->
		{
			double raw = Math.min(1, (System.currentTimeMillis() - ghost.start) / (double) DURATION_MS);
			ghost.t = 1 - Math.pow(1 - raw, 3); // ease out
			ghost.repaint();
			if (raw >= 1)
			{
				timer.stop();
				layer.remove(ghost);
				layer.repaint(area);
				done.run();
			}
		});
		timer.start();
	}

	/** One frame of the animation as a component (previews). */
	static JComponent frame(Rectangle from, Rectangle to, String text, double t)
	{
		ComposerTransition c = new ComposerTransition(from, to, text);
		c.t = t;
		return c;
	}

	private static int lerp(int a, int b, double t)
	{
		return (int) Math.round(a + (b - a) * t);
	}

	private static Color lerp(Color a, Color b, double t)
	{
		return new Color(lerp(a.getRed(), b.getRed(), t), lerp(a.getGreen(), b.getGreen(), t), lerp(a.getBlue(), b.getBlue(), t));
	}

	@Override
	protected void paintComponent(Graphics g)
	{
		Graphics2D g2 = (Graphics2D) g.create();
		g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		int x = lerp(from.x, to.x, t), y = lerp(from.y, to.y, t);
		int w = lerp(from.width, to.width, t), h = lerp(from.height, to.height, t);

		// The floating shadow lifts away as it lands
		for (int i = 1; i <= 6; i++)
		{
			g2.setColor(new Color(0, 0, 0, (int) (22 * (1 - t))));
			int grow = i - 2;
			Pixel.fill(g2, x - grow, y + i * 2 - grow, w + grow * 2, h + grow * 2, (16 + grow * 2) / 2.0);
		}
		g2.setColor(lerp(ChatComponents.CARD_BG, ChatComponents.PANEL_BG, t));
		Pixel.fill(g2, x, y, w, h, 8);
		g2.setColor(ChatComponents.BORDER);
		g2.setStroke(new BasicStroke(1f));
		Pixel.draw(g2, x, y, w, h, 8);

		// The sent text fades out over the first half
		float alpha = (float) Math.max(0, 1 - t * 2);
		if (alpha > 0 && text != null)
		{
			g2.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, alpha));
			g2.setFont(FontManager.getRunescapeFont());
			g2.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_OFF);
			FontMetrics fm = g2.getFontMetrics();
			g2.setColor(Color.WHITE);
			g2.clipRect(x + 12, y, Math.max(0, w - 56), h);
			g2.drawString(text.replace('\n', ' '), x + 12, y + (Math.min(h, 40) + fm.getAscent() - fm.getDescent()) / 2);
		}
		g2.dispose();
	}
}

package com.squire;

import com.squire.ChatComponents.Align;
import com.squire.ChatComponents.MessageList;
import com.squire.ChatComponents.Surface;
import com.squire.WelcomeView.Wrapped;
import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Cursor;
import java.awt.Font;
import java.awt.Toolkit;
import java.awt.datatransfer.StringSelection;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.time.Duration;
import java.time.Instant;
import javax.swing.BorderFactory;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JScrollPane;
import javax.swing.ScrollPaneConstants;
import javax.swing.SwingConstants;
import javax.swing.SwingUtilities;
import javax.swing.Timer;
import net.runelite.client.ui.FontManager;

/**
 * Connect another AI app (Claude, ChatGPT, Cursor, ...) to Squire's MCP server: the connector URL to add, and a
 * one-time pairing code to type when the app asks you to sign in. Watches for the new connection while it's open.
 */
class ConnectView extends JPanel
{
	/** Fetches a fresh code and polls for connected apps; the plugin talks to the server. */
	interface Source
	{
		/** Calls back (any thread) with a code, or an error. */
		void newCode(PairingCallback callback);

		/** Calls back (any thread) with the connected apps' names, or null if unknown. */
		void connectedApps(java.util.function.Consumer<java.util.List<String>> callback);
	}

	interface PairingCallback
	{
		void done(String code, Instant expiresAt, String mcpUrl, String error);
	}

	private static final Color SUCCESS = Tokens.COLOR_STATUS_DONE;

	private final Source source;
	private final JLabel url = new JLabel(" ");
	private final JLabel code = new JLabel("····-····", SwingConstants.CENTER);
	private final JLabel expiry = new JLabel(" ", SwingConstants.CENTER);
	private final JLabel status = new JLabel(" ", SwingConstants.CENTER);
	private final ExportCards.PillButton copyUrl = new ExportCards.PillButton("Copy");
	private final ExportCards.PillButton copyCode = new ExportCards.PillButton("Copy");
	private final JLabel newCode = link("Get a new code");
	private final Timer tick = new Timer(1000, e -> onTick());
	private Instant expiresAt;
	private java.util.List<String> appsAtStart;
	private int ticks;

	ConnectView(Source source)
	{
		super(new BorderLayout());
		this.source = source;
		setOpaque(false);
		MessageList list = new MessageList(null, 0);
		list.setBorder(BorderFactory.createEmptyBorder(8, 4, 16, 4));
		JScrollPane scroll = new JScrollPane(list);
		scroll.setOpaque(false);
		scroll.getViewport().setOpaque(false);
		scroll.setBorder(BorderFactory.createEmptyBorder());
		scroll.setHorizontalScrollBarPolicy(ScrollPaneConstants.HORIZONTAL_SCROLLBAR_NEVER);
		add(scroll);

		list.add(ChatComponents.place(new Wrapped(
			"Use your account in Claude, ChatGPT, Cursor or any AI app that supports MCP connectors.", ChatComponents.MUTED, false),
			Align.FILL, 4));

		// Step 1: the connector URL
		list.add(ChatComponents.place(step("1", "Add a connector with this URL"), Align.FILL, 16));
		Surface urlCard = HomeView.listCard();
		urlCard.setLayout(new BorderLayout(8, 0));
		urlCard.setBorder(BorderFactory.createEmptyBorder(8, 12, 8, 8));
		url.setFont(FontManager.getRunescapeSmallFont());
		url.setForeground(Color.WHITE);
		urlCard.add(url, BorderLayout.CENTER);
		urlCard.add(copyUrl, BorderLayout.EAST);
		copyUrl.addActionListener(e -> copy(url.getToolTipText(), copyUrl));
		list.add(ChatComponents.place(urlCard, Align.FILL, 6));

		// Step 2: the pairing code
		list.add(ChatComponents.place(step("2", "Sign in with this code"), Align.FILL, 16));
		Surface codeCard = HomeView.listCard();
		codeCard.setLayout(new BorderLayout(0, 2));
		codeCard.setBorder(BorderFactory.createEmptyBorder(12, 12, 10, 12));
		code.setFont(FontManager.getRunescapeBoldFont().deriveFont(Font.PLAIN, 32f));
		code.setForeground(Color.WHITE);
		codeCard.add(code, BorderLayout.CENTER);
		JPanel under = new JPanel(new BorderLayout(8, 0));
		under.setOpaque(false);
		expiry.setFont(FontManager.getRunescapeSmallFont());
		expiry.setForeground(ChatComponents.MUTED);
		expiry.setHorizontalAlignment(SwingConstants.LEFT);
		under.add(expiry, BorderLayout.CENTER);
		under.add(copyCode, BorderLayout.EAST);
		copyCode.addActionListener(e -> copy(code.getText(), copyCode));
		codeCard.add(under, BorderLayout.SOUTH);
		list.add(ChatComponents.place(codeCard, Align.FILL, 6));
		newCode.setVisible(false);
		newCode.addMouseListener(new MouseAdapter()
		{
			@Override
			public void mouseReleased(MouseEvent e)
			{
				// On release rather than click: Swing drops a click if the pointer moves a pixel while pressed
				if (!javax.swing.SwingUtilities.isLeftMouseButton(e) || !e.getComponent().contains(e.getPoint()))
				{
					return;
				}
				requestCode();
			}
		});
		list.add(ChatComponents.place(newCode, Align.FILL, 8));

		status.setFont(FontManager.getRunescapeFont());
		status.setForeground(ChatComponents.MUTED);
		list.add(ChatComponents.place(status, Align.FILL, 14));

		list.add(ChatComponents.place(new Wrapped(
			"The app can read your synced account and use Squire's OSRS tools. It can't do anything in your game. "
				+ "Disconnect it any time in Settings.", ChatComponents.MUTED, false), Align.FILL, 14));
	}

	/** Page opened: get a fresh code and start watching for the connection. */
	void onShown()
	{
		appsAtStart = null;
		source.connectedApps(apps -> onEdt(() -> appsAtStart = apps));
		requestCode();
		ticks = 0;
		tick.start();
	}

	void onHidden()
	{
		tick.stop();
	}

	private void requestCode()
	{
		newCode.setVisible(false);
		code.setText("····-····");
		code.setForeground(ChatComponents.MUTED);
		expiry.setText("Getting a code...");
		copyCode.setEnabled(false);
		status.setText(" ");
		source.newCode((c, expires, mcpUrl, error) -> onEdt(() ->
		{
			if (error != null)
			{
				expiry.setText(error);
				newCode.setVisible(true);
				return;
			}
			code.setText(c);
			code.setForeground(Color.WHITE);
			copyCode.setEnabled(true);
			expiresAt = expires;
			url.setText(mcpUrl);
			url.setToolTipText(mcpUrl);
			status.setForeground(ChatComponents.MUTED);
			status.setText("Waiting for your app...");
			onTick();
		}));
	}

	private void onTick()
	{
		if (expiresAt != null)
		{
			long left = Duration.between(Instant.now(), expiresAt).getSeconds();
			if (left <= 0)
			{
				expiry.setText("Code expired");
				code.setForeground(ChatComponents.MUTED);
				copyCode.setEnabled(false);
				newCode.setVisible(true);
				expiresAt = null;
			}
			else
			{
				expiry.setText(String.format("Expires in %d:%02d", left / 60, left % 60));
			}
		}
		// Every 3 seconds, look for a newly connected app
		if (++ticks % 3 == 0 && appsAtStart != null)
		{
			source.connectedApps(apps -> onEdt(() ->
			{
				if (apps == null || appsAtStart == null)
				{
					return;
				}
				if (apps.size() <= appsAtStart.size())
				{
					return;
				}
				String app = apps.stream().filter(a -> !appsAtStart.contains(a)).findFirst().orElse(apps.get(apps.size() - 1));
				status.setForeground(SUCCESS);
				status.setText("Connected to " + app);
				code.setForeground(ChatComponents.MUTED);
				copyCode.setEnabled(false);
				expiresAt = null;
				expiry.setText("Code used");
				appsAtStart = apps;
			}));
		}
	}

	private static void onEdt(Runnable r)
	{
		if (SwingUtilities.isEventDispatchThread())
		{
			r.run();
		}
		else
		{
			SwingUtilities.invokeLater(r);
		}
	}

	private static void copy(String text, ExportCards.PillButton button)
	{
		if (text == null || text.isBlank())
		{
			return;
		}
		Toolkit.getDefaultToolkit().getSystemClipboard().setContents(new StringSelection(text), null);
		button.setText("Copied");
		Timer back = new Timer(1500, e -> button.setText("Copy"));
		back.setRepeats(false);
		back.start();
	}

	private static JPanel step(String n, String text)
	{
		JPanel p = new JPanel(new BorderLayout(6, 0));
		p.setOpaque(false);
		JLabel num = new JLabel(n + ".");
		num.setFont(FontManager.getRunescapeBoldFont());
		num.setForeground(ChatComponents.ACCENT);
		JLabel t = new JLabel(text);
		t.setFont(FontManager.getRunescapeFont());
		t.setForeground(Color.WHITE);
		p.add(num, BorderLayout.WEST);
		p.add(t, BorderLayout.CENTER);
		return p;
	}

	private static JLabel link(String text)
	{
		JLabel l = new JLabel("<html><u>" + text + "</u></html>", SwingConstants.CENTER);
		l.setFont(FontManager.getRunescapeSmallFont());
		l.setForeground(ChatComponents.ACCENT);
		l.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		return l;
	}
}

package com.squire;

import java.awt.Color;
import java.awt.Component;
import java.awt.Graphics2D;
import java.awt.Polygon;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import java.util.HashMap;
import java.util.Map;
import java.util.function.IntFunction;

/**
 * The rank crest: the tier's kiteshield, drawn from the game's own item icon (pixel-doubled so it stays crisp).
 * Falls back to a flat shield in the tier's colour when item icons aren't available (e.g. previews).
 */
final class Crest
{
	private static IntFunction<BufferedImage> icons;
	private static final Map<Integer, BufferedImage> CACHE = new HashMap<>();

	/** Called by the plugin with ItemManager; icons may arrive asynchronously. */
	static void setIconSource(IntFunction<BufferedImage> source)
	{
		icons = source;
		CACHE.clear();
	}

	/**
	 * Paint the crest centred at (cx, cy), at most maxW x maxH. The game icon is scaled by a whole number so its
	 * pixels stay square.
	 */
	static void paint(Graphics2D g, Component owner, int itemId, Color color, int cx, int cy, int maxW, int maxH)
	{
		BufferedImage img = icon(itemId, owner);
		if (img != null && hasPixels(img))
		{
			// Item icons are 36x32 with padding; crop to the drawn pixels so the shield fills the space
			java.awt.Rectangle b = bounds(img);
			int scale = Math.max(1, Math.min(maxW / Math.max(1, b.width), maxH / Math.max(1, b.height)));
			int w = b.width * scale, h = b.height * scale;
			Graphics2D g2 = (Graphics2D) g.create();
			g2.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_NEAREST_NEIGHBOR);
			g2.drawImage(img, cx - w / 2, cy - h / 2, cx - w / 2 + w, cy - h / 2 + h, b.x, b.y, b.x + b.width, b.y + b.height, null);
			g2.dispose();
			return;
		}
		paintShield(g, color, cx, cy, Math.min(maxW, maxH * 9 / 10));
	}

	/** A simple kite shield in the tier colour, with a lighter rim and a dark outline. */
	private static void paintShield(Graphics2D g, Color color, int cx, int cy, int w)
	{
		int h = w * 11 / 9;
		int top = cy - h / 2;
		Polygon shield = new Polygon(
			new int[]{cx - w / 2, cx + w / 2, cx + w / 2, cx, cx - w / 2},
			new int[]{top, top, top + h * 5 / 11, top + h, top + h * 5 / 11}, 5);
		Graphics2D g2 = (Graphics2D) g.create();
		g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g2.setColor(color);
		g2.fill(shield);
		g2.setColor(color.brighter());
		g2.setStroke(new java.awt.BasicStroke(Math.max(2f, w / 10f)));
		g2.draw(shield);
		g2.setColor(new Color(0, 0, 0, 160));
		g2.setStroke(new java.awt.BasicStroke(1f));
		g2.draw(shield);
		g2.dispose();
	}

	/** An item's inventory icon (cached; repaints the owner when it finishes loading), or null. */
	static BufferedImage itemImage(int itemId, Component owner)
	{
		return icon(itemId, owner);
	}

	private static BufferedImage icon(int itemId, Component owner)
	{
		if (icons == null || itemId <= 0)
		{
			return null;
		}
		return CACHE.computeIfAbsent(itemId, id ->
		{
			BufferedImage img = icons.apply(id);
			if (img instanceof net.runelite.client.util.AsyncBufferedImage)
			{
				((net.runelite.client.util.AsyncBufferedImage) img).onLoaded(() -> javax.swing.SwingUtilities.invokeLater(owner::repaint));
			}
			return img;
		});
	}

	private static boolean hasPixels(BufferedImage img)
	{
		return bounds(img).width > 0;
	}

	private static java.awt.Rectangle bounds(BufferedImage img)
	{
		int minX = img.getWidth(), minY = img.getHeight(), maxX = -1, maxY = -1;
		for (int y = 0; y < img.getHeight(); y++)
		{
			for (int x = 0; x < img.getWidth(); x++)
			{
				if ((img.getRGB(x, y) >>> 24) > 0)
				{
					minX = Math.min(minX, x);
					minY = Math.min(minY, y);
					maxX = Math.max(maxX, x);
					maxY = Math.max(maxY, y);
				}
			}
		}
		return maxX < 0 ? new java.awt.Rectangle(0, 0, 0, 0) : new java.awt.Rectangle(minX, minY, maxX - minX + 1, maxY - minY + 1);
	}

	private Crest()
	{
	}
}

