package com.squire;

import java.awt.Color;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.function.Consumer;
import java.util.function.Supplier;
import javax.swing.SwingUtilities;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.gameval.VarClientID;
import net.runelite.client.chat.ChatMessageManager;
import net.runelite.client.chat.QueuedMessage;
import net.runelite.client.game.chatbox.ChatboxPanelManager;
import net.runelite.client.util.ColorUtil;
import net.runelite.client.util.Text;

/**
 * Talking to Squire from the game's chatbox: "::squire <question>" or the Ask shortcut's prompt. Nothing is sent
 * to the game: RuneLite keeps "::" commands to itself, and replies are local console lines only this player sees.
 * The questions and replies also live in an "In-game" conversation in the panel, where sources, hover cards and
 * setups to copy are shown in full.
 */
class InGameChat
{
	private static final Color NAME = new Color(0x3F52D6);
	private static final Color MUTED = Tokens.COLOR_TEXT_MUTED;
	/** A chatbox answer longer than this many lines is cut short with a pointer to the panel. */
	private static final int MAX_LINES = 5;
	/** Longer paragraphs are split between sentences into lines about this long. */
	private static final int LINE_CHARS = 180;

	private final Client client;
	private final ChatMessageManager chatMessages;
	private final ChatboxPanelManager chatbox;
	private final Supplier<ChatSessions> sessions;

	InGameChat(Client client, ChatMessageManager chatMessages, ChatboxPanelManager chatbox, Supplier<ChatSessions> sessions)
	{
		this.client = client;
		this.chatMessages = chatMessages;
		this.chatbox = chatbox;
		this.sessions = sessions;
	}

	// A question from the chatbox is being answered (the chat tab shows "Thinking")
	private volatile boolean thinking;

	boolean thinking()
	{
		return thinking;
	}

	/** The shortcut: open an "Ask Squire" prompt in the chatbox. Client thread. */
	void openPrompt()
	{
		if (client.getGameState() != GameState.LOGGED_IN || chatbox.getCurrentInput() != null)
		{
			return;
		}
		// Don't take over while the player is typing a message
		String typing = client.getVarcStrValue(VarClientID.CHATINPUT);
		if (typing != null && !typing.isEmpty())
		{
			return;
		}
		chatbox.openTextInput("Ask Squire:")
			.onDone((Consumer<String>) this::ask)
			.build();
	}

	/** Ask a question from the chatbox. Any thread. */
	void ask(String question)
	{
		String q = question == null ? "" : question.trim();
		if (q.isEmpty())
		{
			return;
		}
		print(ColorUtil.wrapWithColorTag("You asked Squire: ", MUTED) + Text.escapeJagex(q));
		SwingUtilities.invokeLater(() ->
		{
			ChatSessions s = sessions.get();
			if (s == null)
			{
				return;
			}
			ChatView view = s.inGame(v -> v.setInGame(
				Map.of("replyIn", "game chatbox",
					"replyGuide", "The player asked in the game's chatbox; the answer is shown there as plain text lines. "
						+ "Answer in 1-3 short sentences with no lists, headings or markdown. The full reply is also in their Squire panel."),
				new ChatView.ReplyListener()
				{
					@Override
					public void reply(String markdown, boolean more)
					{
						thinking = false;
						printReply(markdown, more);
					}

					@Override
					public void error(String message)
					{
						thinking = false;
						print(ColorUtil.wrapWithColorTag("Squire: ", NAME) + ColorUtil.wrapWithColorTag(Text.escapeJagex(message), MUTED));
					}
				}));
			if (view.isBusy())
			{
				print(ColorUtil.wrapWithColorTag("Squire is still answering your last question.", MUTED));
				return;
			}
			print(ColorUtil.wrapWithColorTag("Squire is thinking...", MUTED));
			thinking = true;
			view.sendMessage(q);
		});
	}

	private void printReply(String markdown, boolean more)
	{
		List<String> lines = toChatLines(markdown);
		boolean cut = lines.size() > MAX_LINES;
		List<String> shown = cut ? lines.subList(0, MAX_LINES) : lines;
		for (int i = 0; i < shown.size(); i++)
		{
			String line = Text.escapeJagex(shown.get(i));
			print(i == 0 ? ColorUtil.wrapWithColorTag("Squire: ", NAME) + line : line);
		}
		if (shown.isEmpty())
		{
			print(ColorUtil.wrapWithColorTag("Squire: ", NAME) + ColorUtil.wrapWithColorTag("(no reply)", MUTED));
		}
		if (cut || more)
		{
			print(ColorUtil.wrapWithColorTag("Full answer in the Squire panel.", MUTED));
		}
	}

	/** Markdown to plain chat lines: wiki links and links become their text, emphasis goes, one line per paragraph or bullet. */
	static List<String> toChatLines(String markdown)
	{
		String text = MarkdownLite.normalize(markdown)
			.replaceAll("\\[\\[([^\\]|]*)\\|([^\\]]*)\\]\\]", "$2")
			.replaceAll("\\[\\[([^\\]]*)\\]\\]", "$1")
			.replaceAll("\\[([^\\]]+)\\]\\((https?://[^)]+)\\)", "$1")
			.replaceAll("(\\*\\*|__|`)", "")
			.replaceAll("(?<![\\w*])\\*([^*\\n]+)\\*(?![\\w*])", "$1")
			.replaceAll("(?m)^#{1,6}\\s*", "")
			.replaceAll("(?m)^\\s*[*+]\\s+", "- ");
		List<String> out = new ArrayList<>();
		for (String line : text.split("\\n"))
		{
			String l = line.replaceAll("\\s+", " ").trim();
			if (l.isEmpty() || l.matches("^[-|: ]+$"))
			{
				continue;
			}
			// Group sentences into lines of a readable length (the chatbox wraps each one)
			StringBuilder current = new StringBuilder();
			for (String sentence : l.split("(?<=[.!?])\\s+(?=[A-Z0-9\"'(])"))
			{
				if (current.length() > 0 && current.length() + sentence.length() + 1 > LINE_CHARS)
				{
					out.add(current.toString());
					current.setLength(0);
				}
				current.append(current.length() > 0 ? " " : "").append(sentence);
			}
			if (current.length() > 0)
			{
				out.add(current.toString());
			}
		}
		return out;
	}

	/**
	 * An empty colour tag at the start of every Squire line: invisible, but lets the chatbox's Squire tab keep just
	 * Squire's lines (including a reply's continuation lines) when it's focused.
	 */
	static final String MARK = "<col=fefefe></col>";

	static boolean isSquireLine(String value)
	{
		return value != null && value.contains(MARK);
	}

	/** Called for every line Squire prints (the chat tab counts unread replies). */
	static Runnable onPrinted = () -> {};

	void print(String formatted)
	{
		// Console lines: shown only in this client, and not "game messages" that other plugins parse
		chatMessages.queue(QueuedMessage.builder()
			.type(ChatMessageType.CONSOLE)
			.runeLiteFormattedMessage(MARK + formatted)
			.build());
		onPrinted.run();
	}
}

package com.squire;

import java.util.HashMap;
import java.util.Map;
import net.runelite.client.hiscore.HiscoreSkill;
import net.runelite.client.hiscore.HiscoreSkillType;

/**
 * Chat messages, the Chat Commands plugin and the hiscores all spell activity names slightly differently
 * ("Kree'arra" vs "Kree'Arra", "Corrupted Gauntlet" vs "The Corrupted Gauntlet"). Map them all to the hiscore name
 * so the same boss lands in one row.
 */
final class KillCountNames
{
	private static final Map<String, String> CANONICAL = new HashMap<>();

	static
	{
		for (HiscoreSkill skill : HiscoreSkill.values())
		{
			if (skill.getType() != HiscoreSkillType.SKILL)
			{
				CANONICAL.put(key(skill.getName()), skill.getName());
			}
		}
	}

	// Hiscore rows that are ranks or totals rather than counts
	private static final java.util.regex.Pattern NOT_A_KILL_COUNT = java.util.regex.Pattern.compile(
		"(^overall$|rank$|^collections logged$|league points|bounty hunter|deadman)", java.util.regex.Pattern.CASE_INSENSITIVE);

	private static final Map<String, String> ALIASES = Map.of("riftsclosed", "Guardians of the Rift");

	static boolean isKillCount(String name)
	{
		return !NOT_A_KILL_COUNT.matcher(name).find();
	}

	static String canonicalize(String name)
	{
		String alias = ALIASES.get(key(name));
		if (alias != null)
		{
			return alias;
		}
		String canonical = CANONICAL.get(key(name));
		if (canonical != null)
		{
			return canonical;
		}
		// Unknown to the hiscores (e.g. Chat Commands stores lowercase keys): title-case it
		StringBuilder out = new StringBuilder(name.length());
		boolean upper = true;
		for (char c : name.toCharArray())
		{
			out.append(upper ? Character.toUpperCase(c) : c);
			upper = c == ' ' || c == '(' || c == '-';
		}
		return out.toString();
	}

	private static String key(String name)
	{
		String k = name.toLowerCase();
		if (k.startsWith("the "))
		{
			k = k.substring(4);
		}
		return k.replaceAll("[^a-z0-9]", "");
	}

	private KillCountNames()
	{
	}
}

package com.squire;

import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * Just enough Markdown for chat replies in a Swing HTML pane: paragraphs, bullets, numbered
 * lists, bold/italic, inline and fenced code. Headings render bold; tables render monospace.
 */
final class MarkdownLite
{
	private static final Pattern BOLD = Pattern.compile("\\*\\*(.+?)\\*\\*");
	private static final Pattern ITALIC = Pattern.compile("(?<![*\\w])\\*(?!\\s)(.+?)(?<!\\s)\\*(?![*\\w])");
	private static final Pattern CODE = Pattern.compile("`([^`]+)`");
	private static final Pattern LINK = Pattern.compile("\\[([^\\]]+)\\]\\((https?://(?:[^()\\s]|\\([^()\\s]*\\))+)\\)");
	private static final Pattern BULLET = Pattern.compile("^\\s*[-*•]\\s+(.*)$");
	private static final Pattern NUMBERED = Pattern.compile("^\\s*(\\d+)[.)]\\s+(.*)$");
	private static final Pattern HEADING = Pattern.compile("^#{1,6}\\s+(.*)$");

	// RuneLite's RuneScape font lacks many symbols; swap common ones for ASCII look-alikes
	private static final String[][] SUBSTITUTIONS = {
		{"\u2013", "-"}, {"\u2192", "->"}, {"\u2190", "<-"}, {"\u21D2", "=>"},
		{"\u2018", "'"}, {"\u2019", "'"}, {"\u201C", "\""}, {"\u201D", "\""},
		{"\u2265", ">="}, {"\u2264", "<="}, {"\u2260", "!="}, {"\u2248", "~"},
		{"\u2713", "+"}, {"\u2714", "+"}, {"\u2705", "+"}, {"\u2611", "+"},
		{"\u2717", "x"}, {"\u2718", "x"}, {"\u274C", "x"}, {"\u2716", "x"},
		{"\u2605", "*"}, {"\u2606", "*"}, {"\u2022", "-"}, {"\u00A0", " "},
	};

	private static final java.awt.Font FONT = net.runelite.client.ui.FontManager.getRunescapeFont();

	/** Replace or drop characters the RuneScape font can't draw, so they don't show as boxes. */
	static String normalize(String s)
	{
		for (String[] sub : SUBSTITUTIONS)
		{
			s = s.replace(sub[0], sub[1]);
		}
		StringBuilder out = new StringBuilder(s.length());
		s.codePoints().forEach(cp ->
		{
			if (cp == '\n' || cp == '\t' || FONT == null || FONT.canDisplay(cp))
			{
				out.appendCodePoint(cp);
			}
		});
		return out.toString();
	}

	static String escape(String s)
	{
		return normalize(s).replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;");
	}

	/** Numbers a cited link: (url, link text) -> source number, or 0 for none. */
	interface Citer
	{
		int cite(String url, String text);
	}

	static String toHtml(String markdown)
	{
		return toHtml(markdown, null);
	}

	/** Links become clickable; with a citer, each is followed by its source number, e.g. "Vorkath [2]". */
	static String toHtml(String markdown, Citer citer)
	{
		markdown = normalize(markdown);
		StringBuilder out = new StringBuilder();
		boolean inList = false;
		boolean ordered = false;
		boolean inCode = false;
		int codeLines = 0;
		java.util.List<String> table = new java.util.ArrayList<>();
		boolean paragraphOpen = false;

		for (String raw : markdown.split("\n", -1))
		{
			if (raw.trim().startsWith("```"))
			{
				if (paragraphOpen)
				{
					out.append("</div>");
					paragraphOpen = false;
				}
				if (inList)
				{
					out.append(ordered ? "</ol>" : "</ul>");
					inList = false;
				}
				flushTable(out, table);
				if (!inCode)
				{
					// A dark inset box in the code colour; the RuneScape font has no monospace, so keep it
					out.append("<div style='background-color:#1a1a1a; margin-top:4px; padding:4px 6px'><font color='#f0c987'>");
					codeLines = 0;
				}
				else
				{
					out.append("</font></div>");
				}
				inCode = !inCode;
				continue;
			}
			if (inCode)
			{
				String line = escape(raw);
				int lead = line.length() - line.stripLeading().length();
				out.append(codeLines++ > 0 ? "<br>" : "").append("&nbsp;".repeat(lead)).append(line.stripLeading().replace("  ", " &nbsp;"));
				continue;
			}
			if (raw.trim().startsWith("|"))
			{
				if (paragraphOpen)
				{
					out.append("</div>");
					paragraphOpen = false;
				}
				if (!raw.matches("^\\s*\\|[\\s:|-]+\\|\\s*$"))
				{
					table.add(raw);
				}
				continue;
			}
			flushTable(out, table);

			Matcher bullet = BULLET.matcher(raw);
			Matcher numbered = NUMBERED.matcher(raw);
			if (bullet.matches() || numbered.matches())
			{
				if (paragraphOpen)
				{
					out.append("</div>");
					paragraphOpen = false;
				}
				boolean wantOrdered = !bullet.matches();
				if (inList && ordered != wantOrdered)
				{
					out.append(ordered ? "</ol>" : "</ul>");
					inList = false;
				}
				if (!inList)
				{
					out.append(wantOrdered ? "<ol>" : "<ul>");
					inList = true;
					ordered = wantOrdered;
				}
				String item = bullet.matches() ? bullet.group(1) : numbered.group(2);
				out.append("<li>").append(inline(item, citer)).append("</li>");
				continue;
			}
			if (inList)
			{
				out.append(ordered ? "</ol>" : "</ul>");
				inList = false;
			}

			if (raw.isBlank())
			{
				if (paragraphOpen)
				{
					out.append("</div>");
					paragraphOpen = false;
				}
				continue;
			}

			Matcher heading = HEADING.matcher(raw);
			String line = heading.matches() ? "<b>" + inline(heading.group(1), citer) + "</b>" : inline(raw, citer);
			if (!paragraphOpen)
			{
				out.append("<div style='margin-top:4px'>");
				paragraphOpen = true;
			}
			else
			{
				out.append("<br>");
			}
			out.append(line);
		}
		if (inCode)
		{
			out.append("</font></div>");
		}
		flushTable(out, table);
		if (inList)
		{
			out.append(ordered ? "</ol>" : "</ul>");
		}
		if (paragraphOpen)
		{
			out.append("</div>");
		}
		return out.toString();
	}

	/** Markdown table rows ("| a | b |") as an HTML table: the first row bold, the rest in the body colour. */
	private static void flushTable(StringBuilder out, java.util.List<String> rows)
	{
		if (rows.isEmpty())
		{
			return;
		}
		out.append("<table cellspacing='0' cellpadding='2' style='margin-top:4px'>");
		for (int r = 0; r < rows.size(); r++)
		{
			String row = rows.get(r).trim();
			row = row.replaceAll("^\\|", "").replaceAll("\\|$", "");
			out.append("<tr>");
			for (String cell : row.split("\\|"))
			{
				String html = inline(cell.trim(), null);
				out.append("<td style='padding-right:12px'>").append(r == 0 ? "<b>" + html + "</b>" : html).append("</td>");
			}
			out.append("</tr>");
		}
		out.append("</table>");
		rows.clear();
	}

	/** [[Page]] or [[Page|shown text]]: a link to that OSRS Wiki page (shown with a hover card in chat). */
	private static final Pattern WIKILINK = Pattern.compile("\\[\\[([^\\]|]+)(?:\\|([^\\]]+))?\\]\\]");

	/** Turn [[Page]] wiki links into ordinary markdown links to the page. */
	private static String wikiLinks(String text)
	{
		Matcher m = WIKILINK.matcher(text);
		StringBuffer out = new StringBuffer();
		while (m.find())
		{
			String page = m.group(1).trim();
			String shown = m.group(2) == null ? page : m.group(2).trim();
			String url = WikiCards.WIKI + page.replace(' ', '_').replace("(", "%28").replace(")", "%29").replace("'", "%27").replace("?", "%3F");
			m.appendReplacement(out, Matcher.quoteReplacement("[" + shown + "](" + url + ")"));
		}
		m.appendTail(out);
		return out.toString();
	}

	private static String inline(String text, Citer citer)
	{
		String s = escape(wikiLinks(text));
		Matcher link = LINK.matcher(s);
		StringBuffer linked = new StringBuffer();
		while (link.find())
		{
			String label = link.group(1);
			String url = link.group(2).replace("&amp;", "&");
			int n = citer == null ? 0 : citer.cite(url, label.replace("&amp;", "&").replace("&lt;", "<").replace("&gt;", ">"));
			String html = "<a href='" + url.replace("'", "%27").replace("&", "&amp;") + "'>" + label + "</a>"
				+ (n > 0 ? "<font color='#9a9a9a'>&nbsp;[" + n + "]</font>" : "");
			link.appendReplacement(linked, Matcher.quoteReplacement(html));
		}
		link.appendTail(linked);
		s = linked.toString();
		// Highlight rather than switch to a monospace font, which clashes with the RuneScape font
		s = CODE.matcher(s).replaceAll("<font color='#f0c987'>$1</font>");
		s = BOLD.matcher(s).replaceAll("<b>$1</b>");
		s = ITALIC.matcher(s).replaceAll("<i>$1</i>");
		return s;
	}

	private MarkdownLite()
	{
	}
}

package com.squire;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.io.IOException;
import java.util.ArrayList;
import java.util.List;
import java.util.function.Consumer;
import java.util.function.Supplier;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.HttpUrl;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;
import okhttp3.ResponseBody;

/**
 * The models players can choose, fetched from the server's /api/models (with a built-in fallback).
 */
class ModelCatalog
{
	static final class Option
	{
		final String id;
		final String label;
		final String blurb;
		/** "key": runs on the player's own API key (no daily limit); "squire": Squire's free daily messages. */
		final String source;

		Option(String id, String label, String blurb)
		{
			this(id, label, blurb, "squire");
		}

		Option(String id, String label, String blurb, String source)
		{
			this.id = id;
			this.label = label;
			this.blurb = blurb;
			this.source = source;
		}

		@Override
		public String toString()
		{
			return label;
		}
	}

	static final String DEFAULT_ID = "anthropic/claude-sonnet-5";

	// Mirrors server/agent/models.ts; used until the server answers
	private static final List<Option> FALLBACK = List.of(
		new Option("anthropic/claude-sonnet-5", "Claude Sonnet 5", "Balanced (default)"),
		new Option("anthropic/claude-opus-5.5", "Claude Opus 5.5", "Smartest, slower, pricier"),
		new Option("anthropic/claude-haiku-4.5", "Claude Haiku 4.5", "Fast and cheap"),
		new Option("openai/gpt-6-sol", "GPT-6 Sol", "Balanced"),
		new Option("openai/gpt-6-luna", "GPT-6 Luna", "Fast and cheap"),
		new Option("google/gemini-3.8-flash", "Gemini 3.8 Flash", "Fast"),
		new Option("deepseek/deepseek-v4.1-flash", "DeepSeek V4.1 Flash", "Cheapest")
	);

	private final OkHttpClient http;
	private final Gson gson;
	private final Supplier<String> endpoint;
	private final Supplier<String> token;
	private volatile List<Option> options = FALLBACK;

	ModelCatalog(OkHttpClient http, Gson gson, Supplier<String> endpoint, Supplier<String> token)
	{
		this.http = http;
		this.gson = gson;
		this.endpoint = endpoint;
		this.token = token;
	}

	List<Option> options()
	{
		return options;
	}

	Option find(String id)
	{
		for (Option o : options)
		{
			if (o.id.equals(id))
			{
				return o;
			}
		}
		return options.get(0);
	}

	/** Refresh from the server; calls back (on an OkHttp thread) only when the list arrives. */
	void refresh(Consumer<List<Option>> onLoaded)
	{
		HttpUrl base = HttpUrl.parse(endpoint.get().trim());
		if (base == null || token.get().isBlank())
		{
			return;
		}
		Request request = new Request.Builder()
			.url(base.newBuilder().addPathSegments("api/models").build())
			.header("Authorization", "Bearer " + token.get().trim())
			.build();
		http.newCall(request).enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
			}

			@Override
			public void onResponse(Call call, Response response) throws IOException
			{
				try (response)
				{
					ResponseBody body = response.body();
					if (!response.isSuccessful() || body == null)
					{
						return;
					}
					JsonArray models = gson.fromJson(body.string(), JsonObject.class).getAsJsonArray("models");
					List<Option> loaded = new ArrayList<>();
					for (JsonElement e : models)
					{
						JsonObject m = e.getAsJsonObject();
						loaded.add(new Option(m.get("id").getAsString(), m.get("label").getAsString(), m.has("blurb") ? m.get("blurb").getAsString() : "",
							m.has("source") ? m.get("source").getAsString() : "squire"));
					}
					if (!loaded.isEmpty())
					{
						options = loaded;
						onLoaded.accept(loaded);
					}
				}
			}
		});
	}
}

package com.squire;

import java.awt.Color;
import java.awt.Component;
import java.awt.Container;
import java.awt.Dimension;
import java.awt.FlowLayout;
import java.awt.LayoutManager;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.util.List;
import javax.swing.JComponent;
import javax.swing.JLabel;
import javax.swing.JMenuItem;
import javax.swing.JPanel;
import javax.swing.JPopupMenu;
import javax.swing.SwingConstants;
import javax.swing.SwingUtilities;
import javax.swing.Timer;
import net.runelite.client.ui.FontManager;

/**
 * An iOS-style navigation bar: the page's title centred, a back arrow to the page above on the left, and the page's
 * actions on the right. Right-click or long-press the back arrow to jump anywhere up the stack.
 */
class NavBar extends JPanel
{
	static final int HEIGHT = 36;
	private static final int GAP = 6;
	private static final int LONG_PRESS_MS = 450;

	/** A page up the stack: its name and how to go there. */
	static final class Crumb
	{
		final String title;
		final Runnable go;

		Crumb(String title, Runnable go)
		{
			this.title = title;
			this.go = go;
		}
	}

	private final javax.swing.JButton back = ChatComponents.iconButton("arrow-left", "Back");
	private final JLabel title = new JLabel("", SwingConstants.CENTER);
	private final JPanel actions = new JPanel(new FlowLayout(FlowLayout.RIGHT, 0, 0));
	/** Ancestors, nearest first. */
	private List<Crumb> stack = List.of();
	private String backText = "";
	private boolean longPressed;

	NavBar()
	{
		setOpaque(false);
		setLayout(new BarLayout());
		title.setFont(FontManager.getRunescapeBoldFont());
		title.setForeground(Color.WHITE);
		actions.setOpaque(false);
		add(back);
		add(title);
		add(actions);
		installBackGestures();
	}

	/** Show a page: its title, the pages above it (nearest first; empty for none) and its action buttons. */
	void set(String pageTitle, List<Crumb> ancestors, List<? extends JComponent> pageActions)
	{
		title.setText(pageTitle);
		title.setToolTipText(pageTitle);
		stack = ancestors;
		backText = ancestors.isEmpty() ? "" : ancestors.get(0).title;
		back.setToolTipText(ancestors.isEmpty() ? null : "Back to " + backText + (ancestors.size() > 1 ? " (right-click for more)" : ""));
		back.setVisible(!ancestors.isEmpty());
		actions.removeAll();
		pageActions.forEach(actions::add);
		revalidate();
		repaint();
	}

	void setTitle(String pageTitle)
	{
		title.setText(pageTitle);
		title.setToolTipText(pageTitle);
		revalidate();
	}

	private void installBackGestures()
	{
		Timer hold = new Timer(LONG_PRESS_MS, e ->
		{
			longPressed = true;
			showStack();
		});
		hold.setRepeats(false);
		back.addMouseListener(new MouseAdapter()
		{
			@Override
			public void mousePressed(MouseEvent e)
			{
				longPressed = false;
				if (SwingUtilities.isLeftMouseButton(e))
				{
					hold.restart();
				}
			}

			@Override
			public void mouseReleased(MouseEvent e)
			{
				hold.stop();
				if (e.isPopupTrigger() || SwingUtilities.isRightMouseButton(e))
				{
					showStack();
				}
				else if (!longPressed && back.contains(e.getPoint()) && !stack.isEmpty())
				{
					stack.get(0).go.run();
				}
			}

			@Override
			public void mouseExited(MouseEvent e)
			{
				hold.stop();
			}
		});
	}

	/** Every page up the stack, nearest first; pick one to jump straight there. */
	private void showStack()
	{
		if (stack.isEmpty())
		{
			return;
		}
		JPopupMenu menu = new JPopupMenu();
		for (Crumb c : stack)
		{
			JMenuItem item = new JMenuItem(c.title);
			item.setFont(FontManager.getRunescapeFont());
			item.addActionListener(e -> c.go.run());
			menu.add(item);
		}
		menu.show(back, 0, back.getHeight());
	}

	@Override
	public Dimension getPreferredSize()
	{
		return new Dimension(super.getPreferredSize().width, HEIGHT);
	}

	@Override
	public Dimension getMaximumSize()
	{
		return new Dimension(Integer.MAX_VALUE, HEIGHT);
	}

	/** Title centred on the whole bar (not between the sides), shortened if it would reach either side. */
	private final class BarLayout implements LayoutManager
	{
		@Override
		public void addLayoutComponent(String name, Component comp)
		{
		}

		@Override
		public void removeLayoutComponent(Component comp)
		{
		}

		@Override
		public Dimension preferredLayoutSize(Container parent)
		{
			return new Dimension(100, HEIGHT);
		}

		@Override
		public Dimension minimumLayoutSize(Container parent)
		{
			return new Dimension(0, HEIGHT);
		}

		@Override
		public void layoutContainer(Container parent)
		{
			int w = parent.getWidth(), h = parent.getHeight();
			int rw = actions.getPreferredSize().width;
			actions.setBounds(w - rw, (h - actions.getPreferredSize().height) / 2, rw, actions.getPreferredSize().height);

			int lw = back.isVisible() ? back.getPreferredSize().width : 0;
			int tw = title.getPreferredSize().width;
			int side = Math.max(lw, rw);
			int titleW = Math.max(0, Math.min(tw, w - 2 * side - 2 * GAP));
			title.setBounds((w - titleW) / 2, 0, titleW, h);
			back.setBounds(0, (h - back.getPreferredSize().height) / 2, lw, back.getPreferredSize().height);
		}
	}
}

package com.squire;

import java.awt.Graphics2D;
import java.awt.Polygon;
import java.awt.Shape;

/**
 * Pixel-art shapes: rectangles whose corners are cut in whole-pixel steps (like the game's own interface) instead
 * of smooth curves. Every "rounded" surface in the panel goes through here so the style stays consistent.
 */
final class Pixel
{
	private Pixel()
	{
	}

	/** How far each row is cut in from the side, from the top row down, for a corner of about this radius. */
	static int[] corner(int radius)
	{
		// Chunky 2px "art pixels", so the stair steps are visible next to the game font
		if (radius <= 0)
		{
			return new int[0];
		}
		if (radius <= 2)
		{
			return new int[]{1};
		}
		if (radius <= 5)
		{
			return new int[]{2, 2};
		}
		if (radius <= 9)
		{
			return new int[]{4, 4, 2, 2};
		}
		return new int[]{6, 6, 4, 4, 2, 2};
	}

	/** A w×h rectangle at (x, y) with stepped corners of about {@code radius}. */
	static Shape shape(double x, double y, double w, double h, double radius)
	{
		int ix = (int) Math.round(x), iy = (int) Math.round(y), iw = (int) Math.round(w), ih = (int) Math.round(h);
		int[] cut = corner((int) Math.min(Math.round(radius), Math.min(iw, ih) / 2));
		int n = Math.min(cut.length, ih / 2);
		Polygon p = new Polygon();
		// Down the right side, then back up the left: one vertical run and one horizontal step per row of the corner
		for (int i = 0; i < n; i++)
		{
			p.addPoint(ix + iw - cut[i], iy + i);
			p.addPoint(ix + iw - cut[i], iy + i + 1);
		}
		p.addPoint(ix + iw, iy + n);
		p.addPoint(ix + iw, iy + ih - n);
		for (int i = n - 1; i >= 0; i--)
		{
			p.addPoint(ix + iw - cut[i], iy + ih - i - 1);
			p.addPoint(ix + iw - cut[i], iy + ih - i);
		}
		for (int i = 0; i < n; i++)
		{
			p.addPoint(ix + cut[i], iy + ih - i);
			p.addPoint(ix + cut[i], iy + ih - i - 1);
		}
		p.addPoint(ix, iy + ih - n);
		p.addPoint(ix, iy + n);
		for (int i = n - 1; i >= 0; i--)
		{
			p.addPoint(ix + cut[i], iy + i + 1);
			p.addPoint(ix + cut[i], iy + i);
		}
		return p;
	}

	static void fill(Graphics2D g, double x, double y, double w, double h, double radius)
	{
		g.fill(shape(x, y, w, h, radius));
	}

	/** A 1px outline just inside the w×h box, following the same stepped corners pixel for pixel. */
	static void draw(Graphics2D g, double x, double y, double w, double h, double radius)
	{
		int ix = (int) Math.round(x), iy = (int) Math.round(y), iw = (int) Math.round(w), ih = (int) Math.round(h);
		if (iw <= 0 || ih <= 0)
		{
			return;
		}
		int[] cut = corner((int) Math.min(Math.round(radius), Math.min(iw, ih) / 2));
		int n = Math.min(cut.length, ih / 2);
		for (int r = 0; r < ih; r++)
		{
			int outer = cutAt(cut, n, ih, r);
			if (r == 0 || r == ih - 1)
			{
				g.fillRect(ix + outer, iy + r, iw - 2 * outer, 1);
				continue;
			}
			// The ring is as wide as the step between this row and its neighbours, so the corner stays connected
			int inner = Math.max(outer, Math.max(cutAt(cut, n, ih, r - 1), cutAt(cut, n, ih, r + 1))) + 1;
			int run = Math.min(inner - outer, iw / 2);
			g.fillRect(ix + outer, iy + r, run, 1);
			g.fillRect(ix + iw - outer - run, iy + r, run, 1);
		}
	}

	/**
	 * The game's bevel: a 1px ring inside the shape, light along the top and left and dark along the bottom and
	 * right (swap them for a pressed or sunken look). Corner steps take the colour of the edge they belong to.
	 */
	static void bevel(Graphics2D g, double x, double y, double w, double h, double radius, java.awt.Color light, java.awt.Color dark)
	{
		int ix = (int) Math.round(x), iy = (int) Math.round(y), iw = (int) Math.round(w), ih = (int) Math.round(h);
		if (iw <= 2 || ih <= 2)
		{
			return;
		}
		int[] cut = corner((int) Math.min(Math.round(radius), Math.min(iw, ih) / 2));
		int n = Math.min(cut.length, ih / 2);
		for (int r = 0; r < ih; r++)
		{
			int outer = cutAt(cut, n, ih, r);
			if (r == 0 || r == ih - 1)
			{
				g.setColor(r == 0 ? light : dark);
				g.fillRect(ix + outer, iy + r, iw - 2 * outer, 1);
				continue;
			}
			int inner = Math.max(outer, Math.max(cutAt(cut, n, ih, r - 1), cutAt(cut, n, ih, r + 1))) + 1;
			int run = Math.min(inner - outer, iw / 2);
			boolean topCorner = r < n, bottomCorner = r >= ih - n;
			// Left edge is light except the bottom-left steps (part of the bottom edge); right is dark except top-right
			g.setColor(bottomCorner ? dark : light);
			g.fillRect(ix + outer, iy + r, run, 1);
			g.setColor(topCorner ? light : dark);
			g.fillRect(ix + iw - outer - run, iy + r, run, 1);
		}
	}

	private static int cutAt(int[] cut, int n, int h, int r)
	{
		if (r < n)
		{
			return cut[r];
		}
		if (r >= h - n)
		{
			return cut[h - 1 - r];
		}
		return 0;
	}
}

