import java.util.List;
import javax.swing.JComponent;
import net.runelite.client.ui.FontManager;

/** The account score's visuals: a segmented donut and a checkpoint track. */
final class ScoreChart
{
	/** Colours for the score's parts, keyed like the server's SCORE_PARTS. */
	static Color partColor(String key)
	{
		switch (key)
		{
			case "skills":
				return ChatComponents.ACCENT;
			case "combatAchievements":
				return new Color(0xC9483F);
			case "collectionLog":
				return new Color(0x8F6AD8);
			case "quests":
				return new Color(0x3F8FD6);
			case "diaries":
				return new Color(0x3FA33F);
			default:
				return ChatComponents.MUTED;
		}
	}

	static final class Segment
	{
		final double points;
		final Color color;

		Segment(double points, Color color)
		{
			this.points = points;
			this.color = color;
		}
	}

	/** Ring out of 100: one arc per part (sized by the points it earned), ticks at the checkpoints, the score in the middle. */
	static final class Donut extends JComponent
	{
		private final int size;
		private final float thickness;
		private final double score;
		private final List<Segment> segments;
		private final List<Integer> ticks;
		private int crestItemId;
		private Color crestColor;

		Donut(double score, List<Segment> segments, List<Integer> ticks)
		{
			this(112, score, segments, ticks);
		}

		Donut(int size, double score, List<Segment> segments, List<Integer> ticks)
		{
			this.size = size;
			this.thickness = size >= 100 ? 12f : 8f;
			this.score = score;
			this.segments = segments;
			this.ticks = ticks;
		}

		/** Show the tier's crest in the middle instead of the number. */
		Donut withCrest(int itemId, Color color)
		{
			this.crestItemId = itemId;
			this.crestColor = color;
			return this;
		}

		@Override
		public Dimension getPreferredSize()
		{
			return new Dimension(size, size);
		}

		@Override
		public Dimension getMaximumSize()
		{
			return getPreferredSize();
		}

		@Override
		protected void paintComponent(Graphics g)
		{
			Graphics2D g2 = (Graphics2D) g.create();
			g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
			g2.setRenderingHint(RenderingHints.KEY_STROKE_CONTROL, RenderingHints.VALUE_STROKE_PURE);
			double inset = thickness / 2 + 1;
			double d = size - inset * 2;
			double cx = size / 2.0, cy = size / 2.0;

			paintRing(g2, inset, d, cx, cy);

			if (crestColor != null)
			{
				int inner = (int) (d - thickness * 2);
				Crest.paint(g2, this, crestItemId, crestColor, (int) cx, (int) cy, inner * 3 / 4, inner * 3 / 4);
				g2.dispose();
				return;
			}
			String value = String.valueOf((int) Math.floor(score));
			boolean compact = size < 100;
			Font big = FontManager.getRunescapeBoldFont().deriveFont(compact ? 20f : 32f);
			Font small = FontManager.getRunescapeSmallFont();
			FontMetrics bm = g2.getFontMetrics(big);
			FontMetrics sm = g2.getFontMetrics(small);
			int total = compact ? bm.getAscent() - 4 : bm.getAscent() - 4 + sm.getAscent();
			int top = (int) (cy - total / 2.0);
			g2.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_OFF);
			g2.setFont(big);
			g2.setColor(Color.WHITE);
			g2.drawString(value, (int) (cx - bm.stringWidth(value) / 2.0), top + bm.getAscent() - 4);
			if (compact)
			{
				g2.dispose();
				return;
			}
			g2.setFont(small);
			g2.setColor(ChatComponents.MUTED);
			String of = "of 100";
			g2.drawString(of, (int) (cx - sm.stringWidth(of) / 2.0), top + bm.getAscent() - 4 + sm.getAscent());
			g2.dispose();
		}

		private void paintRing(Graphics2D g2, double inset, double d, double cx, double cy)
		{
			g2.setStroke(new BasicStroke(thickness, BasicStroke.CAP_BUTT, BasicStroke.JOIN_MITER));
			g2.setColor(ChatComponents.BASE_BG);
			g2.draw(new Ellipse2D.Double(inset, inset, d, d));

			// Clockwise from 12 o'clock
			double start = 90;
			for (Segment s : segments)
			{
				double extent = s.points / 100.0 * 360;
				if (extent <= 0)
				{
					continue;
				}
				g2.setColor(s.color);
				g2.draw(new Arc2D.Double(inset, inset, d, d, start, -extent, Arc2D.OPEN));
				start -= extent;
			}

			// Checkpoint ticks cut across the ring
			g2.setStroke(new BasicStroke(2f));
			g2.setColor(ChatComponents.PANEL_BG);
			double rIn = d / 2 - thickness / 2 - 1, rOut = d / 2 + thickness / 2 + 1;
			for (int at : ticks)
			{
				double a = Math.toRadians(90 - at / 100.0 * 360);
				g2.draw(new Line2D.Double(cx + Math.cos(a) * rIn, cy - Math.sin(a) * rIn, cx + Math.cos(a) * rOut, cy - Math.sin(a) * rOut));
			}
		}
	}

	static final class Checkpoint
	{
		final String label;
		final String tooltip;
		final boolean reached;

		Checkpoint(String label, String tooltip, boolean reached)
		{
			this.label = label;
			this.tooltip = tooltip;
			this.reached = reached;
		}
	}

	/** Evenly spaced stage nodes joined by a line; reached stages are filled, the line fills toward the next one. */
	static final class Track extends JComponent
	{
		private static final int NODE = 10;
		private final List<Checkpoint> checkpoints;
		private final double towardNext;

		/** towardNext: 0..1 progress from the current stage to the next. */
		Track(List<Checkpoint> checkpoints, double towardNext)
		{
			this.checkpoints = checkpoints;
			this.towardNext = Math.max(0, Math.min(1, towardNext));
			StringBuilder tip = new StringBuilder("<html>");
			for (Checkpoint c : checkpoints)
			{
				tip.append(c.reached ? "&#10003; " : "&nbsp;&nbsp;&nbsp;").append(c.tooltip).append("<br>");
			}
			setToolTipText(tip.append("</html>").toString());
		}

		@Override
		public Dimension getPreferredSize()
		{
			return new Dimension(200, NODE + 4 + getFontMetrics(FontManager.getRunescapeSmallFont()).getHeight());
		}

		@Override
		protected void paintComponent(Graphics g)
		{
			Graphics2D g2 = (Graphics2D) g.create();
			g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
			int n = checkpoints.size();
			Font font = FontManager.getRunescapeSmallFont();
			FontMetrics fm = g2.getFontMetrics(font);
			// Keep the end labels inside the component
			int margin = Math.max(fm.stringWidth(checkpoints.get(0).label), fm.stringWidth(checkpoints.get(n - 1).label)) / 2;
			margin = Math.max(margin, NODE / 2);
			double span = getWidth() - margin * 2;
			int cy = NODE / 2;
			int current = -1;
			for (int i = 0; i < n; i++)
			{
				if (checkpoints.get(i).reached)
				{
					current = i;
				}
			}

			g2.setStroke(new BasicStroke(2f));
			for (int i = 0; i < n - 1; i++)
			{
				double x1 = margin + span * i / (n - 1), x2 = margin + span * (i + 1) / (n - 1);
				g2.setColor(ChatComponents.BASE_BG);
				g2.draw(new Line2D.Double(x1, cy, x2, cy));
				double fill = i < current ? 1 : i == current ? towardNext : 0;
				if (fill > 0)
				{
					g2.setColor(ChatComponents.ACCENT);
					g2.draw(new Line2D.Double(x1, cy, x1 + (x2 - x1) * fill, cy));
				}
			}

			g2.setFont(font);
			for (int i = 0; i < n; i++)
			{
				Checkpoint c = checkpoints.get(i);
				double x = margin + span * i / (n - 1);
				java.awt.Shape node = Pixel.shape(x - NODE / 2.0, 0, NODE, NODE, NODE / 2.0);
				g2.setColor(c.reached ? ChatComponents.ACCENT : ChatComponents.BASE_BG);
				g2.fill(node);
				if (i == current)
				{
					g2.setColor(Color.WHITE);
					Pixel.draw(g2, x - NODE / 2.0, 0, NODE, NODE, NODE / 2.0);
					Pixel.draw(g2, x - NODE / 2.0 + 1, 1, NODE - 2, NODE - 2, NODE / 2.0 - 1);
				}
				else if (!c.reached)
				{
					g2.setColor(ChatComponents.BORDER);
					Pixel.draw(g2, x - NODE / 2.0, 0, NODE, NODE, NODE / 2.0);
				}
				g2.setColor(i == current ? Color.WHITE : c.reached ? ChatComponents.MUTED.brighter() : ChatComponents.MUTED);
				g2.drawString(c.label, (int) Math.round(x - fm.stringWidth(c.label) / 2.0), NODE + 4 + fm.getAscent());
			}
			g2.dispose();
		}
	}

	/** One rank tier for the ladder. */
	static final class Tier
	{
		final String name;
		final int at;
		final int itemId;
		final Color color;
		final boolean reached;

		Tier(String name, int at, int itemId, Color color, boolean reached)
		{
			this.name = name;
			this.at = at;
			this.itemId = itemId;
			this.color = color;
			this.reached = reached;
		}
	}

	/**
	 * Every tier's crest in a row, lowest to highest: reached tiers in full colour, the current one underlined in
	 * orange, the ones to come faded. Hover a crest for its name and score.
	 */
	static final class Ladder extends JComponent
	{
		private static final int CREST = 22;
		private final java.util.List<Tier> tiers;

		Ladder(java.util.List<Tier> tiers)
		{
			this.tiers = tiers;
			setToolTipText("");
		}

		@Override
		public Dimension getPreferredSize()
		{
			return new Dimension(200, CREST + 8);
		}

		@Override
		public Dimension getMaximumSize()
		{
			return new Dimension(Integer.MAX_VALUE, CREST + 8);
		}

		private double slot()
		{
			return getWidth() / (double) Math.max(1, tiers.size());
		}

		@Override
		public String getToolTipText(MouseEvent e)
		{
			int i = (int) (e.getX() / slot());
			if (i < 0 || i >= tiers.size())
			{
				return null;
			}
			Tier t = tiers.get(i);
			return t.name + " (" + t.at + "+)" + (t.reached ? "" : ", not reached yet");
		}

		@Override
		protected void paintComponent(Graphics g)
		{
			Graphics2D g2 = (Graphics2D) g.create();
			g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
			double slot = slot();
			int current = -1;
			for (int i = 0; i < tiers.size(); i++)
			{
				if (tiers.get(i).reached)
				{
					current = i;
				}
			}
			for (int i = 0; i < tiers.size(); i++)
			{
				Tier t = tiers.get(i);
				int cx = (int) Math.round(slot * i + slot / 2);
				Graphics2D c = (Graphics2D) g2.create();
				if (!t.reached)
				{
					c.setComposite(java.awt.AlphaComposite.getInstance(java.awt.AlphaComposite.SRC_OVER, 0.3f));
				}
				Crest.paint(c, this, t.itemId, t.color, cx, CREST / 2, CREST, CREST);
				c.dispose();
				if (i == current)
				{
					g2.setColor(ChatComponents.ACCENT);
					Pixel.fill(g2, cx - 7, CREST + 4, 14, 3, 1.5);
				}
			}
			g2.dispose();
		}
	}

	private ScoreChart()
	{
	}
}

package com.squire;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.function.Consumer;
import java.util.function.IntFunction;
import java.util.regex.Pattern;
import net.runelite.api.Actor;
import net.runelite.api.Client;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.NPC;
import net.runelite.api.Player;
import net.runelite.api.Prayer;
import net.runelite.api.Skill;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.gameval.InventoryID;

/**
 * Observes a stretch of play for Squire to review afterwards: damage taken (from what, with which protection prayer
 * up), damage dealt, attacks by weapon, supplies used, kills, deaths, HP and time. It only counts; it never shows
 * anything during play (Jagex's rules forbid live boss coaching), and the summary is uploaded when it stops.
 * All methods run on the client thread.
 */
class SessionRecorder
{
	private static final int MAX_SECONDS = 60 * 60;
	private static final int MAX_HITS = 400;
	/** Ticks inside an instance (about 30 seconds) before leaving it counts as the run ending. */
	private static final int MIN_INSTANCE_TICKS = 50;
	private static final Pattern DOSE = Pattern.compile("\\s*\\(\\d\\)$");
	private static final Pattern FOOD = Pattern.compile("(?i)^(shark|paddlefish|manta ray|anglerfish|dark crab|sea turtle|tuna potato|"
		+ "cooked karambwan|karambwan|monkfish|lobster|swordfish|pineapple pizza|.*pie|.*pizza|cooked .*|.*potato.*|crystal paddlefish|"
		+ "corrupted paddlefish|blighted .*|purple sweets|saradomin brew|.*brew|jug of wine|cake|chocolate cake|.* fish)$");

	private final Client client;
	private final IntFunction<String> itemName;
	private final Consumer<Map<String, Object>> onFinished;

	private String label;
	private long startedAt;
	private int ticks;
	private final List<Map<String, Object>> areas = new ArrayList<>();
	private final List<Map<String, Object>> kills = new ArrayList<>();
	private final List<Map<String, Object>> hits = new ArrayList<>();
	private final Map<String, Integer> takenBySource = new HashMap<>();
	private final Map<String, Integer> dealtByTarget = new HashMap<>();
	private final Map<String, Integer> attacksByWeapon = new HashMap<>();
	private final Map<String, Integer> supplies = new HashMap<>();
	private final Map<Skill, Integer> startXp = new HashMap<>();
	private final Map<Integer, Integer> lastInventory = new HashMap<>();
	private int taken, whileProtected, unprotected, dealt, hitCount, zeros, maxHit, attacks, deaths, prayerSwitches, gearSwitches;
	private int hpMin = Integer.MAX_VALUE, hpStart = -1, hpEnd = -1;
	private long hpSum;
	private int lastRegion = -1, lastWeapon = -2, instanceTicks;
	private String lastPrayer;

	SessionRecorder(Client client, IntFunction<String> itemName, Consumer<Map<String, Object>> onFinished)
	{
		this.client = client;
		this.itemName = itemName;
		this.onFinished = onFinished;
	}

	boolean recording()
	{
		return label != null;
	}

	String label()
	{
		return label;
	}

	long startedAt()
	{
		return startedAt;
	}

	void start(String what)
	{
		reset();
		label = what == null || what.isBlank() ? "Session" : what.trim();
		startedAt = System.currentTimeMillis();
		for (Skill s : Skill.values())
		{
			startXp.put(s, client.getSkillExperience(s));
		}
		hpStart = client.getBoostedSkillLevel(Skill.HITPOINTS);
		snapshotInventory();
	}

	/** Stop and hand the summary to onFinished. */
	void stop(String reason)
	{
		if (label == null)
		{
			return;
		}
		Map<String, Object> summary = summary(reason);
		label = null;
		onFinished.accept(summary);
	}

	void cancel()
	{
		label = null;
	}

	// ---- Events

	void onTick()
	{
		if (label == null)
		{
			return;
		}
		ticks++;
		Player local = client.getLocalPlayer();
		if (local == null)
		{
			return;
		}
		int hp = client.getBoostedSkillLevel(Skill.HITPOINTS);
		hpMin = Math.min(hpMin, hp);
		hpSum += hp;
		hpEnd = hp;

		WorldPoint wp = WorldPoint.fromLocalInstance(client, local.getLocalLocation());
		int region = wp.getRegionID();
		if (region != lastRegion)
		{
			lastRegion = region;
			if (areas.size() < 100)
			{
				areas.add(Map.of("at", seconds(), "name", (client.getTopLevelWorldView().isInstance() ? "Instance, region " : "Region ") + region));
			}
		}
		String prayer = protection();
		if (lastPrayer != null && !String.valueOf(prayer).equals(lastPrayer))
		{
			prayerSwitches++;
		}
		lastPrayer = String.valueOf(prayer);
		ItemContainer worn = client.getItemContainer(InventoryID.WORN);
		Item weapon = worn == null ? null : worn.getItem(net.runelite.api.EquipmentInventorySlot.WEAPON.getSlotIdx());
		int weaponId = weapon == null ? -1 : weapon.getId();
		if (lastWeapon != -2 && weaponId != lastWeapon)
		{
			gearSwitches++;
		}
		lastWeapon = weaponId;
		// Leaving the instance the fight happened in (the Gauntlet, Vorkath, a raid) ends the run
		boolean instanced = client.getTopLevelWorldView().isInstance();
		if (instanced)
		{
			instanceTicks++;
		}
		else if (instanceTicks >= MIN_INSTANCE_TICKS)
		{
			stop("left the instance");
			return;
		}
		if (seconds() >= MAX_SECONDS)
		{
			stop("an hour passed");
		}
	}

	void onHitsplat(Actor target, int amount, boolean mine)
	{
		if (label == null)
		{
			return;
		}
		Player local = client.getLocalPlayer();
		if (target == local)
		{
			if (amount <= 0)
			{
				return;
			}
			String source = attackerName(local);
			String prayer = protection();
			taken += amount;
			takenBySource.merge(source, amount, Integer::sum);
			if (prayer != null)
			{
				whileProtected += amount;
			}
			else
			{
				unprotected += amount;
			}
			if (hits.size() < MAX_HITS)
			{
				Map<String, Object> h = new LinkedHashMap<>();
				h.put("at", seconds());
				h.put("source", source);
				h.put("damage", amount);
				h.put("prayer", prayer);
				h.put("hp", client.getBoostedSkillLevel(Skill.HITPOINTS));
				hits.add(h);
			}
		}
		else if (mine && target instanceof NPC)
		{
			String name = ((NPC) target).getName();
			dealt += amount;
			hitCount++;
			if (amount == 0)
			{
				zeros++;
			}
			maxHit = Math.max(maxHit, amount);
			dealtByTarget.merge(name == null ? "Unknown" : name, amount, Integer::sum);
		}
	}

	/** The player started an attack animation while fighting an NPC. */
	void onPlayerAnimation(Player player)
	{
		if (label == null || player != client.getLocalPlayer() || player.getAnimation() == -1 || !(player.getInteracting() instanceof NPC))
		{
			return;
		}
		attacks++;
		ItemContainer worn = client.getItemContainer(InventoryID.WORN);
		Item weapon = worn == null ? null : worn.getItem(net.runelite.api.EquipmentInventorySlot.WEAPON.getSlotIdx());
		attacksByWeapon.merge(weapon == null ? "Unarmed" : itemName.apply(weapon.getId()), 1, Integer::sum);
	}

	void onDeath(Actor actor)
	{
		if (label == null)
		{
			return;
		}
		if (actor == client.getLocalPlayer())
		{
			deaths++;
			stop("died");
		}
		else if (actor instanceof NPC && dealtByTarget.containsKey(((NPC) actor).getName()))
		{
			if (kills.size() < 500)
			{
				kills.add(Map.of("at", seconds(), "npc", String.valueOf(((NPC) actor).getName())));
			}
		}
	}

	/** Inventory changed: count food eaten and potion doses drunk. */
	void onInventoryChanged(ItemContainer inv)
	{
		if (label == null)
		{
			return;
		}
		Map<Integer, Integer> now = counts(inv);
		for (Map.Entry<Integer, Integer> e : lastInventory.entrySet())
		{
			int before = e.getValue(), after = now.getOrDefault(e.getKey(), 0);
			if (after < before)
			{
				String name = itemName.apply(e.getKey());
				if (DOSE.matcher(name).find())
				{
					supplies.merge(DOSE.matcher(name).replaceAll("") + " (doses)", before - after, Integer::sum);
				}
				else if (FOOD.matcher(name).matches())
				{
					supplies.merge(name, before - after, Integer::sum);
				}
			}
		}
		lastInventory.clear();
		lastInventory.putAll(now);
	}

	// ---- Helpers

	private int seconds()
	{
		return (int) ((System.currentTimeMillis() - startedAt) / 1000);
	}

	/** The protection prayer up right now, or null. */
	private String protection()
	{
		if (client.isPrayerActive(Prayer.PROTECT_FROM_MAGIC))
		{
			return "Protect from Magic";
		}
		if (client.isPrayerActive(Prayer.PROTECT_FROM_MISSILES))
		{
			return "Protect from Missiles";
		}
		if (client.isPrayerActive(Prayer.PROTECT_FROM_MELEE))
		{
			return "Protect from Melee";
		}
		return null;
	}

	/** Who's hitting the player: an NPC targeting them, else whatever they're fighting. */
	private String attackerName(Player local)
	{
		for (NPC npc : client.getTopLevelWorldView().npcs())
		{
			if (npc != null && npc.getInteracting() == local && npc.getName() != null)
			{
				return npc.getName();
			}
		}
		Actor target = local.getInteracting();
		return target != null && target.getName() != null ? target.getName() : "Unknown";
	}

	private void snapshotInventory()
	{
		lastInventory.clear();
		ItemContainer inv = client.getItemContainer(InventoryID.INV);
		if (inv != null)
		{
			lastInventory.putAll(counts(inv));
		}
	}

	private static Map<Integer, Integer> counts(ItemContainer inv)
	{
		Map<Integer, Integer> out = new HashMap<>();
		for (Item i : inv.getItems())
		{
			if (i != null && i.getId() > 0)
			{
				out.merge(i.getId(), Math.max(1, i.getQuantity()), Integer::sum);
			}
		}
		return out;
	}

	private Map<String, Object> summary(String reason)
	{
		Map<String, Object> s = new LinkedHashMap<>();
		s.put("label", label);
		s.put("startedAt", startedAt);
		s.put("durationSeconds", seconds());
		s.put("endedBy", reason);
		s.put("areas", areas);
		s.put("kills", kills);
		s.put("deaths", deaths);
		s.put("damageTaken", Map.of("total", taken, "bySource", takenBySource, "whileProtected", whileProtected, "unprotected", unprotected, "hits", hits));
		s.put("damageDealt", Map.of("total", dealt, "byTarget", dealtByTarget, "hits", hitCount, "zeros", zeros, "maxHit", maxHit));
		s.put("attacks", Map.of("total", attacks, "byWeapon", attacksByWeapon));
		s.put("supplies", supplies);
		Map<String, Object> hp = new LinkedHashMap<>();
		hp.put("min", hpMin == Integer.MAX_VALUE ? null : hpMin);
		hp.put("average", ticks == 0 ? null : Math.round(hpSum / (double) ticks));
		hp.put("start", hpStart < 0 ? null : hpStart);
		hp.put("end", hpEnd < 0 ? null : hpEnd);
		s.put("hitpoints", hp);
		s.put("prayerSwitches", prayerSwitches);
		s.put("gearSwitches", gearSwitches);
		Map<String, Integer> xp = new HashMap<>();
		for (Skill sk : Skill.values())
		{
			int gained = client.getSkillExperience(sk) - startXp.getOrDefault(sk, client.getSkillExperience(sk));
			if (gained > 0)
			{
				xp.put(sk.getName(), gained);
			}
		}
		s.put("xp", xp);
		return s;
	}

	private void reset()
	{
		ticks = 0;
		areas.clear();
		kills.clear();
		hits.clear();
		takenBySource.clear();
		dealtByTarget.clear();
		attacksByWeapon.clear();
		supplies.clear();
		startXp.clear();
		lastInventory.clear();
		taken = whileProtected = unprotected = dealt = hitCount = zeros = maxHit = attacks = deaths = prayerSwitches = gearSwitches = 0;
		hpMin = Integer.MAX_VALUE;
		hpStart = hpEnd = -1;
		hpSum = 0;
		lastRegion = -1;
		lastWeapon = -2;
		instanceTicks = 0;
		lastPrayer = null;
	}
}

