	/**
	 * An action row: label with an optional small muted detail line under it (e.g. the sync status), a chevron, and
	 * a tooltip. {@code color} tints the label and chevron (red for destructive actions); null for the default.
	 */
	private static JComponent actionRow(String label, String detail, String tooltip, Color color, Runnable onClick)
	{
		Color rest = color != null ? color : net.runelite.client.ui.ColorScheme.LIGHT_GRAY_COLOR;
		Color hot = color != null ? color.brighter() : Color.WHITE;
		Surface r = new Surface(null, 0, false);
		r.setLayout(new BorderLayout(8, 0));
		r.setBorder(detail == null ? BorderFactory.createEmptyBorder(0, 10, 0, 12) : BorderFactory.createEmptyBorder(7, 10, 7, 12));
		javax.swing.JPanel words = new javax.swing.JPanel();
		words.setOpaque(false);
		words.setLayout(new javax.swing.BoxLayout(words, javax.swing.BoxLayout.Y_AXIS));
		JLabel title = Ui.text(label, rest);
		JLabel sub = Ui.small(detail == null ? "" : detail);
		title.setAlignmentX(LEFT_ALIGNMENT);
		sub.setAlignmentX(LEFT_ALIGNMENT);
		if (detail != null)
		{
			words.add(title);
			words.add(sub);
		}
		else
		{
			// Just the label: centre it in the row
			words.add(javax.swing.Box.createVerticalGlue());
			words.add(title);
			words.add(javax.swing.Box.createVerticalGlue());
		}
		r.add(words, BorderLayout.CENTER);
		JLabel chevron = new JLabel(SvgIcon.load("chevron-right", 16, color));
		r.add(chevron, BorderLayout.EAST);
		r.setToolTipText("<html>" + MarkdownLite.escape(tooltip).replace("\n", "<br>") + "</html>");
		r.setAlignmentX(LEFT_ALIGNMENT);
		int height = detail == null ? 32 : r.getPreferredSize().height;
		r.setPreferredSize(new java.awt.Dimension(100, height));
		r.setMaximumSize(new java.awt.Dimension(Integer.MAX_VALUE, height));
		r.setCursor(java.awt.Cursor.getPredefinedCursor(java.awt.Cursor.HAND_CURSOR));
		java.awt.event.MouseAdapter m = new java.awt.event.MouseAdapter()
		{
			@Override
			public void mouseReleased(java.awt.event.MouseEvent e)
			{
				// On release rather than click: Swing drops a click if the pointer moves a pixel while pressed
				if (!javax.swing.SwingUtilities.isLeftMouseButton(e) || !e.getComponent().contains(e.getPoint()))
				{
					return;
				}
				onClick.run();
			}

			@Override
			public void mouseEntered(java.awt.event.MouseEvent e)
			{
				r.setFill(ChatComponents.HOVER_BG);
				title.setForeground(hot);
			}

			@Override
			public void mouseExited(java.awt.event.MouseEvent e)
			{
				if (!r.contains(SwingUtilities.convertPoint(e.getComponent(), e.getPoint(), r)))
				{
					r.setFill(null);
					title.setForeground(rest);
				}
			}
		};
		for (java.awt.Component c : new java.awt.Component[]{r, words, title, sub, chevron})
		{
			c.addMouseListener(m);
		}
		return r;
	}

	/** Pick a provider and paste a key; it goes straight to the server (stored encrypted there, not on this computer). */
	private void addKeyDialog()
	{
		if (keyProviders.isEmpty())
		{
			return;
		}
		javax.swing.JComboBox<String> provider = new javax.swing.JComboBox<>(keyProviders.stream().map(p -> p[1]).toArray(String[]::new));
		javax.swing.JPasswordField key = new javax.swing.JPasswordField(24);
		javax.swing.JPanel form = new javax.swing.JPanel(new java.awt.GridLayout(0, 1, 0, 4));
		form.add(new JLabel("Provider"));
		form.add(provider);
		form.add(new JLabel("API key"));
		form.add(key);
		form.add(new JLabel("<html><body style='width:230px'>Squire checks which models your key can use. It's stored encrypted on the server and never shown again.</body></html>"));
		int answer = javax.swing.JOptionPane.showConfirmDialog(this, form, "Add an API key", javax.swing.JOptionPane.OK_CANCEL_OPTION, javax.swing.JOptionPane.PLAIN_MESSAGE);
		String value = new String(key.getPassword()).trim();
		java.util.Arrays.fill(key.getPassword(), '\0');
		if (answer == javax.swing.JOptionPane.OK_OPTION && !value.isEmpty())
		{
			onSaveKey.accept(keyProviders.get(provider.getSelectedIndex())[0], value);
		}
	}

	/** Forget a note, or for a goal, mark it done. */
	private void memoryMenu(String[] n)
	{
		boolean goal = "goal".equals(n[1]);
		Object[] options = goal ? new Object[]{"Mark done", "Forget", "Cancel"} : new Object[]{"Forget", "Cancel"};
		int choice = javax.swing.JOptionPane.showOptionDialog(this, n[2], goal ? "Goal" : "Squire remembers",
			javax.swing.JOptionPane.DEFAULT_OPTION, javax.swing.JOptionPane.PLAIN_MESSAGE, null, options, options[options.length - 1]);
		if (goal && choice == 0)
		{
			onFinish.accept(n);
		}
		else if (choice == (goal ? 1 : 0))
		{
			onForget.accept(n);
		}
	}

	private static String escape(String s)
	{
		return s.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;");
	}

	private void group(String title)
	{
		JLabel label = Ui.bold(title);
		// Indented to line up with the row labels inside the cards
		label.setBorder(BorderFactory.createEmptyBorder(0, 11, 0, 0));
		list.add(ChatComponents.place(label, Align.LEFT, list.getComponentCount() == 0 ? 6 : 18));
	}

	private void note(String text)
	{
		list.add(ChatComponents.place(new Note(text), Align.FILL, 6));
	}

	/** An editable setting: clicking runs {@code onClick}, or, with {@code onShortcut}, records the next key combo. */
	static final class Item
	{
		final String label;
		final String value;
		final String tooltip;
		final Runnable onClick;
		final java.util.function.Consumer<net.runelite.client.config.Keybind> onShortcut;
		/** Non-null for on/off settings, drawn as a switch. */
		final Boolean on;

		private Item(String label, String value, String tooltip, Runnable onClick, java.util.function.Consumer<net.runelite.client.config.Keybind> onShortcut, Boolean on)
		{
			this.label = label;
			this.value = value;
			this.tooltip = tooltip;
			this.onClick = onClick;
			this.onShortcut = onShortcut;
			this.on = on;
		}

		/** An on/off setting, shown as a switch. */
		static Item toggle(String label, boolean on, String tooltip, Runnable onClick)
		{
			return new Item(label, null, tooltip, onClick, null, on);
		}

		/** A value that changes when clicked (a toggle, or the next option). */
		static Item choice(String label, String value, String tooltip, Runnable onClick)
		{
			return new Item(label, value, tooltip, onClick, null, null);
		}

		/** A keyboard shortcut: click, then press the new combination (Esc cancels, Backspace clears). */
		static Item shortcut(String label, String value, String tooltip, java.util.function.Consumer<net.runelite.client.config.Keybind> onShortcut)
		{
			return new Item(label, value, tooltip, null, onShortcut, null);
		}

		/** Read-only. */
		static Item info(String label, String value)
		{
			return new Item(label, value, null, null, null, null);
		}
	}

	private JComponent itemRow(Item item)
	{
		if (item.on != null)
		{
			JComponent r = HomeView.listRow(null, item.label, new ChatComponents.Switch(item.on), item.onClick);
			r.setToolTipText(item.tooltip);
			return r;
		}
		JLabel value = Ui.text(item.value == null ? "" : item.value, ChatComponents.MUTED);
		if (item.onShortcut == null)
		{
			JComponent r = HomeView.listRow(null, item.label, value, item.onClick);
			r.setToolTipText(item.tooltip);
			return r;
		}
		// Shortcut: the row takes focus and records the next key combination
		JComponent[] holder = new JComponent[1];
		holder[0] = HomeView.listRow(null, item.label, value, () ->
		{
			value.setText("Press keys...");
			value.setForeground(ChatComponents.ACCENT);
			holder[0].setFocusable(true);
			holder[0].requestFocusInWindow();
		});
		JComponent r = holder[0];
		r.setToolTipText(item.tooltip);
		r.addKeyListener(new java.awt.event.KeyAdapter()
		{
			@Override
			public void keyPressed(java.awt.event.KeyEvent e)
			{
				if (!"Press keys...".equals(value.getText()))
				{
					return;
				}
				int code = e.getKeyCode();
				if (code == java.awt.event.KeyEvent.VK_SHIFT || code == java.awt.event.KeyEvent.VK_CONTROL
					|| code == java.awt.event.KeyEvent.VK_ALT || code == java.awt.event.KeyEvent.VK_META)
				{
					return; // wait for the actual key
				}
				e.consume();
				if (code == java.awt.event.KeyEvent.VK_ESCAPE)
				{
					render();
					return;
				}
				item.onShortcut.accept(code == java.awt.event.KeyEvent.VK_BACK_SPACE
					? net.runelite.client.config.Keybind.NOT_SET
					: new net.runelite.client.config.Keybind(code, e.getModifiersEx()));
			}
		});
		r.addFocusListener(new java.awt.event.FocusAdapter()
		{
			@Override
			public void focusLost(java.awt.event.FocusEvent e)
			{
				if ("Press keys...".equals(value.getText()))
				{
					render();
				}
			}
		});
		return r;
	}

	/** A settings row: label, value on the right (or a chevron when it does something). */
	private static JComponent row(String label, String value, String tooltip, Runnable onClick)
	{
		JComponent right;
		if (onClick != null)
		{
			right = new JLabel(SvgIcon.load("chevron-right", 16, null));
		}
		else
		{
			JLabel v = Ui.text(value == null ? "" : value, ChatComponents.MUTED);
			v.setToolTipText(tooltip);
			right = v;
		}
		JComponent r = HomeView.listRow(null, label, right, onClick);
		r.setToolTipText(tooltip);
		return r;
	}

	private static String strip(String html)
	{
		return html.replaceAll("<[^>]+>", "").replace("&amp;", "&").trim();
	}

	/** Muted, wrapping text under a group; the list asks it for its height at the width it gets. */
	private static final class Note extends JTextArea implements ChatComponents.HeightForWidth
	{
		Note(String text)
		{
			super(text);
			setLineWrap(true);
			setWrapStyleWord(true);
			setEditable(false);
			setFocusable(false);
			setOpaque(false);
			setFont(FontManager.getRunescapeSmallFont());
			setForeground(ChatComponents.MUTED);
			setBorder(BorderFactory.createEmptyBorder(0, 12, 0, 12));
		}

		@Override
		public int heightForWidth(int width)
		{
			setSize(width, Short.MAX_VALUE);
			return getPreferredSize().height;
		}

		@Override
		public Color getBackground()
		{
			return new Color(0, 0, 0, 0);
		}
	}
}

package com.squire;

import com.google.gson.JsonObject;
import com.squire.ChatComponents.Align;
import com.squire.ChatComponents.MessageList;
import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.Image;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import java.util.function.BooleanSupplier;
import java.util.function.Consumer;
import javax.imageio.ImageIO;
import javax.swing.BorderFactory;
import javax.swing.BoxLayout;
import javax.swing.JComponent;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JScrollPane;
import javax.swing.ScrollPaneConstants;
import javax.swing.SwingUtilities;
import javax.swing.Timer;
import net.runelite.client.ui.FontManager;

/**
 * Set up, straight after Continue: one card for what syncs by itself (the account, then its Wise Old Man history),
 * turning green when it's done, then what needs the player: opening the bank and the collection log. It checks the
 * server every few seconds while it's on screen. "Finish later" leaves it for Home, which keeps a way back.
 */
class SetupView extends JPanel
{
	interface Controller
	{
		/** The server's view: {synced, history: waiting|importing|done|none, bank, collectionLog}, or an error. */
		void fetch(Consumer<AccountApi.Result> callback);

		boolean loggedIn();

		/** The page came on screen or left it (the plugin captures the collection log as soon as it opens meanwhile). */
		void visible(boolean visible);

		/** Everything is done: Home stops offering the page. */
		void completed();

		/** Finish later, or Done: back to Home. */
		void leave();
	}

	static final Color DONE = Tokens.COLOR_STATUS_DONE;
	private static final Color EDGE = Tokens.COLOR_BORDER_EDGE;
	private static final int POLL_MS = 3000;

	private final Controller controller;
	private final MessageList list = new MessageList(null, 0);
	private final ChatComponents.AccentButton later = new ChatComponents.AccentButton("Finish later", true);
	private final ChatComponents.AccentButton done = new ChatComponents.AccentButton("Done");
	private final JPanel bottom = new JPanel(new BorderLayout());
	private final Timer poll;
	private final Timer spin;
	private JsonObject state;
	private int spinStep;
	private boolean reportedComplete;

	SetupView(Controller controller)
	{
		super(new BorderLayout());
		this.controller = controller;
		setOpaque(false);
		list.setBorder(BorderFactory.createEmptyBorder(1, 1, 12, 1));
		JScrollPane scroll = new JScrollPane(list);
		scroll.setOpaque(false);
		scroll.getViewport().setOpaque(false);
		scroll.setBorder(BorderFactory.createEmptyBorder());
		scroll.setHorizontalScrollBarPolicy(ScrollPaneConstants.HORIZONTAL_SCROLLBAR_NEVER);
		scroll.getVerticalScrollBar().setUnitIncrement(16);
		add(scroll);

		later.addActionListener(e -> controller.leave());
		done.addActionListener(e -> controller.leave());
		bottom.setOpaque(false);
		bottom.setBorder(BorderFactory.createEmptyBorder(4, 0, 0, 0));
		add(bottom, BorderLayout.SOUTH);

		poll = new Timer(POLL_MS, e -> fetch());
		spin = new Timer(100, e ->
		{
			spinStep = (spinStep + 1) % 8;
			list.repaint();
		});
		render();
	}

	/** The page came on screen: check now, then every few seconds until it leaves. */
	void onShown()
	{
		controller.visible(true);
		fetch();
		poll.start();
		spin.start();
	}

	void onHidden()
	{
		controller.visible(false);
		poll.stop();
		spin.stop();
	}

	/** For previews: show this state without fetching. */
	void show(JsonObject state)
	{
		this.state = state;
		render();
	}

	private void fetch()
	{
		if (!isShowing() && poll.isRunning())
		{
			onHidden();
			return;
		}
		controller.fetch(result -> SwingUtilities.invokeLater(() ->
		{
			if (result.json != null)
			{
				state = result.json;
				render();
			}
		}));
	}

	private boolean flag(String key)
	{
		return state != null && state.has(key) && state.get(key).getAsBoolean();
	}

	private String history()
	{
		return state != null && state.has("history") ? state.get("history").getAsString() : "waiting";
	}

	private void render()
	{
		boolean synced = flag("synced");
		String history = history();
		boolean dataDone = synced && ("done".equals(history) || "none".equals(history));
		boolean bank = flag("bank"), clog = flag("collectionLog");
		boolean complete = dataDone && bank && clog;

		list.removeAll();
		list.add(ChatComponents.place(syncCard(synced, history, dataDone), Align.FILL, 0));
		list.add(ChatComponents.place(groupTitle("Needs you"), Align.FILL, 4));
		list.add(ChatComponents.place(new Task("bank.png", "Open your bank", "Needed for gear, setups and plans",
			"Bank synced", bank), Align.FILL, 4));
		list.add(ChatComponents.place(new Task("collection-log.png", "Open your collection log", "Needed for log goals and your score",
			"Collection log synced", clog), Align.FILL, 4));
		list.revalidate();
		list.repaint();

		bottom.removeAll();
		bottom.add(complete ? done : later);
		bottom.revalidate();
		bottom.repaint();

		if (complete && !reportedComplete)
		{
			reportedComplete = true;
			controller.completed();
		}
	}

	private JComponent syncCard(boolean synced, String history, boolean finished)
	{
		String title, detail;
		double progress;
		if (finished)
		{
			title = "Your data is synced";
			detail = "none".equals(history) ? "Stats, quests and diaries" : "Stats, quests, diaries and your history";
			progress = 1;
		}
		else if (synced)
		{
			title = "Syncing your data";
			detail = "Importing your history from Wise Old Man...";
			progress = 0.75;
		}
		else if (controller.loggedIn())
		{
			title = "Syncing your data";
			detail = "Sending your stats, quests and diaries...";
			progress = 0.35;
		}
		else
		{
			title = "Syncing your data";
			detail = "Log in to the game to start";
			progress = 0.05;
		}
		return new SyncCard(title, detail, progress, finished);
	}

	private static JComponent groupTitle(String text)
	{
		JLabel l = Ui.bold(text);
		l.setBorder(BorderFactory.createEmptyBorder(10, 11, 2, 0));
		return l;
	}

	/** Two lines of text: a bold title and a small muted detail. */
	private static JPanel textBlock(String title, String detail)
	{
		JPanel text = new JPanel();
		text.setOpaque(false);
		text.setLayout(new BoxLayout(text, BoxLayout.Y_AXIS));
		JLabel t = Ui.bold(title);
		JLabel d = Ui.small(detail);
		d.setBorder(BorderFactory.createEmptyBorder(1, 0, 0, 0));
		text.add(t);
		text.add(d);
		return text;
	}

	/** A card in the design's frame: stepped corners, a 1px edge and the game's bevel. */
	private static void frame(Graphics2D g2, int w, int h, Color fill, Color edge)
	{
		g2.setColor(fill);
		Pixel.fill(g2, 0, 0, w, h, 4);
		g2.setColor(edge);
		Pixel.draw(g2, 0, 0, w, h, 4);
		Pixel.bevel(g2, 1, 1, w - 2, h - 2, 3, ChatComponents.CARD_LIGHT, ChatComponents.CARD_DARK);
	}

	/** What syncs by itself: a progress bar along the top, then a status and two lines of text. Green when done. */
	private final class SyncCard extends JPanel
	{
		private final double progress;
		private final boolean finished;

		SyncCard(String title, String detail, double progress, boolean finished)
		{
			super(new BorderLayout(8, 0));
			this.progress = progress;
			this.finished = finished;
			setOpaque(false);
			setBorder(BorderFactory.createEmptyBorder(7 + 8, 10, 8, 10));
			JComponent status = new Status(finished ? Status.DONE : Status.LOADING);
			JPanel west = new JPanel(new BorderLayout());
			west.setOpaque(false);
			west.add(status, BorderLayout.NORTH);
			add(west, BorderLayout.WEST);
			add(textBlock(title, detail));
		}

		@Override
		protected void paintComponent(Graphics g)
		{
			Graphics2D g2 = (Graphics2D) g.create();
			int w = getWidth(), h = getHeight();
			frame(g2, w, h, ChatComponents.CARD_BG, finished ? DONE : EDGE);
			// The bar runs edge to edge just inside the frame
			int bw = w - 2;
			g2.setColor(ChatComponents.BASE_BG);
			g2.fillRect(1, 1, bw, 6);
			g2.setColor(finished ? DONE : ChatComponents.ACCENT);
			g2.fillRect(1, 1, (int) Math.round(bw * progress), 6);
			g2.dispose();
		}
	}

	/** Something the player does in game: its icon, what to do and why, and a status on the right. */
	private final class Task extends JPanel
	{
		Task(String iconFile, String title, String detail, String doneDetail, boolean finished)
		{
			super(new BorderLayout(8, 0));
			setOpaque(false);
			setBorder(BorderFactory.createEmptyBorder(8, 10, 8, 10));
			JLabel icon = new JLabel(icon(iconFile));
			icon.setPreferredSize(new Dimension(32, 32));
			add(icon, BorderLayout.WEST);
			add(textBlock(title, finished ? doneDetail : detail));
			JPanel east = new JPanel(new java.awt.GridBagLayout());
			east.setOpaque(false);
			east.add(new Status(finished ? Status.DONE : Status.WAITING));
			add(east, BorderLayout.EAST);
		}

		@Override
		protected void paintComponent(Graphics g)
		{
			Graphics2D g2 = (Graphics2D) g.create();
			frame(g2, getWidth(), getHeight(), ChatComponents.CARD_BG, EDGE);
			g2.dispose();
		}
	}

	/** The wiki's small game icons, scaled in whole steps so the pixels stay crisp, centred in 32px. */
	private static javax.swing.Icon icon(String file)
	{
		BufferedImage img;
		try (java.io.InputStream in = SetupView.class.getResourceAsStream("welcome/" + file))
		{
			img = in == null ? null : ImageIO.read(in);
		}
		catch (java.io.IOException e)
		{
			img = null;
		}
		if (img == null)
		{
			return null;
		}
		int scale = Math.max(1, 32 / Math.max(img.getWidth(), img.getHeight()));
		Image scaled = img.getScaledInstance(img.getWidth() * scale, img.getHeight() * scale, Image.SCALE_REPLICATE);
		BufferedImage out = new BufferedImage(32, 32, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = out.createGraphics();
		g.drawImage(scaled, (32 - img.getWidth() * scale) / 2, (32 - img.getHeight() * scale) / 2, null);
		g.dispose();
		return new javax.swing.ImageIcon(out);
	}

	/** The design's 12px pixel statuses: a spinner, a green tick, or an empty box. */
	private final class Status extends JComponent
	{
		static final int LOADING = 0, DONE = 1, WAITING = 2;
		private final int kind;

		Status(int kind)
		{
			this.kind = kind;
			Dimension d = new Dimension(12, 17);
			setPreferredSize(d);
			setMinimumSize(d);
			setMaximumSize(d);
		}

		@Override
		protected void paintComponent(Graphics g)
		{
			Graphics2D g2 = (Graphics2D) g.create();
			g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_OFF);
			int y = 2;
			switch (kind)
			{
				case LOADING:
				{
					// Eight 2px dots in a ring; the bright one walks round
					int[][] dots = {{5, 0}, {9, 1}, {10, 5}, {9, 9}, {5, 10}, {1, 9}, {0, 5}, {1, 1}};
					int[] shades = {0xFFFFFF, 0xBBBBBB, 0x888888, 0x555555, 0x555555, 0x555555, 0x555555, 0x555555};
					for (int i = 0; i < dots.length; i++)
					{
						g2.setColor(new Color(shades[(i - spinStep + 8) % 8]));
						g2.fillRect(dots[i][0], y + dots[i][1], 2, 2);
					}
					break;
				}
				case DONE:
				{
					g2.setColor(SetupView.DONE);
					// A stepped tick
					int[][] tick = {{0, 5}, {2, 7}, {4, 9}, {6, 7}, {8, 5}, {10, 3}, {10, 1}};
					for (int[] p : tick)
					{
						g2.fillRect(p[0], y + p[1], 2, 2);
					}
					break;
				}
				default:
					g2.setColor(ChatComponents.BORDER);
					g2.drawRect(0, y, 11, 11);
			}
			g2.dispose();
		}
	}
}

package com.squire;

import java.util.HashMap;
import java.util.Map;
import java.util.function.Supplier;
import net.runelite.api.Client;
import net.runelite.api.MessageNode;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.JavaScriptCallback;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.WidgetPositionMode;
import net.runelite.api.widgets.WidgetSizeMode;
import net.runelite.api.widgets.WidgetTextAlignment;
import net.runelite.api.widgets.WidgetType;

/**
 * A "Squire" stone among the chatbox's bottom tabs, between Trade and Report: the other tabs narrow a little to
 * make room. An icon beside the name shows Squire's status (Ready, Thinking, Observing, New). Clicking it focuses
 * the chatbox on Squire: only Squire's lines show, and what the player types goes to Squire instead of the game;
 * clicking any game tab goes back. Nothing is ever typed for the player.
 * All methods run on the client thread.
 */
class SquireChatTab
{
	/** The game's tabs, left to right; Squire goes in before Report. */
	private static final int[] TABS = {
		InterfaceID.Chatbox.CHAT_ALL, InterfaceID.Chatbox.CHAT_GAME, InterfaceID.Chatbox.CHAT_PUBLIC, InterfaceID.Chatbox.CHAT_PRIVATE,
		InterfaceID.Chatbox.CHAT_FRIENDSCHAT, InterfaceID.Chatbox.CHAT_CLAN, InterfaceID.Chatbox.CHAT_TRADE,
	};
	private static final int REPORT = InterfaceID.Chatbox.REPORTABUSE;
	private static final int YELLOW = 0xFFFF00, ORANGE = 0xFF981F, WHITE = 0xFFFFFF;

	private final Client client;
	private final Runnable openPrompt;
	private final Supplier<String> busyStatus;
	private final Runnable rebuildChat;
	private final Runnable openPanel;
	private final Supplier<String> panelShortcut;

	private Widget graphic;
	private Widget name;
	/** The status icon left of the name (Ready, Thinking, Observing, New). */
	private Widget status;

	// Status icons, drawn here and registered as sprites under ids the game doesn't use
	private static final int SPRITE_BASE = 0x5C0100;
	private static final int READY = SPRITE_BASE, THINKING = SPRITE_BASE + 1, OBSERVING = SPRITE_BASE + 2, NEW = SPRITE_BASE + 3;
	private static final int ICON = 13;
	private boolean spritesAdded;
	private Widget parent;
	/** The tabs' own positions, to put back when the tab is turned off. */
	private final Map<Integer, int[]> original = new HashMap<>();
	/** The game's own tab row: {left, right, y, height}, and the bar width it was measured at. */
	private int[] natural;
	private int naturalBarWidth = -1;
	private boolean focused;
	private int unread;

	/**
	 * @param openPrompt opens the Ask Squire chatbox prompt
	 * @param busyStatus "Thinking" or "Observing" while that's happening, else null
	 * @param rebuildChat redraws the chatbox (later, not from inside the game's click handler)
	 */
	SquireChatTab(Client client, Runnable openPrompt, Supplier<String> busyStatus, Runnable rebuildChat, Runnable openPanel, Supplier<String> panelShortcut)
	{
		this.openPanel = openPanel;
		this.panelShortcut = panelShortcut;
		this.rebuildChat = rebuildChat;
		this.client = client;
		this.openPrompt = openPrompt;
		this.busyStatus = busyStatus;
	}

	boolean focused()
	{
		return focused;
	}

	/** A Squire line was printed: counts as unread unless the tab is focused. */
	void onSquireLine()
	{
		if (!focused)
		{
			unread++;
		}
	}

	/** Put the tab in place (and keep it there after the game redraws the chatbox). Cheap when nothing changed. */
	void update()
	{
		Widget all = client.getWidget(TABS[0]);
		Widget report = client.getWidget(REPORT);
		if (all == null || report == null || all.getParent() == null)
		{
			return;
		}
		Widget bar = all.getParent();
		if (bar != parent || graphic == null || graphic.getParent() != bar)
		{
			parent = bar;
			create(bar);
		}
		layout(bar);
		refreshStatus();
	}

	/** Remove the tab and put the game's tabs back as they were. */
	void remove()
	{
		setFocused(false);
		restoreGameTabs();
		natural = null;
		for (Widget w : new Widget[]{graphic, name, status})
		{
			if (w != null)
			{
				w.setHidden(true);
			}
		}
		graphic = name = status = null;
		parent = null;
		removeSprites();
	}

	/** Called for every chat line while filtering: false hides it (focused mode shows only Squire's lines). */
	boolean keep(int messageId)
	{
		if (!focused)
		{
			return true;
		}
		MessageNode node = client.getMessages().get(messageId);
		return node != null && InGameChat.isSquireLine(node.getValue());
	}

	/** The player clicked one of the game's tabs: leave Squire focus. */
	void onGameTabClicked()
	{
		if (focused)
		{
			setFocused(false);
		}
	}

	static boolean isGameTab(int widgetId)
	{
		for (int t : TABS)
		{
			if (t == widgetId)
			{
				return true;
			}
		}
		return widgetId == REPORT;
	}

	// ----

	private void setFocused(boolean on)
	{
		if (focused == on)
		{
			return;
		}
		focused = on;
		if (on)
		{
			unread = 0;
		}
		refreshStatus();
		// Redraw the chatbox so the filter applies
		rebuildChat.run();
	}

	private void create(Widget bar)
	{
		Widget sampleGraphic = child(TABS[TABS.length - 1], 0);
		Widget sampleName = client.getWidget(InterfaceID.Chatbox.CHAT_TRADE_TEXT);
		graphic = bar.createChild(-1, WidgetType.GRAPHIC);
		learnSprites();
		if (normalSprite >= 0)
		{
			graphic.setSpriteId(normalSprite);
		}
		else if (sampleGraphic != null)
		{
			graphic.setSpriteId(sampleGraphic.getSpriteId());
		}
		name = bar.createChild(-1, WidgetType.TEXT);
		name.setText("Squire");
		styleText(name, sampleName, WHITE);
		// One centred line, like a tab without a filter label
		name.setYTextAlignment(WidgetTextAlignment.CENTER);
		addSprites();
		status = bar.createChild(-1, WidgetType.GRAPHIC);
		status.setSpriteId(READY);

		// No target name: the game's own tabs show just the option ("Switch tab"), not "Option Target"
		graphic.setName("");
		graphic.setAction(0, "View Squire");
		graphic.setAction(1, "Ask Squire");
		graphic.setAction(2, panelAction());
		graphic.setHasListener(true);
		graphic.setOnOpListener((JavaScriptCallback) ev ->
		{
			switch (ev.getOp())
			{
				case 1:
					// Shift-click opens the panel; a plain click shows only Squire's lines and the chatbox talks to
					// Squire (see onChatboxInput)
					if (client.isKeyPressed(net.runelite.api.KeyCode.KC_SHIFT))
					{
						openPanel.run();
					}
					else
					{
						setFocused(true);
					}
					break;
				case 2:
					openPrompt.run();
					break;
				case 3:
					openPanel.run();
					break;
				default:
					setFocused(false);
			}
		});
	}

	private static void styleText(Widget w, Widget sample, int color)
	{
		if (sample != null)
		{
			w.setFontId(sample.getFontId());
			w.setTextShadowed(sample.getTextShadowed());
		}
		w.setTextColor(color);
		// Same alignment as the game's tab text: the name at the top, the status at the bottom
		w.setXTextAlignment(sample != null ? sample.getXTextAlignment() : WidgetTextAlignment.CENTER);
		w.setYTextAlignment(sample != null ? sample.getYTextAlignment() : WidgetTextAlignment.CENTER);
	}

	/** Nine even slots across the bar: the seven chat tabs, Squire, Report. */
	private void layout(Widget bar)
	{
		Widget all = client.getWidget(TABS[0]);
		Widget report = client.getWidget(REPORT);
		// Where the game itself puts the tabs (captured before we move anything, per bar width)
		if (natural == null || naturalBarWidth != bar.getWidth())
		{
			restoreGameTabs();
			natural = new int[]{all.getRelativeX(), report.getRelativeX() + report.getWidth(), all.getRelativeY(), all.getHeight()};
			naturalBarWidth = bar.getWidth();
			org.slf4j.LoggerFactory.getLogger(SquireChatTab.class).info("Squire chat tab: bar width {}, tabs from {} to {}, y {}, height {}, report x {} w {} (xMode {})",
				bar.getWidth(), natural[0], natural[1], natural[2], natural[3], report.getRelativeX(), report.getWidth(), report.getXPositionMode());
		}
		int left = natural[0], right = natural[1];
		int slots = TABS.length + 2;
		int w = (right - left) / slots;
		// Never make things worse: if the numbers look wrong, leave the game's tabs alone and hide ours
		if (w < 30 || w > 120 || natural[3] <= 0)
		{
			restoreGameTabs();
			for (Widget x : new Widget[]{graphic, name, status})
			{
				if (x != null)
				{
					x.setHidden(true);
				}
			}
			return;
		}
		for (int id : TABS)
		{
			remember(id);
		}
		remember(REPORT);
		for (int i = 0; i < TABS.length; i++)
		{
			Widget tab = client.getWidget(TABS[i]);
			if (tab != null)
			{
				place(tab, left + i * w, w);
			}
		}
		int squireX = left + TABS.length * w;
		place(report, squireX + w, right - (squireX + w));

		// The stone, then the status icon and "Squire" side by side, centred
		int y = natural[2], h = natural[3];
		put(graphic, squireX, y, w, h);
		int textWidth = 36;
		int group = ICON + 3 + textWidth;
		int gx = squireX + Math.max(2, (w - group) / 2);
		put(status, gx, y + (h - ICON) / 2, ICON, ICON);
		put(name, gx + ICON + 3, y, Math.min(textWidth + 4, squireX + w - (gx + ICON + 3)), h);
		name.setXTextAlignment(WidgetTextAlignment.LEFT);

		learnSprites();
		// While focused, no game tab looks selected: the Squire stone is
		if (focused && normalSprite >= 0)
		{
			for (int id : TABS)
			{
				Widget g = child(id, 0);
				if (g != null && g.getSpriteId() != normalSprite)
				{
					g.setSpriteId(normalSprite);
				}
			}
		}
	}

	/** "Open Squire panel", with its shortcut in grey (the menu shows it like a hint). */
	private String panelAction()
	{
		String key = panelShortcut.get();
		return "Open Squire panel" + (key == null || key.isEmpty() || key.equals("Not set") ? "" : " <col=9f9f9f>(" + key + " or shift-click)</col>");
	}

	/** The game's stone graphics: the one most tabs use (normal) and the odd one out (the selected tab). */
	private int normalSprite = -1, selectedSprite = -1;

	private void learnSprites()
	{
		Map<Integer, Integer> counts = new HashMap<>();
		for (int id : TABS)
		{
			Widget g = child(id, 0);
			if (g != null && g.getSpriteId() >= 0)
			{
				counts.merge(g.getSpriteId(), 1, Integer::sum);
			}
		}
		if (counts.isEmpty())
		{
			return;
		}
		int best = -1, bestCount = -1;
		for (Map.Entry<Integer, Integer> e : counts.entrySet())
		{
			if (e.getValue() > bestCount)
			{
				best = e.getKey();
				bestCount = e.getValue();
			}
		}
		normalSprite = best;
		for (int sprite : counts.keySet())
		{
			if (sprite != best && !focused)
			{
				selectedSprite = sprite;
			}
		}
	}

	private void refreshStatus()
	{
		if (status == null || name == null)
		{
			return;
		}
		String busy = busyStatus.get();
		int icon = "Observing".equals(busy) ? OBSERVING : busy != null ? THINKING : unread > 0 && !focused ? NEW : READY;
		if (status.getSpriteId() != icon)
		{
			status.setSpriteId(icon);
		}
		name.setTextColor(WHITE);
		if (graphic != null)
		{
			graphic.setAction(2, panelAction());
			graphic.setAction(3, focused ? "Show all chat" : null);
			int sprite = focused && selectedSprite >= 0 ? selectedSprite : normalSprite;
			if (sprite >= 0 && graphic.getSpriteId() != sprite)
			{
				graphic.setSpriteId(sprite);
			}
		}
	}

	/** Draw the status icons (13px pixel art) and register them as sprites. */
	private void addSprites()
	{
		if (spritesAdded)
		{
			return;
		}
		java.util.Map<Integer, net.runelite.api.SpritePixels> overrides = client.getSpriteOverrides();
		overrides.put(READY, net.runelite.client.util.ImageUtil.getImageSpritePixels(chatBubble(), client));
		overrides.put(THINKING, net.runelite.client.util.ImageUtil.getImageSpritePixels(dots(), client));
		overrides.put(OBSERVING, net.runelite.client.util.ImageUtil.getImageSpritePixels(redDot(), client));
		overrides.put(NEW, net.runelite.client.util.ImageUtil.getImageSpritePixels(helmWithBadge(), client));
		spritesAdded = true;
	}

	private void removeSprites()
	{
		if (spritesAdded)
		{
			for (int id : new int[]{READY, THINKING, OBSERVING, NEW})
			{
				client.getSpriteOverrides().remove(id);
			}
			spritesAdded = false;
		}
	}

	private static java.awt.image.BufferedImage canvas()
	{
		return new java.awt.image.BufferedImage(ICON, ICON, java.awt.image.BufferedImage.TYPE_INT_ARGB);
	}

	/** Thinking: three yellow dots with a dark outline. */
	private static java.awt.image.BufferedImage dots()
	{
		java.awt.image.BufferedImage img = canvas();
		java.awt.Graphics2D g = img.createGraphics();
		for (int x : new int[]{0, 5, 10})
		{
			g.setColor(java.awt.Color.BLACK);
			g.fillRect(x, 5, 3, 4);
			g.setColor(new java.awt.Color(YELLOW));
			g.fillRect(x, 5, 3, 3);
		}
		g.dispose();
		return img;
	}

	/** Observing: a red dot, like a recording light. */
	private static java.awt.image.BufferedImage redDot()
	{
		java.awt.image.BufferedImage img = canvas();
		java.awt.Graphics2D g = img.createGraphics();
		g.setColor(java.awt.Color.BLACK);
		g.fillRect(3, 2, 7, 9);
		g.fillRect(2, 3, 9, 7);
		g.setColor(new java.awt.Color(0xE5534B));
		g.fillRect(4, 3, 5, 7);
		g.fillRect(3, 4, 7, 5);
		g.setColor(new java.awt.Color(0xFF8A80));
		g.fillRect(4, 4, 2, 2);
		g.dispose();
		return img;
	}

	/** Ready: a light chat bubble with a dark outline and three dots, with a tail at the bottom left. */
	private static java.awt.image.BufferedImage chatBubble()
	{
		String[] art = {
			".............",
			".###########.",
			"#WWWWWWWWWWW#",
			"#WWWWWWWWWWW#",
			"#WWKWWKWWKWW#",
			"#WWKWWKWWKWW#",
			"#WWWWWWWWWWW#",
			"#WWWWWWWWWWW#",
			".###WW######.",
			"..#WW#.......",
			"..#W#........",
			"..##.........",
			".............",
		};
		java.awt.image.BufferedImage img = canvas();
		for (int y = 0; y < art.length; y++)
		{
			for (int x = 0; x < art[y].length(); x++)
			{
				char c = art[y].charAt(x);
				if (c != '.')
				{
					img.setRGB(x, y, c == '#' ? 0xFF000000 : c == 'K' ? 0xFF3A3A3A : 0xFFE6E6E6);
				}
			}
		}
		return img;
	}

	/** New reply: the chat bubble with an orange badge in the corner. */
	private static java.awt.image.BufferedImage helmWithBadge()
	{
		java.awt.image.BufferedImage img = chatBubble();
		java.awt.Graphics2D g = img.createGraphics();
		g.setColor(java.awt.Color.BLACK);
		g.fillRect(8, 0, 5, 5);
		g.setColor(new java.awt.Color(ORANGE));
		g.fillRect(9, 1, 3, 3);
		g.dispose();
		return img;
	}

	/** The game's own geometry for a tab and its children: {xMode, x, widthMode, width} each. */
	private void remember(int id)
	{
		if (original.containsKey(id))
		{
			return;
		}
		Widget w = client.getWidget(id);
		if (w == null)
		{
			return;
		}
		Widget[] kids = w.getStaticChildren();
		int n = kids == null ? 0 : kids.length;
		int[] g = new int[4 + n * 4];
		store(g, 0, w);
		for (int i = 0; i < n; i++)
		{
			store(g, 4 + i * 4, kids[i]);
		}
		original.put(id, g);
	}

	private static void store(int[] g, int at, Widget w)
	{
		g[at] = w.getXPositionMode();
		g[at + 1] = w.getOriginalX();
		g[at + 2] = w.getWidthMode();
		g[at + 3] = w.getOriginalWidth();
	}

	private static void apply(int[] g, int at, Widget w)
	{
		w.setXPositionMode(g[at]);
		w.setOriginalX(g[at + 1]);
		w.setWidthMode(g[at + 2]);
		w.setOriginalWidth(g[at + 3]);
		w.revalidate();
	}

	/** Put the game's tabs back exactly as the game had them. */
	private void restoreGameTabs()
	{
		for (Map.Entry<Integer, int[]> e : original.entrySet())
		{
			Widget w = client.getWidget(e.getKey());
			if (w == null)
			{
				continue;
			}
			int[] g = e.getValue();
			apply(g, 0, w);
			Widget[] kids = w.getStaticChildren();
			for (int i = 0; kids != null && i < kids.length && 4 + i * 4 < g.length; i++)
			{
				apply(g, 4 + i * 4, kids[i]);
			}
		}
		original.clear();
	}

	/**
	 * Move a tab to x and give it width w. Children that spanned the whole tab (its graphic) get the new width; the
	 * rest keep their own sizing (text lines that follow their parent's width already).
	 */
	private void place(Widget tab, int x, int w)
	{
		if (tab.getRelativeX() == x && tab.getWidth() == w)
		{
			return;
		}
		int oldWidth = tab.getWidth();
		tab.setXPositionMode(WidgetPositionMode.ABSOLUTE_LEFT);
		tab.setWidthMode(WidgetSizeMode.ABSOLUTE);
		tab.setOriginalX(x);
		tab.setOriginalWidth(w);
		Widget[] kids = tab.getStaticChildren();
		if (kids != null)
		{
			for (Widget k : kids)
			{
				if (k.getWidthMode() == WidgetSizeMode.ABSOLUTE && k.getWidth() == oldWidth)
				{
					k.setXPositionMode(WidgetPositionMode.ABSOLUTE_LEFT);
					k.setOriginalX(0);
					k.setOriginalWidth(w);
				}
			}
		}
		tab.revalidate();
		if (kids != null)
		{
			for (Widget k : kids)
			{
				k.revalidate();
			}
		}
	}

	private static void put(Widget w, int x, int y, int width, int height)
	{
		if (w == null)
		{
			return;
		}
		if (w.getOriginalX() != x || w.getOriginalY() != y || w.getOriginalWidth() != width || w.getOriginalHeight() != height || w.isHidden())
		{
			w.setHidden(false);
			w.setXPositionMode(WidgetPositionMode.ABSOLUTE_LEFT);
			w.setYPositionMode(WidgetPositionMode.ABSOLUTE_TOP);
			w.setWidthMode(WidgetSizeMode.ABSOLUTE);
			w.setHeightMode(WidgetSizeMode.ABSOLUTE);
			w.setOriginalX(x);
			w.setOriginalY(y);
			w.setOriginalWidth(width);
			w.setOriginalHeight(height);
			w.revalidate();
		}
	}

	/** A tab's n-th static child (0 = its graphic). */
	private Widget child(int tabId, int n)
	{
		Widget tab = client.getWidget(tabId);
		Widget[] kids = tab == null ? null : tab.getStaticChildren();
		return kids != null && kids.length > n ? kids[n] : null;
	}
}

