	@Override
	protected void shutDown()
	{
		if (chatTab != null)
		{
			SquireChatTab tab = chatTab;
			clientThread.invokeLater(tab::remove);
			chatTab = null;
		}
		clientToolbar.removeNavigation(navButton);
		keyManager.unregisterKeyListener(askHotkey);
		keyManager.unregisterKeyListener(panelHotkey);
		inGameChat = null;
		if (sessions != null)
		{
			sessions.shutdown();
			sessions = null;
		}
		flush();
		AvatarStudio studio = avatarStudio;
		clientThread.invokeLater(studio::cancel);
