	private SquireChatTab chatTab;

	private void updateChatTab()
	{
		if (chatTab == null)
		{
			return;
		}
		if (config.squireChatTab() && isConfigured() && client.getGameState() == GameState.LOGGED_IN)
		{
			chatTab.update();
		}
		else
		{
			chatTab.remove();
		}
