	/** {id, name} for each connected AI app, or null if the server couldn't say. */
	private static List<String[]> connectedAppsOf(AccountApi.Result r)
	{
		if (r.json == null || !r.json.has("apps"))
		{
			return null;
		}
		List<String[]> out = new ArrayList<>();
		for (com.google.gson.JsonElement e : r.json.getAsJsonArray("apps"))
		{
			com.google.gson.JsonObject o = e.getAsJsonObject();
			out.add(new String[]{o.get("id").getAsString(), o.get("name").getAsString()});
		}
		return out;
	}

	private void refreshConnections()
	{
		if (!isConfigured())
		{
			panel.setConnectedApps(List.of());
			return;
		}
		accountApi.connections(r ->
		{
			List<String[]> apps = connectedAppsOf(r);
			if (apps != null)
			{
				panel.setConnectedApps(apps);
			}
		});
	}

	/** The player's own provider keys for the Settings page; the model list follows them. */
	private void refreshKeys()
	{
		models.refresh(options -> SwingUtilities.invokeLater(() -> sessions.forEachView(ChatView::refreshModelLabel)));
		if (!isConfigured())
		{
			panel.setProviderKeys(List.of(), List.of());
			return;
		}
		accountApi.providerKeys(r ->
		{
			if (r.json == null || !r.json.has("keys"))
			{
				return;
			}
			List<String[]> saved = new ArrayList<>();
			for (com.google.gson.JsonElement e : r.json.getAsJsonArray("keys"))
			{
				com.google.gson.JsonObject o = e.getAsJsonObject();
				saved.add(new String[]{o.get("provider").getAsString(), o.get("label").getAsString(), String.valueOf(o.getAsJsonArray("models").size())});
			}
			List<String[]> providers = new ArrayList<>();
			for (com.google.gson.JsonElement e : r.json.getAsJsonArray("providers"))
			{
				com.google.gson.JsonObject o = e.getAsJsonObject();
				providers.add(new String[]{o.get("id").getAsString(), o.get("label").getAsString()});
			}
			panel.setProviderKeys(saved, providers);
		});
	}

	/** Squire's notes about the logged-in account, for the Settings page. */
	private void refreshMemory()
	{
		if (!isConfigured())
		{
			panel.setMemory(List.of());
			return;
		}
		accountApi.notes(r ->
		{
			if (r.json == null || !r.json.has("notes"))
			{
				return;
			}
			List<String[]> out = new ArrayList<>();
			for (com.google.gson.JsonElement e : r.json.getAsJsonArray("notes"))
			{
				com.google.gson.JsonObject o = e.getAsJsonObject();
				boolean done = o.has("done_at") && !o.get("done_at").isJsonNull();
				out.add(new String[]{o.get("id").getAsString(), o.get("kind").getAsString(), o.get("text").getAsString(), done ? "1" : ""});
			}
			panel.setMemory(out);
		});
	}

	/** Today's message count (or unlimited with the player's own key) for the Settings page. */
	private void refreshUsage()
	{
		refreshConnections();
		refreshMemory();
		refreshKeys();
		if (!isConfigured())
		{
			panel.setUsage("Squire is off", false);
			return;
		}
		accountApi.me(r ->
		{
			if (r.json == null)
			{
				panel.setUsage(r.error != null ? r.error : "Unavailable", false);
				return;
			}
			if (r.json.has("admin"))
			{
				panel.setUsage("Unlimited (server owner)", false);
				return;
			}
			if (r.json.has("beta") && r.json.get("beta").isJsonObject())
			{
				com.google.gson.JsonObject beta = r.json.getAsJsonObject("beta");
				panel.setBeta(beta.get("inviteOnly").getAsBoolean(), beta.get("access").getAsBoolean());
			}
			boolean key = r.json.has("personalKey") && r.json.get("personalKey").getAsBoolean();
			int used = r.json.has("used") ? r.json.get("used").getAsInt() : 0;
			int limit = r.json.has("limit") ? r.json.get("limit").getAsInt() : 0;
			panel.setUsage(key ? "Unlimited (your key)" : used + " of " + limit + " free", key);
		});
	}

	/** A key typed into RuneLite's settings goes to the server once (stored encrypted there) and is cleared here. */
	@Subscribe
	public void onConfigChanged(net.runelite.client.events.ConfigChanged event)
	{
		// Pointing at another server, or clearing the token, means signing up again: show Welcome
		if (SquireConfig.GROUP.equals(event.getGroup()) && ("token".equals(event.getKey()) || "endpoint".equals(event.getKey())) && sidebar != null)
		{
			SwingUtilities.invokeLater(() -> sidebar.setTurnedOn(isTurnedOn(), welcome));
		}
		if (SquireConfig.GROUP.equals(event.getGroup()) && "squireChatTab".equals(event.getKey()))
		{
			// Add or remove the tab right away, and let the game lay its own tabs out again
			clientThread.invokeLater(() ->
			{
				updateChatTab();
				client.runScript(net.runelite.api.ScriptID.BUILD_CHATBOX);
			});
		}
		if (!SquireConfig.GROUP.equals(event.getGroup()) || !"gatewayKey".equals(event.getKey()))
		{
			return;
		}
		String key = config.gatewayKey().trim();
		if (key.isEmpty() || accountApi == null || !isConfigured())
		{
			return;
		}
		accountApi.setGatewayKey(key, r ->
		{
			configManager.setConfiguration(SquireConfig.GROUP, "gatewayKey", "");
			panel.setStatus(r.error == null ? "Your AI Gateway key is saved: chat is unlimited." : "Couldn't save your key: " + r.error);
			refreshUsage();
		});
	}

	private void send(Map<String, Object> payload)
	{
		applySyncChoices(payload);
		HttpUrl base = HttpUrl.parse(serverUrl());
		if (base == null)
		{
			log.warn("Squire: invalid server URL {}", serverUrl());
			return;
		}
		HttpUrl url = base.newBuilder().addPathSegments("api/ingest").build();
		Request request = new Request.Builder()
			.url(url)
			.header("Authorization", "Bearer " + config.token().trim())
			.post(RequestBody.create(JSON, gson.toJson(payload)))
			.build();

		inFlight = true;
		okHttpClient.newCall(request).enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				inFlight = false;
				log.warn("Squire: failed to reach server", e);
				panel.setStatus("Couldn't reach the server; will retry.");
				requeue(payload);
			}

			@Override
			public void onResponse(Call call, Response response)
			{
				try (response)
				{
					if (response.isSuccessful())
					{
						writeAccountMd(response.body());
						panel.setStatus("Last synced " + java.time.LocalTime.now().withNano(0) + summarize(payload));
						// Syncs are frequent now; reload the pages when something notable changed, else now and then
						long now = System.currentTimeMillis();
						boolean notable = payload.containsKey("events") || payload.containsKey("killCounts") || payload.containsKey("quests");
						if (notable || now - lastRefreshAt >= REFRESH_EVERY_MS)
						{
							lastRefreshAt = now;
							sidebar.refreshData();
						}
					}
					else
					{
						log.warn("Squire: server returned {}", response.code());
						panel.setStatus("Server returned " + response.code() + (response.code() == 401 ? " (check your ingest token)" : ""));
						if (response.code() >= 500)
						{
							requeue(payload);
						}
					}
				}
				finally
				{
					inFlight = false;
				}
			}
		});
	}
}

