	{
		connect = view;
		body.add(view, Page.CONNECT.name());
	}

	/** Go to a page. Home has no bar (its profile row stands in); the rest get back, title and actions. */
	private void show(Page next)
	{
		if (page == Page.CONNECT && next != Page.CONNECT && connect != null)
		{
			connect.onHidden();
		}
		if (page == Page.SETUP && next != Page.SETUP && setup != null)
		{
			setup.onHidden();
		}
		page = next;
		cards.show(body, next.name());
		nav.setVisible(next != Page.HOME && next != Page.WELCOME);
		List<NavBar.Crumb> ancestors = new ArrayList<>();
		for (Page p = next.parent(); p != null; p = p.parent())
		{
			Page target = p;
			ancestors.add(new NavBar.Crumb(p == Page.HOME ? "Home" : p.title, () -> show(target)));
		}
		List<JButton> actions = new ArrayList<>();
		if (next == Page.CHAT)
		{
			actions.add(newChatButton);
			actions.add(chatMenuButton);
		}
		else if (next == Page.CHATS)
		{
			actions.add(newChatButton);
		}
		nav.set(titleOf(next), ancestors, actions);
		ask.setPlaceholder(placeholderFor(next));
		ask.setVisible(next != Page.CHAT && next != Page.CHATS && next != Page.WELCOME && next != Page.CONNECT && next != Page.SYNC && next != Page.SETUP && next != Page.PROFILE);

		if (next == Page.CHAT)
		{
			sessions.current().refreshModelLabel();
			sessions.current().focusInput();
		}
		else if (next == Page.CHATS)
		{
			history.onShown();
		}
		else if (next == Page.HOME)
		{
			home.onShown();
		}
		else if (next == Page.PLAN)
		{
			home.planView().refresh();
		}
		else if (next == Page.ACTIVITY)
		{
			activity.refresh();
		}
		else if (next == Page.GAINED)
		{
			gained.refresh();
		}
		else if (next == Page.SETTINGS)
		{
			settings.onShown();
		}
		else if (next == Page.SYNC && sync != null)
		{
			sync.onShown();
		}
		else if (next == Page.CONNECT && connect != null)
		{
			connect.onShown();
		}
		else if (next == Page.SETUP && setup != null)
		{
			setup.onShown();
		}
		else if (next == Page.PROFILE && profile != null)
		{
			profile.onShown();
		}
		revalidate();
		repaint();
	}

	/** The floating composer's hint says what it will use: this plan, your progress, your playtime. */
	private String placeholderFor(Page p)
	{
		switch (p)
		{
			case PLAN:
				return home.planView().plan() != null ? "Ask about or change this plan..." : "Ask Squire to make a plan...";
			case PROGRESS:
				return "Ask about your progress...";
			case ACTIVITY:
				return "Ask about your playtime...";
			case GAINED:
				return "Ask about your gains...";
			case PROGRESS_DETAIL:
				return "For fun".equals(progressDetail.pageTitle()) ? "Ask about how you play..." : "Ask about your " + progressDetail.pageTitle().toLowerCase() + "...";
			case BOSS:
				return "Ask about " + boss.pageTitle() + "...";
			default:
				return "Ask anything...";
		}
	}

	/** What a question from the floating composer carries from the page it was asked on. */
	private java.util.List<Attachment> contextFor(Page p)
	{
		Attachment a = p == Page.PLAN ? home.planView().contextAttachment() : p == Page.PROGRESS ? progressView.contextAttachment()
			: p == Page.BOSS ? boss.contextAttachment() : null;
		return a == null ? java.util.List.of() : java.util.List.of(a);
	}

	private String titleOf(Page p)
	{
		switch (p)
		{
			case CHAT:
				return sessions.current().title();
			case PROGRESS_DETAIL:
				return progressDetail.pageTitle();
			case BOSS:
				return boss.pageTitle();
			default:
				return p.title;
		}
	}

	/** A boss's page; back goes to every kill count. */
	private void openBoss(String name)
	{
		if (!"kill-counts".equals(progressDetail.view()))
		{
			progressDetail.show("kill-counts", "Kill counts");
		}
		boss.show(name);
		show(Page.BOSS);
	}

	/**
	 * Send from the floating composer: start a new chat, switch to it, and let the floating box glide down into the
	 * chat's composer.
	 */
	private void askFromFloating(String text)
	{
		Rectangle from = ask.isDisplayable() && ask.isVisible() ? ask.boxBoundsIn(this) : null;
		ask.clear();
		// The page's context (the plan, your progress) goes along as a tile on the message
		sessions.startWith(text, contextFor(page));
		show(Page.CHAT);
		validate();
		ChatView chat = sessions.current();
		Rectangle to = chat.isDisplayable() ? chat.composerBoundsIn(this) : null;
		chat.setComposerHidden(true);
		ComposerTransition.play(this, from, to, text, () ->
		{
			chat.setComposerHidden(false);
			chat.focusInput();
		});
	}

	/** The floating composer (previews). */
	FloatingAsk floatingAsk()
	{
		return ask;
	}

	/** The chat's "..." menu: copy its ID or the whole conversation, or delete it. */
	private void showChatMenu()
	{
		ChatView chat = sessions.current();
		JPopupMenu menu = new JPopupMenu();
		JMenuItem copyId = new JMenuItem("Copy chat ID");
		copyId.addActionListener(e -> copy(chat.id()));
		JMenuItem copyText = new JMenuItem("Copy conversation");
		copyText.addActionListener(e -> copy(chat.transcript()));
		copyText.setEnabled(chat.hasConversation());
		JMenuItem delete = new JMenuItem("Delete chat");
		delete.setEnabled(chat.hasConversation());
		delete.addActionListener(e ->
		{
			int answer = JOptionPane.showConfirmDialog(this, "Delete \"" + chat.title() + "\"? This can't be undone.",
				"Delete chat", JOptionPane.OK_CANCEL_OPTION, JOptionPane.WARNING_MESSAGE);
			if (answer == JOptionPane.OK_OPTION)
			{
				sessions.delete(chat.id());
				show(Page.CHATS);
			}
		});
		for (JMenuItem item : new JMenuItem[]{copyId, copyText, delete})
		{
			item.setFont(FontManager.getRunescapeFont());
		}
		menu.add(copyId);
		menu.add(copyText);
		menu.addSeparator();
		menu.add(delete);
		menu.show(chatMenuButton, chatMenuButton.getWidth() - menu.getPreferredSize().width, chatMenuButton.getHeight());
	}

	private static void copy(String text)
	{
		Toolkit.getDefaultToolkit().getSystemClipboard().setContents(new StringSelection(text), null);
	}

	/** Refetch what Home and the open page show (e.g. after a sync). */
	void refreshData()
	{
		home.refresh();
		if (page == Page.ACTIVITY)
		{
			activity.refresh();
		}
		else if (page == Page.GAINED)
		{
			gained.refresh();
		}
		else if (page == Page.PROGRESS_DETAIL)
		{
			progressDetail.refresh();
		}
		else if (page == Page.BOSS)
		{
			boss.refresh();
		}
	}

	HomeView home()
	{
		return home;
	}

	/** For previews: the Progress detail and boss pages. */
	ProgressDetailView progressDetail()
	{
		return progressDetail;
	}

	BossView boss()
	{
		return boss;
	}

	/** For previews: open a page by name ("home", "progress", "activity", "chat" or "settings"). */
	void showPage(String name)
	{
		show(Page.valueOf(name.toUpperCase()));
	}

	// ---- Width

	@Override
	public Dimension getPreferredSize()
	{
		return new Dimension(panelWidth, super.getPreferredSize().height);
	}

	@Override
	public Dimension getMinimumSize()
	{
		return new Dimension(panelWidth, super.getMinimumSize().height);
	}

	private static int clamp(int w)
	{
		return Math.max(MIN_WIDTH, Math.min(MAX_WIDTH, w));
	}

	void setPanelWidth(int w)
	{
		int next = clamp(w);
		if (next == panelWidth)
		{
			return;
		}
		panelWidth = next;
		// RuneLite sizes the sidebar to the selected panel, so relayout up to the window
		JTabbedPane sidebar = (JTabbedPane) SwingUtilities.getAncestorOfClass(JTabbedPane.class, this);
		if (sidebar != null)
		{
			sidebar.revalidate();
		}
		revalidate();
		Window window = SwingUtilities.getWindowAncestor(this);
		if (window != null)
		{
			window.validate();
		}
		repaint();
	}

	/** A few pixels on the left edge drag to resize; double-click resets to the default width. */
	private void installResizeGrip()
	{
		MouseAdapter grip = new MouseAdapter()
		{
			private int startX;
			private int startWidth;
			private boolean dragging;

			private boolean onGrip(MouseEvent e)
			{
				return e.getX() <= GRIP;
			}

			@Override
			public void mouseMoved(MouseEvent e)
			{
				boolean on = onGrip(e);
				setCursor(on ? Cursor.getPredefinedCursor(Cursor.W_RESIZE_CURSOR) : Cursor.getDefaultCursor());
				if (on != gripActive)
				{
					gripActive = on;
					repaint(0, 0, GRIP, getHeight());
				}
			}

			@Override
			public void mouseExited(MouseEvent e)
			{
				if (!dragging)
				{
					gripActive = false;
					setCursor(Cursor.getDefaultCursor());
					repaint(0, 0, GRIP, getHeight());
				}
			}

			@Override
			public void mousePressed(MouseEvent e)
			{
				if (onGrip(e))
				{
					dragging = true;
					startX = e.getXOnScreen();
					startWidth = panelWidth;
				}
			}

			@Override
			public void mouseDragged(MouseEvent e)
			{
				if (dragging)
				{
					// The panel sits on the right, so dragging left makes it wider
					setPanelWidth(startWidth + (startX - e.getXOnScreen()));
				}
			}

			@Override
			public void mouseReleased(MouseEvent e)
			{
				if (dragging)
				{
					dragging = false;
					onWidthChosen.accept(panelWidth);
				}
			}

			@Override
			public void mouseClicked(MouseEvent e)
			{
				if (onGrip(e) && e.getClickCount() == 2)
				{
					setPanelWidth(DEFAULT_WIDTH);
					onWidthChosen.accept(panelWidth);
				}
			}
		};
		addMouseListener(grip);
		addMouseMotionListener(grip);
		setToolTipText(null);
	}

	@Override
	protected void paintComponent(Graphics g)
	{
		super.paintComponent(g);
		if (gripActive)
		{
			g.setColor(ChatComponents.BORDER);
			g.fillRect(0, 0, 2, getHeight());
		}
	}

	@Override
	public void onActivate()
	{
		if (page == Page.CHAT)
		{
			sessions.current().focusInput();
		}
		else if (page == Page.HOME)
		{
			home.onShown();
		}
	}
}

package com.squire;

import java.awt.AlphaComposite;
import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.geom.Ellipse2D;
import java.awt.geom.Path2D;
import java.awt.image.BaseMultiResolutionImage;
import java.awt.image.BufferedImage;
import java.io.IOException;
import java.io.InputStream;
import java.nio.charset.StandardCharsets;
import java.util.HashMap;
import java.util.Map;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import javax.swing.ImageIcon;

/**
 * Renders the plugin's SVG icons without an SVG library: our own (exported from the Figma design) and Pixelarticons
 * (pixelarticons.com, MIT). Supports what those use: paths with M/L/H/V/Z commands (absolute or relative), circles,
 * fill colours ("currentColor" draws in the default icon grey) and opacity.
 */
final class SvgIcon
{
	private static final Pattern VIEWBOX = Pattern.compile("viewBox=\"([\\d.\\s-]+)\"");
	private static final Pattern PATH = Pattern.compile("<path([^>]*)/?>");
	/** The grey our icons are drawn in when they don't say (Pixelarticons use currentColor). */
	private static final Color DEFAULT = Tokens.COLOR_TEXT_SECONDARY;
	private static final Pattern CIRCLE = Pattern.compile("<circle([^>]*)/?>");
	private static final Pattern ATTR = Pattern.compile("(\\w+)=\"([^\"]*)\"");
	private static final Pattern TOKEN = Pattern.compile("[MLHVZmlhvz]|-?\\d*\\.?\\d+(?:e-?\\d+)?");
	private static final Map<String, String> CACHE = new HashMap<>();

	/**
	 * Load an icon from resources, drawn at `height` pixels tall (width follows the viewBox), optionally recoloured.
	 * Includes a 2x rendering so it stays sharp on HiDPI displays.
	 */
	static ImageIcon load(String name, int height, Color tint)
	{
		String svg = source(name);
		return new ImageIcon(new BaseMultiResolutionImage(render(svg, height, tint), render(svg, height * 2, tint)));
	}

	static String source(String name)
	{
		return CACHE.computeIfAbsent(name, n ->
		{
			try (InputStream in = SvgIcon.class.getResourceAsStream("icons/" + n + ".svg"))
			{
				if (in == null)
				{
					throw new IllegalStateException("Missing icon " + n);
				}
				return new String(in.readAllBytes(), StandardCharsets.UTF_8);
			}
			catch (IOException e)
			{
				throw new IllegalStateException(e);
			}
		});
	}

	static BufferedImage render(String svg, int height, Color tint)
	{
		Matcher vb = VIEWBOX.matcher(svg);
		double vbW = 12, vbH = 12;
		if (vb.find())
		{
			String[] p = vb.group(1).trim().split("\\s+");
			vbW = Double.parseDouble(p[2]);
			vbH = Double.parseDouble(p[3]);
		}
		double scale = height / vbH;
		int width = Math.max(1, (int) Math.round(vbW * scale));
		BufferedImage img = new BufferedImage(width, height, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = img.createGraphics();
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g.scale(scale, scale);

		java.util.List<Path2D> paths = new java.util.ArrayList<>();
		java.util.List<Color> colors = new java.util.ArrayList<>();
		Matcher pm = PATH.matcher(svg);
		while (pm.find())
		{
			Map<String, String> a = attrs(pm.group(1));
			if (a.containsKey("d"))
			{
				paths.add(path(a.get("d")));
				colors.add(tint != null ? tint : color(a.getOrDefault("fill", "currentColor")));
			}
		}
		// Pixelarticons draw 2-unit pixels on a 24 grid, some starting on odd units: shift those a unit so every
		// pixel lands on the 12-cell grid our 16px icons use, keeping edges as sharp as our own icons.
		if (vbW == 24 && vbH == 24)
		{
			g.translate(snap(paths, true), snap(paths, false));
		}
		for (int i = 0; i < paths.size(); i++)
		{
			g.setColor(colors.get(i));
			g.fill(paths.get(i));
		}
		Matcher cm = CIRCLE.matcher(svg);
		while (cm.find())
		{
			Map<String, String> a = attrs(cm.group(1));
			double r = Double.parseDouble(a.getOrDefault("r", "0"));
			double cx = Double.parseDouble(a.getOrDefault("cx", "0"));
			double cy = Double.parseDouble(a.getOrDefault("cy", "0"));
			float opacity = Float.parseFloat(a.getOrDefault("opacity", "1"));
			g.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, opacity));
			g.setColor(tint != null ? tint : color(a.getOrDefault("fill", "#000000")));
			g.fill(new Ellipse2D.Double(cx - r, cy - r, r * 2, r * 2));
			g.setComposite(AlphaComposite.SrcOver);
		}
		g.dispose();
		return img;
	}

	private static Map<String, String> attrs(String s)
	{
		Map<String, String> out = new HashMap<>();
		Matcher m = ATTR.matcher(s);
		while (m.find())
		{
			out.put(m.group(1), m.group(2));
		}
		return out;
	}

	/** -1 or +1 when every vertex sits on an odd coordinate along this axis, else 0. */
	private static int snap(java.util.List<Path2D> paths, boolean horizontal)
	{
		double min = Double.MAX_VALUE;
		for (Path2D p : paths)
		{
			double[] c = new double[6];
			for (java.awt.geom.PathIterator it = p.getPathIterator(null); !it.isDone(); it.next())
			{
				if (it.currentSegment(c) == java.awt.geom.PathIterator.SEG_CLOSE)
				{
					continue;
				}
				double v = horizontal ? c[0] : c[1];
				if (v != Math.floor(v) || ((long) v) % 2 == 0)
				{
					return 0;
				}
				min = Math.min(min, v);
			}
		}
		return min == Double.MAX_VALUE ? 0 : min >= 1 ? -1 : 1;
	}

	private static Color color(String c)
	{
		if (c == null || "currentColor".equals(c) || "none".equals(c))
		{
			return DEFAULT;
		}
		if ("white".equals(c))
		{
			return Color.WHITE;
		}
		if ("black".equals(c))
		{
			return Color.BLACK;
		}
		return Color.decode(c);
	}

	private static Path2D path(String d)
	{
		Path2D.Double p = new Path2D.Double(Path2D.WIND_NON_ZERO);
		Matcher m = TOKEN.matcher(d);
		String cmd = "M";
		double x = 0, y = 0, startX = 0, startY = 0;
		java.util.List<String> tokens = new java.util.ArrayList<>();
		while (m.find())
		{
			tokens.add(m.group());
		}
		for (int i = 0; i < tokens.size(); )
		{
			String t = tokens.get(i);
			if (t.matches("[A-Za-z]"))
			{
				cmd = t;
				i++;
				if (cmd.equalsIgnoreCase("Z"))
				{
					p.closePath();
					x = startX;
					y = startY;
				}
				continue;
			}
			// Lower-case commands are relative to the current point
			boolean rel = Character.isLowerCase(cmd.charAt(0));
			switch (cmd.toUpperCase())
			{
				case "M":
					x = (rel ? x : 0) + Double.parseDouble(tokens.get(i++));
					y = (rel ? y : 0) + Double.parseDouble(tokens.get(i++));
					p.moveTo(x, y);
					startX = x;
					startY = y;
					cmd = rel ? "l" : "L"; // subsequent pairs are line-tos
					break;
				case "L":
					x = (rel ? x : 0) + Double.parseDouble(tokens.get(i++));
					y = (rel ? y : 0) + Double.parseDouble(tokens.get(i++));
					p.lineTo(x, y);
					break;
				case "H":
					x = (rel ? x : 0) + Double.parseDouble(tokens.get(i++));
					p.lineTo(x, y);
					break;
				case "V":
					y = (rel ? y : 0) + Double.parseDouble(tokens.get(i++));
					p.lineTo(x, y);
					break;
				default:
					i++; // unsupported command in these icons; skip its argument
			}
		}
		return p;
	}

	private SvgIcon()
	{
	}
}

package com.squire;

import com.squire.ChatComponents.Align;
import com.squire.ChatComponents.MessageList;
import com.squire.ChatComponents.Surface;
import com.squire.WelcomeView.Wrapped;
import java.awt.BorderLayout;
import java.util.List;
import javax.swing.BorderFactory;
import javax.swing.JComponent;
import javax.swing.JLabel;
import javax.swing.JOptionPane;
import javax.swing.JPanel;
import javax.swing.JScrollPane;
import javax.swing.ScrollPaneConstants;

/**
 * Settings, What's synced: turn each kind of data on or off, and hide individual items. Turning something off
 * stops the plugin sending it and removes what the server already has; hiding an item does the same for that item.
 */
class SyncView extends JPanel
{
	interface Controller
	{
		boolean isOn(String key);

		/** Turn a kind on or off (off also forgets it on the server). */
		void set(String key, String kind, boolean on);

		List<String> hidden();

		void hide(String item, boolean hide);
	}

	/** {config key, server kind, label, what it's for} */
	private static final String[][] KINDS = {
		{"syncBank", "bank", "Bank", "Your bank's items and value"},
		{"syncWorn", "worn", "Inventory and equipment", "What you carry and wear"},
		{"syncStorage", "storage", "Other storage", "Looting bag, rune pouch, seed vault, house"},
		{"syncLocation", "location", "Location and world", "For answers about where you are"},
		{"syncLoot", "loot", "Loot drops", "Loot history and drop luck"},
		{"syncActivity", "activity", "What you're doing", "Time played by monster and skill"},
		{"syncClog", "clog", "Collection log", "Your collection log slots"},
	};

	private final Controller controller;
	private final MessageList list = new MessageList(null, 0);

	SyncView(Controller controller)
	{
		super(new BorderLayout());
		this.controller = controller;
		setOpaque(false);
		list.setBorder(BorderFactory.createEmptyBorder(1, 1, 16, 1));
		JScrollPane scroll = new JScrollPane(list);
		scroll.setOpaque(false);
		scroll.getViewport().setOpaque(false);
		scroll.setBorder(BorderFactory.createEmptyBorder());
		scroll.setHorizontalScrollBarPolicy(ScrollPaneConstants.HORIZONTAL_SCROLLBAR_NEVER);
		scroll.getVerticalScrollBar().setUnitIncrement(16);
		add(scroll);
		render();
	}

	void onShown()
	{
		render();
	}

	private void render()
	{
		list.removeAll();
		Wrapped intro = new Wrapped("Choose what Squire syncs. Turning something off stops sending it and removes what "
			+ "the server already has. Your levels, quests, diaries and kill counts are always synced: they're what Squire "
			+ "needs to help.", ChatComponents.MUTED, false);
		intro.setBorder(BorderFactory.createEmptyBorder(0, 11, 0, 11));
		list.add(ChatComponents.place(intro, Align.FILL, 6));

		list.add(ChatComponents.place(title("Synced"), Align.LEFT, 16));
		Surface kinds = HomeView.listCard();
		for (int i = 0; i < KINDS.length; i++)
		{
			String[] k = KINDS[i];
			if (i > 0)
			{
				kinds.add(HomeView.divider());
			}
			boolean on = controller.isOn(k[0]);
			JComponent row = HomeView.listRow(null, k[2], new ChatComponents.Switch(on), () ->
			{
				if (on)
				{
					int answer = JOptionPane.showConfirmDialog(this,
						"Stop syncing " + k[2].toLowerCase() + "? Squire will also forget what it already has.",
						"What's synced", JOptionPane.OK_CANCEL_OPTION, JOptionPane.QUESTION_MESSAGE);
					if (answer != JOptionPane.OK_OPTION)
					{
						return;
					}
				}
				controller.set(k[0], k[1], !on);
				render();
			});
			row.setToolTipText(k[3]);
			kinds.add(row);
		}
		list.add(ChatComponents.place(kinds, Align.FILL, 6));

		list.add(ChatComponents.place(title("Hidden items"), Align.LEFT, 18));
		Surface hidden = HomeView.listCard();
		for (String item : controller.hidden())
		{
			JComponent row = HomeView.listRow(null, item, Ui.text("Show", ChatComponents.MUTED), () ->
			{
				controller.hide(item, false);
				render();
			});
			row.setToolTipText("Sync " + item + " again");
			hidden.add(row);
			hidden.add(HomeView.divider());
		}
		JComponent add = HomeView.listRow(null, "Hide an item", new JLabel(SvgIcon.load("chevron-right", 16, null)), () ->
		{
			String name = JOptionPane.showInputDialog(this, "Item name, exactly as in game (e.g. Twisted bow):", "Hide an item", JOptionPane.PLAIN_MESSAGE);
			if (name != null && !name.isBlank())
			{
				controller.hide(name.trim(), true);
				render();
			}
		});
		add.setToolTipText("Never sync this item, and remove it from the server");
		hidden.add(add);
		list.add(ChatComponents.place(hidden, Align.FILL, 6));
		list.revalidate();
		list.repaint();
	}

	private static JLabel title(String text)
	{
		JLabel l = Ui.bold(text);
		l.setBorder(BorderFactory.createEmptyBorder(0, 11, 0, 0));
		return l;
	}
}

