	private static void render(Component c, File file) throws Exception
	{
		int w = Integer.getInteger("preview.width", c.getPreferredSize().width);
		int h = Integer.getInteger("preview.height", 620);
		int scale = Integer.getInteger("preview.scale", 2);
		// Lay out inside an undisplayed frame so fonts and HTML views resolve
		JFrame frame = new JFrame();
		frame.setUndecorated(true);
		frame.setContentPane((Container) c);
		frame.setSize(w, h);
		frame.addNotify();
		frame.validate();
		for (int i = 0; i < 3; i++)
		{
			validateTree((Container) c);
		}
		BufferedImage img = new BufferedImage(w * scale, h * scale, BufferedImage.TYPE_INT_RGB);
		Graphics2D g = img.createGraphics();
		g.scale(scale, scale);
		g.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_ON);
		c.paint(g);
		g.dispose();
		ImageIO.write(img, "png", file);
		frame.setContentPane(new javax.swing.JPanel());
		frame.dispose();
	}

	private static void renderSized(Component c, File file, int w, int h) throws Exception
	{
		System.setProperty("preview.width", String.valueOf(w));
		System.setProperty("preview.height", String.valueOf(h));
		render(c, file);
		System.clearProperty("preview.width");
		System.clearProperty("preview.height");
	}

	private static void validateTree(Container c)
	{
		c.invalidate();
		c.validate();
		for (Component child : c.getComponents())
		{
			if (child instanceof Container)
			{
				((Container) child).doLayout();
			}
		}
	}
}

package com.squire;

import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import java.io.File;
import javax.imageio.ImageIO;

/** Renders a saved player model at a few framings, side by side, to tune the Home portrait without the game. */
public class PortraitTune
{
	public static void main(String[] args) throws Exception
	{
		PlayerPortrait.Mesh mesh;
		try (java.io.Reader r = java.nio.file.Files.newBufferedReader(new File(args[0]).toPath()))
		{
			mesh = PlayerPortrait.load(r, new com.google.gson.Gson());
		}
		if (args.length > 1)
		{
			// Redraw the saved portrait with the current framing
			ImageIO.write(PlayerPortrait.draw(mesh, 128, PlayerPortrait.DEFAULT_FRAMING), "png", new File(args[1]));
			System.out.println("wrote " + args[1]);
			return;
		}
		float minY = Float.MAX_VALUE, maxY = -Float.MAX_VALUE, minX = Float.MAX_VALUE, maxX = -Float.MAX_VALUE;
		for (int i = 0; i < mesh.vx.length; i++)
		{
			minY = Math.min(minY, mesh.vy[i]);
			maxY = Math.max(maxY, mesh.vy[i]);
			minX = Math.min(minX, mesh.vx[i]);
			maxX = Math.max(maxX, mesh.vx[i]);
		}
		System.out.printf("vertices %d faces %d  y %.0f..%.0f  x %.0f..%.0f  textures %s%n",
			mesh.vx.length, mesh.faceCount(), minY, maxY, minX, maxX, mesh.texels.keySet());

		float[][] crops = {{-202, -140}, {-204, -134}, {-206, -128}, {-200, -144}};
		double[] yaws = {-22, -30};
		int size = 128, pad = 8;
		BufferedImage sheet = new BufferedImage(crops.length * (size + pad) + pad, yaws.length * (size + pad) + pad, BufferedImage.TYPE_INT_RGB);
		Graphics2D g = sheet.createGraphics();
		g.setColor(new Color(0x1e1e1e));
		g.fillRect(0, 0, sheet.getWidth(), sheet.getHeight());
		for (int r = 0; r < yaws.length; r++)
		{
			for (int c = 0; c < crops.length; c++)
			{
				PlayerPortrait.Framing f = new PlayerPortrait.Framing(crops[c][0], crops[c][1], Math.toRadians(yaws[r]));
				BufferedImage img = PlayerPortrait.draw(mesh, size, f);
				g.drawImage(img, pad + c * (size + pad), pad + r * (size + pad), null);
			}
		}
		g.dispose();
		File out = new File("build/preview/portrait-tune.png");
		out.getParentFile().mkdirs();
		ImageIO.write(sheet, "png", out);
		System.out.println("wrote " + out);
	}
}

package com.squire;

/** Prints the starters for a few situations: ./gradlew scenariosCheck */
public class ScenariosCheck
{
	public static void main(String[] args)
	{
		long now = System.currentTimeMillis();
		Scenarios.Snapshot idle = new Scenarios.Snapshot();
		show("Idle, nothing happening", idle);

		Scenarios.Snapshot boss = new Scenarios.Snapshot();
		boss.fighting = "Vorkath";
		boss.activity = "Vorkath";
		boss.slayerTask = "BLUE DRAGONS";
		boss.slayerLeft = 112;
		boss.hitpoints = 0.3;
		show("Fighting Vorkath, low HP, blue dragon task", boss);

		Scenarios.Snapshot skilling = new Scenarios.Snapshot();
		skilling.activity = "Woodcutting";
		skilling.activityLevel = 72;
		skilling.levelledSkill = "Woodcutting";
		skilling.levelledTo = 72;
		skilling.levelledAt = now - 60_000;
		show("Just hit 72 Woodcutting while chopping", skilling);

		Scenarios.Snapshot drop = new Scenarios.Snapshot();
		drop.accountType = "IRONMAN";
		drop.lootItem = "Tanzanite fang";
		drop.lootSource = "Zulrah";
		drop.lootAt = now - 30_000;
		drop.bankOpen = true;
		show("Ironman, fang drop, bank open", drop);

		Scenarios.Snapshot stale = new Scenarios.Snapshot();
		stale.levelledSkill = "Agility";
		stale.levelledTo = 60;
		stale.levelledAt = now - 3_600_000;
		stale.clueTier = "hard";
		stale.wildernessLevel = 12;
		stale.questInProgress = "Dragon Slayer II";
		show("An hour-old level, hard clue, wilderness 12, in DS2", stale);
	}

	private static void show(String label, Scenarios.Snapshot s)
	{
		System.out.println(label + ":");
		for (Scenarios.Prompt p : Scenarios.suggest(s))
		{
			System.out.println("  - " + p.title + "   // " + p.prompt);
		}
		if (Scenarios.suggest(s).isEmpty())
		{
			System.out.println("  (none: falls back to account-based starters)");
		}
	}
}

